quests[14449] = { id = 14449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erste Schritt", description = "Was Ihr hier seht, ist das Werk der Stacheleber, mein Kind. Jahr für Jahr sind sie in unser Dorf eingefallen. Durch den großen Kataklysmus sind sie nun aus ihren Dornen hervorgekommen und haben sich wie Heuschrecken im ganzen Land breitgemacht. Das Ergebnis sieht man nur allzu gut; selbst meine Mutter starb aufgrund ihrer Wildheit.\n\nHeute ist der Tag, an dem Ihr Eure Volljährigkeit erreicht. Heute ist der Tag, an dem Ihr Eure Waffe nehmen, für den Klan kämpfen und Großmutter Falkenwind rächen werdet. Folgt dem Weg nach Osten - dort werdet Ihr meinen Sohn Grull finden. Er wird Euch bei Eurem Angriff auf die Stacheleber anführen.", sourceObjective = "Folgt dem Weg, der aus Camp Narache nach Osten führt, und sucht Grull Falkenwind auf.", completion = "Willkommen zu Eurer ersten richtigen Prüfung als {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14450] = { id = 14450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randomdrop-Test Progressiv", description = "Diese Quest testet Zufallsdrops mit progressiver Prozentzahl für Drops.", sourceObjective = "Beschafft 10 progressive Dingse.", sourceObjectiveStatus = "unverified-source-field" }
quests[14451] = { id = 14451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randomdrop-Test FlatRate", description = "Diese Quest testet Zufallsdrops mit Flatrate-Prozentzahl für Drops.", sourceObjective = "Beschafft 10 Flatratedingse.", sourceObjectiveStatus = "unverified-source-field" }
quests[14452] = { id = 14452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Kraft", description = "Merkt auf, {name}. Allein schon die Anwesenheit der Borstennacken macht diesen Ort zu einem Schandfleck. Wo sie sind, bleibt nichts übrig außer Leichen und Brachland. In Camp Narache könnte es in nur wenigen Tagen genau so aussehen wie hier, wenn wir nicht standhaft bleiben und kämpfen.\n\nDies wird Euer Ritus der Kraft - die erste Zeremonie, die einem Kriegerhelden der Tauren gewährt wird. Begebt Euch ins Herz von Dornknoten und tötet die Stacheleber der Borstennacken. Kehrt daraufhin zu mir zurück.", sourceObjective = "Tötet 6 Eindringlinge der Borstennacken.", completion = "Ihr habt gut gekämpft, {name}. Wir können vielleicht noch gerettet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14453] = { id = 14453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bescheidene Bitte", description = "Alle Mitglieder des Stammes teilen die Harmonie des Lebens miteinander. Wir leben und arbeiten zusammen.\n\nMit der Verpflichtung, füreinander da zu sein, haben wir eine große Verantwortung übernommen. Ich habe eine bescheidene Bitte an Euch.\n\nMeine Mutter ist heute Morgen fortgegangen, um Wasser aus dem Brunnen südöstlich von Narache zu holen. Das ist jetzt schon eine Weile her. Würdet Ihr wohl an meiner Stelle nach ihr sehen, während ich mich hier um Stammesangelegenheiten kümmere?", sourceObjective = "Häuptling Falkenwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[14454] = { id = 14454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Krieger", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Kriegerheld Scharfhorn, einen jungen Kriegerlehrer, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen Schlüssel für den Käfig und befreit ihn!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Kriegerheld Scharfhorn gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[14455] = { id = 14455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Dornenrufer auf", description = "Die Eigenheiten seiner Beute zu kennen ist ein sehr wichtiger Aspekt bei der Jagd. In ihrer Heimat leben die Stacheleber in den Schatten und im Schutz großer Dornenwurzeln. Wenn sie unterwegs sind, pflanzen die Schamanen Samen, um neue Dornenbehausungen wachsen zu lassen.\n\nDiese Dornen schädigen das Land und entziehen allen anderen Pflanzen das Leben, so dass ein Brachland entsteht. Reist nach Süden und haltet die Dornenrufer auf, bevor sie noch mehr Land zerstören können, {name}.", sourceObjective = "Tötet 7 Dornenrufer der Borstennacken.", completion = "Nun, da die Dornenrufer tot sind, wird die Erdenmutter ihre eigenen Wunden selbst heilen können. Die Wurzeln sind nicht für diesen Ort bestimmt und werden eingehen. Das Gleichgewicht wird wieder hergestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14456] = { id = 14456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus des Muts", description = "Etwas, das Ihr bereits sehr früh erlernen müsst, ist, Eure Beute nie zu unterschätzen, {name}.\n\nWährend wir durch die Angriffe in Camp Narache abgelenkt waren, haben einige Borstennacken sich unbemerkt angeschlichen und eine Kiste mit Gewehren geklaut. Ihr könnt von hier aus sehen, wie sie im Süden nun die Luft mit Blei füllen.\n\nDies wird Euer Ritus des Muts: Stellt Euch dem Regen der Gewehrschüsse, jagt die Waffendiebe der Borstennacken und bringt uns unsere Gewehre zurück.", sourceObjective = "Holt 7 gestohlene Gewehre von den Waffendieben der Borstennacken zurück.", progress = "Wie viele der gestohlenen Gewehre konntet Ihr an Euch bringen, Initiand?", completion = "Gut gemacht, {name}. Zeigt Respekt vor Eurer Beute und der Gefahr, die mit ihr verbunden ist, aber fürchtet sie nicht. Wer Furcht zeigt, wird selbst zur Beute.", sourceObjectiveStatus = "unverified-source-field" }
quests[14457] = { id = 14457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan der Sonnenhäscher", description = "Einer meiner Kontakte in den Kanälen der Schattenseite hat in der Nähe des Schwarzmarktes einen Agenten der Sonnenhäscher erblickt. Die Sonnenhäscher sind normalerweise nicht dafür bekannt, ein Interesse am dortigen Treiben zu hegen, was also sehr stark darauf hindeutet, dass sie etwas vorhaben.\n\nBegebt Euch zur Schattenseite, spürt diesen Agenten auf und kümmert Euch um ihn. Durchsucht ihn nach allen Informationen, die uns einen Hinweis über den Verbleib dieses Folianten vom Wyrmruhtempel liefern könnten. Wir können nicht zulassen, dass sie ihn zuerst zurück nach Eiskrone bringen.", sourceObjective = "Gelangt an die Befehle der Sonnenhäscher.", progress = "Habt Ihr irgendetwas Brauchbares bei dem Agenten finden können?", completion = "<Arkanist Tybalin sieht sich die gefundenen Befehle genauer an.>\n\nDer Agent, den Ihr abgefangen habt, sollte, nachdem er sich mit einem gewissen Magister Hathorel in Sonnenhäschers Zuflucht getroffen hat, den Folianten nach Eiskrone bringen. Wir müssen dieses Buch bekommen, {name}, und das ist unsere Chance. Es wird jedoch nicht einfach sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14458] = { id = 14458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Adana auf", description = "Wir konnten gegen die Borstennacken hier einiges ausrichten. Ich werde hier bleiben und das Gebiet sichern, aber Ihr müsst weiterreisen.\n\nSucht Adana Donnerhorn auf; sie ist mit ein paar Kriegerhelden nach Südwesten aufgebrochen, um den Rest der Borstennacken auszumerzen.", sourceObjective = "Sucht Adana Donnerhorn im Südwesten auf.", completion = "Es liegen noch weitere Prüfungen vor Euch, {name}. Ich hoffe, Ihr seid gut vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14459] = { id = 14459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kampfeber", description = "Es gibt noch mehr Gefahren, um die wir uns kümmern müssen. Die Borstennacken zähmen wilde Eber und bilden sie zu Kampfebern aus, die im Kampf gegen uns genutzt werden sollen.\n\nDiese gepanzerten Kampfeber wurden ohne Hoffnung auf jegliche Erholung gequält und missbraucht. Sie müssen getötet werden, im Namen unserer Sicherheit und ihres Friedens. Begebt Euch zu den Pferchen im Süden und tötet die Eber, {name}. Kehrt danach wieder zu mir zurück.", sourceObjective = "Tötet 10 gepanzerte Kampfeber.", completion = "Gute Arbeit, {name}. Diese Bestien hätten eine größere Bedrohung als die Borstennacken selbst darstellen können, wenn wir uns nicht rechtzeitig um das Problem gekümmert hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14460] = { id = 14460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Ehre", description = "Diese Stacheleber unterstehen Häuptling Quieker Dornmantel. Er war es, der beim Angriff auf Camp Narache das Leben von Großmutter Falkenwind genommen hat. Nach dieser grauenvollen Tat ist er geflohen und hat sich versteckt, aber wir haben ihn ausfindig gemacht. Er befindet sich westlich von hier in einem garstigen Dornennest und schafft es, alle Kriegerhelden abzuwehren, die wir schicken, um sich seiner anzunehmen.\n\nIhr habt Euch als mutiger Verteidiger unseres Volkes herausgestellt, {name}. Tötet Dornmantel und bringt Häuptling Falkenwind seine Mähne, um Großmutter Falkenwind zu ehren!", sourceObjective = "Tötet Häuptling Quieker Dornmantel.", progress = "Habt Ihr Eure Prüfungen abgeschlossen, Kind?", completion = "<Häuptling Falkenwind hält die Mähne von Dornenmantel über seinen Kopf.>\n\nDer Häuptling der Borstennacken ist gefallen. Der Geist von Großmutter Falkenwind wurde gerächt!", sourceObjectiveStatus = "unverified-source-field" }
quests[14461] = { id = 14461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futter des Bösen", description = "Wir müssen weitaus mehr tun, als nur Eber zu jagen. Der Anblick dieses Landes bereitet Augenschmerzen, und das muss geändert werden.\n\nUm die Kampfeber mit einem ungemeinen Blutdurst zu versehen, werden sie mit rohem Fleisch zwangsernährt. Nehmt diese Fackel und benutzt sie, um die Tröge mit dem Fleisch und dem Blut in Flammen zu setzen.", sourceObjective = "Benutzt Adanas Fackel, um alle 3 Tröge im Kriegseberpferch in Flammen zu setzen.", completion = "Ihr habt nicht nur die Kriegseberpferche gereinigt, sondern auch dieser furchtbaren Entweihung ein Ende gesetzt. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[14462] = { id = 14462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist mein Kopf?", description = "Er ist hier, {name}. Hauptmann Grunwald ist ein hochrangiger Allianzoffizier aus der Feste Nordwacht. Zweifellos ist er hier, um einen Angriff auf Orgrimmar mit seinen Nachtelfenverbündeten zu koordinieren. Wir haben beobachtet, wie er in den Turm südwestlich von hier gegangen ist. Ich will seinen Kopf, {class}. Ich will ihn zurück nach Nordwacht schicken, um einen Keil zwischen unsere Feinde zu treiben!\n\nIch habe eine Goblinattentäterin, Slinky Scharfklinge, zum Turm geschickt, aber sie ist nicht zurückgekommen. Geht und findet sie. Und bringt mir diesen Kopf!", sourceObjective = "Ihr wurdet ausgeschickt, um Euch mit der Goblinattentäterin Slinky Scharfklinge am Fuß des nördlichen Turms der Talrendisspitze zu treffen.", completion = "Ihr kommt gerade rechtzeitig, {class}. Ich will gerade ein blitzschnelles, Präzisionsattentat verüben. Mal sehen...\n\nSprengstoff? Ist da.\n\nPneumatische Enterhaken? Sind da.\n\nTragbarer Fallschirm? Ist da.\n\nLähmendes Nervengift?\n\n\n\nAufgetragen. Dann mal los!", sourceObjectiveStatus = "unverified-source-field" }
quests[14463] = { id = 14463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pferde für Dämmerhafen", description = "Die Pferde gerettet zu haben, könnte bedeuten, dass auch die Stadt gerettet ist. Es gibt zwar ausreichend Karren in Dämmerhafen, aber nicht genügend Pferde, um sie zu ziehen.\n\nGeht und sagt Bürgermeisterin Armstead, dass die Pferde, die Ihr gerettet habt, zu ihrer Verfügung stehen.\n\nIch bereite alles vor und stoße dann bald zu Euch.", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", completion = "Hervorragende Arbeit, {name}. Ich denke, ich spreche für alle, wenn ich sage: Je früher wir hier herauskommen, desto besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[14464] = { id = 14464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzschnelles Attentat", description = "Am Fuß des Turms patrouillieren Elitewachen des Hauptmanns. Also wir machen das so: Wir hangeln uns mit den Enterhaken bis nach oben, schnetzeln die VIPs und machen uns mit meinem tragbaren Tiefflugfallschirm davon. Ich werde den Turm mit Sprengstoff spicken, damit er hinter uns explodiert. Ihr stellt sicher, dass Ihr Hauptmann Grunwalds Kopf für Chawg mitbringt. Kapiert?\n\nIhr dürft diese Mission nur DANN annehmen, wenn Ihr zu UNGEBREMSTER GEMEINHEIT fähig seid. Ist das klar?", sourceObjective = "Sprecht mit Slinky Scharfklinge, um auf den Turm zu klettern und Hauptmann Grunwald zu töten. Holt Hauptmann Grunwalds Kopf.", progress = "Ich gehe davon aus, dass Ihr gute Nachrichten habt, {name}?", completion = "Ich bin von der Schlauheit unserer neuen Goblinverbündeten beeindruckt, aber Ihr habt mich noch mehr beeindruckt, {name}. Schaut Euch den entsetzten Ausdruck an, der auf dem Gesicht des Hauptmanns eingefroren ist! Er hat Euren Angriff nicht kommen sehen. Stellt Euch die Angst vor, die das in Nordwacht hervorrufen wird, wenn sie sehen, was einem ihrer geschätzten Offiziere in den Ländern der Nachtelfen geschehen ist.\n\nGut gemacht, {class}. Unser Angriff geht weiter...", sourceObjectiveStatus = "unverified-source-field" }
quests[14465] = { id = 14465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Graumähnenanwesen", description = "Es ist an der Zeit, alle in Sicherheit zu bringen. Das gilt auch für Euch, {name}. Begebt Euch zum Graumähnenanwesen. Die anderen werden Euch in Kürze folgen.\n\nMacht Euch um mich keine Sorgen. Ich kümmere mich darum, dass alle heil hier rauskommen. Ja, sogar die paar Wilden, die wir in den Ställen eingesperrt haben.\n\nSobald Ihr dort angekommen seid, sprecht mit Königin Graumähne über die Dringlichkeit der Lage.", sourceObjective = "Sprecht mit Königin Mia Graumähne im Graumähnenanwesen.", completion = "{name}. Ich habe schon so viel von Euch gehört.\n\nWie ich hörte habt Ihr beim Überleben meiner Familie während des Ausbruchs in Gilneas eine wichtige Rolle gespielt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14466] = { id = 14466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Observatorium des Königs", description = "Ihr solltet mit Genn sprechen. Seit dieses Martyrium begonnen hat, hat er sich in seinem Observatorium eingeschlossen.\n\nIch bin mir sicher, dass er an einem Plan für sein Volk arbeitet. Er ist ein sehr eigensinniger Zeitgenosse.", sourceObjective = "Sprecht mit König Genn Graumähne im Observatorium des Graumähnenanwesens.", completion = "Da seid Ihr ja, {name}. Ich habe Euch erwartet.\n\nIch habe von Eurer Genesung gehört und… Wartet! Spürt Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[14467] = { id = 14467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh weh, Gilneas!", sourceObjective = "Schaut, {name}! Schaut nur, was aus Dämmerhafen geworden ist!\n\nSchaut, was aus dem letzten sicheren Ort in Gilneas geworden ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[14468] = { id = 14468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch ein warmer Körper", description = "Oh, ich habe ein tolles Angebot für Euch! Taucht ein in fremde Kulturen, genießt epische Abenteuer, sprengt Dinge in die Luft und lasst Euch dafür auch noch bezahlen! Klingt zu gut, um wahr zu sein? Tja, ist es aber! Genau das tun wir!\n\nWenn Ihr Interesse habt, meldet Euch bei Gallywix' Verteidigungsposten am Einsamen Grat im Norden und haltet nach Kommandant Molotov Ausschau.", sourceObjective = "Meldet Euch bei Kommandant Molotov am Einsamen Grat.", completion = "Der neuste Rekrut, was?\n\nIch fasse mich kurz. Wir wurden angeheuert, um die Naga in den Ruinen von Gallywix und seinem Eigentum fern zu halten. Ihr tut, was wir Euch sagen, und ich sorge dafür, dass man Euch am Ende dafür entlohnt.\n\nWillkommen im Bilgewässer Bataillon.", sourceObjectiveStatus = "unverified-source-field" }
quests[14469] = { id = 14469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus zweiter Hand", description = "Zunächst brauchen wir mehr Vorräte für Euch und die anderen neuen Rekruten. Unser letzter Schwung Rekruten, oder besser gesagt ihre Leichen auf dem Minenfeld im Norden, haben noch taugliche Standardversorgungspacks bei sich.\n\nMacht nicht den gleichen Fehler wie sie. Versucht, den Minen auszuweichen.", sourceObjective = "Beschafft Euch 12 Militärversorgungspacks vom mittleren Minenfeld.", progress = "An wiederverwerteten Dingen ist nichts auszusetzen.", completion = "Ihr seid ein ganz gewandtes Schlitzohr, was? Gute Arbeit.\n\nHier habt Ihr ein bisschen was, was Euch am Leben halten soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[14470] = { id = 14470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Militärischer Durchbruch", description = "Wir haben den Kontakt zu Unteroffizier Dynamo verloren, der am nächsten Grat nördlich des mittleren Minenfelds stationiert ist. Wahrscheinlich wurden er und seine Leute überrannt.\n\nEr hatte unsere letzte BGG. Geht zu ihm und holt sie zurück. Löscht alle Naga aus, die unsere Linien durchbrochen haben.", sourceObjective = "Tötet Kriegsherr Krellian und beschafft Euch die BGG.", progress = "Wo ist mein Raketenwerfer, Rekrut?", completion = "Gute und schnelle Arbeit, Rekrut.\n\nIst sie nicht eine Schönheit? Ich habe sie selbst zusammengebaut. Und ich habe ganz besondere Pläne für dieses Schätzchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14471] = { id = 14471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mörser ersten Grades", description = "He Kumpel! Mögt Ihr Explosionen? Natürlich tut Ihr das. Wie kann man Explosionen auch nicht mögen?!\n\nIch habe am Grat im Osten Mörser aufstellen lassen, um die Naga zurückzuhalten. Los, Rekrut! Mörsert sie… Mörsert sie alle! Ahahaha!", sourceObjective = "Benutzt einen Goblinmörser, um 60 Angreifer der Grollflossen zu töten.", completion = "Kaum zu glauben, dass sie uns dafür auch noch BEZAHLEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[14472] = { id = 14472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dahin, wo es weh tut!", description = "Die Naga bringen diese Riesen dazu, Pfade durch unsere Minenfelder zu trampeln. Es ist Zeit, unsere BGG einzusetzen!\n\nBegebt Euch zum Eingang des südlichen Minenfelds. Den Rest könnt Ihr Euch sicher denken.", sourceObjective = "Benutzt eine BGG, um einen versklavten Sohn von Arkkoroc auf dem südlichen Minenfeld zu töten.", completion = "BÄMM! Mitten ins Gesicht! Guter Schuss, Kleiner!", sourceObjectiveStatus = "unverified-source-field" }
quests[14473] = { id = 14473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt ist es unser Problem", description = "Sieht aus, als würden diese Affen einfach alles stehlen, was nicht niet- und nagelfest ist! Diese diebischen kleinen Monster haben die Teraptormatriarchin zur Weißglut gebracht, indem sie ihre Eier gestohlen haben. Aber was noch schlimmer ist: Die Eier sind geschlüpft! Jetzt rennen hier überall hungrige Teraptorjunge herum und haben uns als schnelle Mahlzeit auserkoren!\n\nWir haben nicht damit angefangen, aber jetzt ist es unser Problem. Ihr müsst in den Dschungel gehen und diese hungrigen Teraptorjungen töten, bevor sie uns alle töten.", sourceObjective = "Tötet 6 Teraptorjunge.", completion = "Hoffen wir einfach mal, dass wir uns später nicht mit ihrer Mama auseinandersetzen müssen. Das wäre alles andere als gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[14474] = { id = 14474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungskapseln der Goblins", description = "{name}, es tut mir leid. Ich dachte, Ihr wärt tot!\n\nEs ist einfach Irrsinn! Wir sind direkt in einen Kampf zwischen der Allianz und der Horde gesegelt.\n\nWir müssen unsere Brüder und Schwestern retten.\n\n<Er zeigt auf die Rettungskapseln, die um Euch herum im Wasser verstreut sind.>\n\nIch glaube, ich bleibe hier noch ein wenig sitzen und komme zu Atem. Könntet Ihr aufs Meer schwimmen und sie herauslassen? Nehmt meine thermohydraulischen Flossen, damit könnt Ihr Euch schneller fortbewegen.\n\nLasst Sassy wissen, dass ich gleich losschwimme.", sourceObjective = "Rettet 6 überlebende Goblins.", completion = "Oh, dem Himmel sei Dank, dass Ihr überlebt habt, {name}! Ich war mir so sicher, dass Ihr ertrunken seid, nachdem ich Euch über Bord habe gehen sehen.\n\n\n\nSchaut nur, wie viele Leute Ihr gerettet habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[14475] = { id = 14475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandet!", description = "Seht Ihr ein Problem mit diesen Windreitern, {name}? Sie reiten nicht auf dem Wind! Jeder Flug, den ich aussende, wird von diesen Nachtelfenheckenschützen abgeschossen.\n\nScharfschützen aus Talrendis haben sich im südlichsten Turm vor den Bergen verschanzt. Ich hab einen dieser kleinen Goblinanfänger losgeschickt, damit er sich um den Turm kümmert, aber ich habe kein Wort von ihm gehört. Geht und findet Bombardierhauptmann Smooks und macht ihm gehörig Dampf!", sourceObjective = "Findet Bombardierhauptmann Smooks im südlichsten Nachtelfenturm bei der Talrendisspitze.", completion = "Endlich Verstärkung!", sourceObjectiveStatus = "unverified-source-field" }
quests[14476] = { id = 14476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verkabelt zum großen Knall", description = "Dieser Turm war nicht in der Reichweite der Kanonen, also dachte ich, wir lassen ihn auf die altmodische Art in die Luft fliegen - höchstpersönlich. Wir haben die Sprengsätze alle angebracht, aber die Wachen haben uns zurückgeschlagen, bevor wir die Zünder scharfmachen konnten.\n\n{name}! Geht dort hinauf und macht die drei Zünder scharf, die wir am Fuß des Turms platziert haben. Die Dinger sind per Kabel mit einem Satz Thermalbomben verbunden, die ich an der tragenden Wand angebracht habe... Das wird ein Spektakel!", sourceObjective = "Macht die drei Sprengladungen, die um den Fuß des südlichsten Turms an der Talrendisspitze angebracht sind, scharf.", completion = "Klasse. Dann wollen wir diesen Bananenstand mal anzünden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14477] = { id = 14477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drückt auf den Knopf!", description = "Lass mich die Verbindungen überprüfen... alles klar. Bitte, Ihr habt die Ehre, {name}. Drückt drauf. Drückt auf den Knopf!\n\nDrückt auf den Knopf, {name}!\n\nNach dem Feuerwerk geht zu Kroum in Valormok und sagt ihm, dass der Himmel sauber ist.\n\nDrückt auf den Knopf!", sourceObjective = "Zündet die Sprengladungen!", completion = "Ja, lasst sie brennen! Lasst sie die Nacht erleuchten und ihr brennender Turm soll das Schlachtfeld unter uns erleuchten während wir Entsetzen über sie bringen.\n\nIch danke Euch, {name}. Bleibt in meiner Nähe: der Einmarsch steht kurz bevor...", sourceObjectiveStatus = "unverified-source-field" }
quests[14478] = { id = 14478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Ausnehmer", description = "Das Bilgewasserbataillon sucht derzeit nach neuen Rekruten für OPERATION AUSNEHMER.\n\nDer Sold besteht aus einer Goldmünze für alle Soldaten, die am Ende der Operation unbescholten sind. Im Falle des Ablebens erlischt jeglicher Anspruch auf eine Bezahlung. Für alle im Rahmen der Mission durchgeführten Wiederbelebungen wird eine Gebühr von 20 Silberstücken erhoben.\n\nAlle Rekruten sollen sich umgehend bei Kommandant Molotov unter der Hauptkanone melden.", sourceObjective = "Meldet Euch bei Kommandant Molotov unter der Hauptkanone im Bilgewasserhafen zum Dienst.", completion = "Willkommen zurück zum Dienst, Soldat. Schön, dass Ihr wieder da seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[14479] = { id = 14479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt viele andere", description = "Genug geredet. Schwingt die Beine und ab auf eine Rakete, Soldat!\n\nUnd vergesst nicht: Wenn Ihr tot seid, werdet Ihr nicht bezahlt!", sourceObjective = "Nehmt eine Rakete zum Strand der Trümmer und meldet Euch dann bei Leutnant Drex zum Dienst.", completion = "Holprige Reise gehabt?", sourceObjectiveStatus = "unverified-source-field" }
quests[14480] = { id = 14480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschung", description = "Wir schicken Euch dort hinein, um diese Nagaplage auszurotten. Der Gebrauch von Waffen wurde genehmigt.\n\nDer Goblintrupp unterstützt Euch bei dieser Mission, also sollte es ein Kinderspiel werden.", sourceObjective = "Tötet 30 Naga der Grollflossen in den Ruinen von Eldarath.", completion = "Euer Name spricht sich herum… Ihr seid fast schon so berüchtigt wie der Goblintrupp. Ihr seid ein ganz Harter.", sourceObjectiveStatus = "unverified-source-field" }
quests[14481] = { id = 14481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Abgrund", description = "Die Horde und die Allianz bekämpfen sich auf dem Meer im Westen.\n\nUnter ihnen bereiten sich viele neue Feinde auf etwas vor, das unser aller Ende mit sich bringen könnte.\n\nIch werde Euch schicken, um mit dem Admiral der Streitmächte der Allianz zu sprechen. Teilt Eure Vision mit ihm. Überzeugt ihn davon, dass er seine Aufmerksamkeit auf die wahre Gefahr von unten richten muss, bevor sie zu groß wird...\n\nUm beim Admiral vorsprechen zu können, müsst Ihr Euch bei Rekrutierer Burns einschreiben.", sourceObjective = "Nambria möchte, dass Ihr mit Rekrutierer Burns am Hafen von Sturmwind sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[14482] = { id = 14482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht ruft", description = "Bürger!\n\nWie Ihr vielleicht gehört habt, greift uns die Horde vor der Küste an. Die Schlacht ist heftig und unerbittlich.\n\nWir brauchen jeden Tauglichen, um die Feinde zurückzuschlagen!\n\nMeldet Euch unverzüglich am nördlichsten Dock, um zur Schlacht transportiert zu werden.\n\nOh und unsere offiziellen Schlachtschiffe sind... nun ja, etwas später dran als geplant. Macht Euch aber keine Sorgen, wir haben Söldnerschiffe angeheuert, die in der Zwischenzeit reichen sollten.\n\nBeeilt Euch jetzt, {class}. Sturmwind braucht Euch!", sourceObjective = "Fahrt mit dem Söldnerboot zur Schlacht.", completion = "Ich wette, dass Ihr eine andere Art von Schlacht erwartet habt. Aber es ist dennoch eine Schlacht, Ihr werdet schon sehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[14483] = { id = 14483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas liegt in der Luft (und Liebe ist es nicht)", description = "Auf die Innenseite der Karte sind verrückte, detaillierte Pläne gekritzelt, einen Großteil Azeroths zu infizieren. Das müsst Ihr sofort einem der Ermittler des Dampfdruckkartells zeigen!", sourceObjective = "Bringt die vergilbte schöne Grußkarte zu Detektiv Snap Schnappbolz in Orgrimmar.", progress = "Habt Ihr Euch um diese nichtsnutzigen, Ränke schmiedenden Gauner gekümmert?", completion = "Was habt Ihr da?\n\nOh, hey, das ist was Großes. Was richtig Großes. Die ganzen verrückten Details auf einem Haufen. Danke - Ihr habt uns hier echt geholfen. Es war schön, mit Euch zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14484] = { id = 14484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopf der Schlange", description = "Im Offizierslager hat man uns beigebracht, immer den Kopf der Schlange abzuschlagen. Angesichts der Tatsache, dass wir nie irgendwelche Schlangen gefunden haben, schien das ein ganz schön blöder Rat zu sein. Aber jetzt ergibt alles einen Sinn.\n\nBringt Eure Männer dorthin und tötet Lord Kassarus.", sourceObjective = "Tötet Lord Kassarus im Tempel von Zin-Malor.", completion = "Ich bin froh, dass Ihr auf unserer Seite kämpft, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[14485] = { id = 14485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen Ticker", description = "Unser bester Sprengstoffexperte Ticker ist zusammen mit dem Goblintrupp in einer Mission unterwegs. Er hat WEIT mehr als genug Sprengstoff für alle Runensteine in den Ruinen dabei.\n\nIhr müsst ihm nur Deckung geben. Den Rest erledigt er.", sourceObjective = "Bringt Ticker in die Ruinen und gebt ihm Deckung, während er Bomben an 3 der Runensteine der Grollflossen anbringt.", completion = "Wir hoffen, dass wir damit eine ihrer größten Magiequellen abschneiden können. Die Wahrheit ist, dass wir es nicht genau wissen. Aber wer kann schon einer Gelegenheit widerstehen, etwas in die Luft zu jagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14486] = { id = 14486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ware anfassen", description = "Hey, <Kumpel/Ihr da>! Wollt Ihr schnell ein paar Münzen verdienen?\n\nBringt mir alle Tafeln der Hochgeborenen, die Ihr in den Ruinen finden könnt.", sourceObjective = "Sammelt 12 Tafeln der Hochgeborenen aus den Ruinen von Eldarath.", progress = "Die Blutelfen sind verrückt nach diesen Tafeln. Pures Geld!", completion = "Ausgezeichnet. Hier ist Eurer Anteil.\n\nSchön, mit Euch Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14487] = { id = 14487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch schlagendes Herz", description = "Kommandant Molotov hat im Geheimlabor einen Käufer für das Artefakt gefunden, das Ihr für mich ausgespäht habt.\n\nZweifellos befindet es sich noch immer in der Mitte der Ruinen bei der Hohepriesterin, wo Ihr es gefunden habt. Bringt es unbeschadet her, <Soldat/Soldatin>!", sourceObjective = "Beschafft Euch das Herz von Arkkoroc aus der Mitte der Ruinen von Eldarath.", progress = "Ich liebe es, wenn die Leute unschätzbar wertvolle Artefakte einfach herumliegen lassen.", completion = "Haha! Es ist RIESIG!\n\nWir müssen es gleich zu Onkel Tollhaus bringen, sobald wir hier alles aufgeräumt haben und abmarschbereit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[14488] = { id = 14488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustellung", description = "Ihr habt es geschafft? Gut. Ich habe schon auf Hilfe gewartet. Jetzt ist die beste Zeit, zu handeln.\n\nNehmt dieses Paket und begebt Euch noch tiefer hinein, um Hummel, dem Leiter dieser dreckigen Chemiemanufaktur, ein paar Dokumente zuzustellen. Das Dokument ist hier drin, zusammen mit einer kleinen Hilfe, falls sie irgendwelche chemischen Überraschungen für Euch bereithalten. Verwendet einen der Neutralisatoren, wenn es so weit kommt, okay?", sourceObjective = "Stellt Apotheker Hummel auf Burg Schattenfang die Vorladung bei Gericht zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[14491] = { id = 14491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhelose Erde", description = "Bis vor Kurzem schürfte eine Gruppe von Zwergen, die hier eingefallen war, rücksichtslos in unseren Ländern im Westen auf der Suche nach Schätzen. Als die Erde brach, stiegen die Erdgeister des missbrauchten Landes auf und übten Rache an den Zwergen.\n\nDie aufgebrachten Erdgeister suchen die alte Ausgrabungsstätte noch immer heim, {name}. Wir müssen sie beschwichtigen.\n\nNehmt diese Trommel mit Euch nach Westen und trommelt für die Geister. Der Rhythmus sollte ihre Wut und Verwirrung schlichten.", sourceObjective = "Benutzt die Trommel der besänftigten Erde, um 6 aufgebrachte Erdgeister zu beruhigen.", completion = "Das Land ist eindeutig noch immer in Aufruhr, wenn es so schwierig war, die Erdgeister zu beruhigen.\n\nEines sollte Euch in Erinnerung bleiben, {name}. Vergesst nie das Schicksal, das jene ereilt, die der Erdenmutter Schmerzen zufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[20438] = { id = 20438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Verkleidung", description = "Euch ins Innere von Sonnenhäschers Zuflucht zu bringen, wird schwieriger sein, als es erscheint. Nur diejenigen, die über einen Wappenrock der Sonnenhäscher verfügen, wird Zugang zur Zuflucht gewährt. Sollten wir an einen herankommen können, wird eine einfache Verzauberung den Rest erledigen.\n\nAuf dem Balkon über den Fäden des Schicksals werdet Ihr Shandy Lackglanz finden. Ich habe ihm in der Vergangenheit ein paar Mal geholfen - er schuldet mir also noch einen Gefallen. Er kümmert sich um die Wäsche etlicher Leute jeden Schlags aus der Stadt. Vielleicht kann er einen Weg finden, Euch einen Wappenrock eine Weile lang \"auszuleihen\".", sourceObjective = "Besorgt Euch von Shandy Lackglanz einen geliehenen Wappenrock.", progress = "Konnte Shandy Euch dabei helfen, an einen Wappenrock der Sonnenhäscher heranzukommen?", completion = "Ich wusste, dass Shandy für uns einen Weg finden würde, hindurchzukommen. Lasst mich ihn verzaubern, damit Ihr ihn verwenden könnt. Je eher Ihr den Wappenrock nicht mehr braucht, um so schneller können wir ihn Shandy zurückgeben und um so höher wird unsere Chance sein, dass sein Besitzer ihn niemals vermissen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[20439] = { id = 20439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit dem Magister", description = "Ich habe eine Verzauberung auf den Wappenrock gelegt, die es Euch erlauben sollte, einen kurzen Augenblick lang unentdeckt an den Verteidigungsvorkehrungen der Zuflucht der Sonnenhäscher vorbeizukommen. Das sollte Euch genug Zeit geben, das Rattenloch zu betreten und Euch dort mit unserem Kontakt bei den Sonnenhäschern, einem gewissen Magister Hathorel, zu treffen.\n\nBesorgt Euch die Kopie von \"Uralte drachengeschmiedete Klingen\", die seine Männer aus Wyrmruh entliehen haben, solange Eure Verkleidung anhält, und kehrt zu mir zurück.", sourceObjective = "Besorgt den Folianten \"Uralte drachengeschmiedete Klingen\" von Magister Hathorel.", progress = "Habt Ihr das Buch besorgt?", completion = "Ausgezeichnete Arbeit! Jetzt, wo es sich in unserem Besitz befindet, müssen wir es so schnell wie möglich zu Caladis Prunkspeer bringen. Wir dürfen nicht riskieren, dass das Buch wieder in die Hände der Sonnenhäscher gelangt.\n\nIch kümmere mich darum, dass Shandy Lackglanz seinen Wappenrock unbeschadet zurückbekommt und für seine Hilfe reichlich belohnt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[20440] = { id = 20440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergiftetes Wasser", description = "Unsere heiligen Brunnen wurden besudelt und ich werde Eure Hilfe brauchen, um das wieder in Ordnung zu bringen.\n\nUm alle Brunnen zu säubern, muss ich ein Läuterungstotem herstellen und Ihr müsst dieses Totem dann zu den Brunnen bringen und ein Säuberungsritual durchführen.\n\nZuerst werden wir ein Läuterungstotem für den Brunnen der Winterhufe herstellen. Dabei muss uns das Land behilflich sein. Jagt Präriewölfe wegen ihrer Tatzen und ausgewachsene Ebenenschreiter wegen ihrer Krallen. Sie sind im Südwesten zu finden.\n\nKehrt mit den Tatzen und Krallen zu mir zurück, {name}.", sourceObjective = "Sammelt 6 Präriewolftatzen und 4 Ebenenschreiterkrallen.", progress = "Habt Ihr die Tatzen und die Krallen, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ich werde ihre Macht jetzt an ein Totem der Läuterung binden.", sourceObjectiveStatus = "unverified-source-field" }
quests[20441] = { id = 20441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Vision", description = "Stellt sicher, dass Ihr bereit seid, um das Dorf der Bluthufe zu verlassen, {name}. Der nächste Schritt Eurer Reise wird Euch an weit entfernte Orte führen.\n\nEuer Weg führt Euch über die Felder von Mulgore, und die Erdenmutter wird jederzeit über Euch wachen. Wenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, werden sich Eure Augen öffnen, und die Geister werden Euch begleiten.", sourceObjective = "Trinkt vor dem Stammesfeuer im Dorf der Bluthufe das Wasser der Vision.", completion = "Habt keine Angst, {name}. Ihr habt den Ritus der Vision erfolgreich bestanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[23733] = { id = 23733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Heute habt Ihr ein Ritual absolviert, das weitaus schwieriger war, als wir es normalerweise von jungen Tauren erwarten. Seid stolz. Es ist nun an der Zeit, Eure Reise fortzusetzen.\n\nWestlich von hier, hinter der Begräbnisstätte, werdet Ihr einen Pfad finden, der zur Ebene führt. Folgt diesem Pfad und sprecht mit Dyami Windsegler.\n\nGeht mit der Erdenmutter. Ihr werdet hier immer willkommen sein.", sourceObjective = "Sprecht mit Dyami Windsegler oben auf der Horizontmesa.", completion = "Wenn Ihr bereit seid, Camp Narache hinter Euch zu lassen, so werde ich die Geister rufen, um Euch auf Eurem Weg zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24215] = { id = 24215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus des Winds", description = "Seht, {name}. Die Wogenden Ebenen Mulgores erstrecken sich vor Euch: unsere Heimat, die Wiege der Erdenmutter. Hier versorgt sie uns mit allem, was wir je brauchen, in einem friedlichen und grünen Land. Zum Schutz dieses Landes werdet Ihr kämpfen.\n\nEure Reise wird Euch weitab von den schützenden Armen der Heimat führen, zu den am weitesten entfernten und schrecklichsten Gegenden der Welt, und noch weiter.\n\nUnter uns könnt Ihr das Dorf der Bluthufe sehen. Hier beginnt der erste Schritt auf Eurem wahren Weg. Trinkt von dem Wasser der Vision und lasst die Geister Euch den Weg zeigen.", sourceObjective = "Trinkt das Wasser der Vision.\n\nBereitgestellter Gegenstand:", completion = "Willkommen im Dorf der Bluthufe. Ich bin froh, dass die Geister Euch einen sicheren Weg gezeigt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24216] = { id = 24216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch" }
quests[24217] = { id = 24217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch" }
quests[24218] = { id = 24218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24219] = { id = 24219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24220] = { id = 24220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24221] = { id = 24221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin" }
quests[24222] = { id = 24222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Wo auch immer wir dem Feind begegnen, werden wir ihn bekämpfen und vernichten. Egal ob dies in Azeroth, in der Scherbenwelt oder irgendwo sonst auf der Welt getan werden muss.\n\nWir dürfen nicht zulassen, dass die Allianz ihre Position im Auge des Sturms weiter festigt. Bringen wir den Kampf also zu ihnen... denn morgen ist es vielleicht schon zu spät.", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24223] = { id = 24223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24224] = { id = 24224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24225] = { id = 24225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch" }
