quests[24426] = { id = 24426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley" }
quests[24427] = { id = 24427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, {name}, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24428] = { id = 24428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höchst merkwürdiger Umstand", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und bringt ihn Zardeth der Schwarzen Klaue.", sourceObjective = "Bringt Onyxias Kopf zu Zardeth der Schwarzen Klaue, im Keller des Geschlachteten Lamms.", progress = "Bei Nozdormus Zähnen!", completion = "Was? Wie seid Ihr an diesen Kopf gekommen? Ist sie nicht... Nein, die Details sind nicht wichtig vermute ich. Ihr werdet unzweifelhaft ein wenig von diesem Tand als Vergütung erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24429] = { id = 24429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höchst merkwürdiger Umstand", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot vor Euch. Nehmt ihren Kopf und überbringt ihn Arnak Feuerklinge.", sourceObjective = "Bringt Onyxias Kopf zu Arnak Feuerklinge in die Kluft der Schatten.", progress = "Was hat das zu bedeuten?!", completion = "Ihr habt mir das Haupt von jemandem gebracht, der... Nein, es wäre das Beste, nicht zu viel darüber nachzudenken. Ihr werdet unzweifelhaft eine Vergütung für Eure Heldentaten erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24430] = { id = 24430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Himmel schwärzen", description = "{name}! Helft uns hier mal, ja? Gorsch hier hat schlechte Erfahrungen mit dem 'Iss-so-viel-du-kannst'-Meeresfrüchteladen in der Stadt gemacht und jetzt fehlt uns ein Pilot.\n\nIch sollte diese Glevenschleudern der Elfen unbrauchbar machen, bevor sie unsere Lufteinheiten zu Konfetti verarbeiten. Setzt Euch auf diesen Windreiter und schwingt Euch in die Lüfte! Einer meiner Bombardierkumpels wird mit Euch kommen und die Ziele auf Euer Kommando bombardieren.\n\nUnd ach ja! Werft eine Bombe genau auf die Kommandozentrale der Nachtelfen – das große Gebäude im Süden neben der Brücke. Großartig!", sourceObjective = "Besteigt einen gestrandeten Windreiter und fliegt über die Talrendisspitze. Zerstört 6 Glevenschleudern der Talrendisspitze und bombardiert die Kommandozentrale.", progress = "Noch mehr Bomben. Noch mehr Bomben!", completion = "Oh ja! Ich liebe den Geruch von frischen Bombenkratern im Schmutz!\n\nMan munkelt im Lager, dass die Frontlinie der Elfen in Richtung Fluss zusammenbricht. Redet mit Chawg und findet heraus, ob Ihr irgendwie helfen könnt, die Sache zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24431] = { id = 24431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässtes Rezept", description = "Dies scheinen die Überreste eines Rezepts für starken Wein zu sein. Vielleicht wäre der Eigentümer von Noch ein Gläschen in Dalaran daran interessiert...", sourceObjective = "Bringt das durchnässte Rezept zu Christi Stockton nach Dalaran.", progress = "\"Wein ist nur so fein, wie derjenige, der ihn trinkt\", sag ich immer.", completion = "Das ist ein ziemlicher Fund, {name}. Ich kann Euch nicht erlauben, das an irgendwen anderen zu verkaufen, also bin ich gewillt, Euch ein großzügiges Angebot zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24432] = { id = 24432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seetauglich", description = "Willkommen im Salzkutter, {class}.\n\nIch bin Erunak, der letzte überlebende Passagier dieses einst stolzen Schiffes.\n\nIch fürchte, die Mühen haben für Euch gerade erst begonnen. Die Naga greifen unaufhörlich an.\n\nIhr seid an die Bedingungen hier unten nicht ausreichend angepasst, um von großem Nutzen zu sein, aber das kann ich ändern.\n\nDirekt außerhalb dieses Schiffes lebt eine besondere Art von Seestern. Bringt mir einige davon und ein Tritonshorn. Ich werde eine Verzauberung vorbereiten, die Eure Überlebenschancen deutlich erhöhen wird.", sourceObjective = "Erunak im Salzkutter möchte, dass Ihr ihm 3 Salzwasserseesterne und ein Tritonshorn vom Seefahrergrab bringt.", progress = "Schön zu sehen, dass Ihr noch am Leben seid, {race}.\n\nHabt Ihr die Dinge gefunden, die ich brauche?", completion = "Bitteschön, {class}. Damit solltet Ihr Euch im Meer fast mühelos bewegen können.\n\nDoch jetzt müssen wir uns an die Arbeit machen. Wir haben viel zu tun, aber nur wenig Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24433] = { id = 24433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angst, der große Motivator", description = "Unsere Grunzer sind stark, aber sie zeigen keinerlei Initiative. Sie gehen an den Frontlinien in die direkte Konfrontation. Aber <ein unabhängiger/eine unabhängige:c> {class} wie Ihr - nun jemand wie Ihr könnte sich doch hinter die Linien schleichen und tief hinter den Schanzen der Feinde Chaos und Verwüstung anrichten.\n\nSchlagt eine Schneise der Verwüstung durch das Herz von Talrendis, {name}! Streckt unsere Feinde in dem Gebiet nieder, das sie als sicher erachten und hinterlasst Blut und Angst.", sourceObjective = "Kämpft Euch quer durch Talrendisspitze und tötet 12 Verteidiger der Talrendisspitze und 6 Schildwachen der Talrendisspitze.", completion = "Lok'tar ogar, {name}. Wenn sie die Leichen ihrer Kameraden entdecken, werden sie erkennen, dass man nirgendwo vor dem Zorn der Horde sicher ist und ihr Kampfeswille wird gebrochen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24434] = { id = 24434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen absetzen", description = "Spürt Ihr das leichte Beben der hiesigen Leylinien, {name}? Ich spüre hin und wieder ein Vibrieren, wie nach dem Zupfen einer Saite. Diese Art Resonanz erwarte ich nach einem weitreichenden Beschwörungszauber. Die Wissenshüter an der Talrendisspitze versuchen mit ihrer lächerlich primitiven Magie Verstärkung aus Darnassus herbeizurufen.\n\nDas können wir zu unserem Vorteil nutzen, {name}. Wenn Ihr ihren Beschwörungsstein beeinflusst, können wir ein Spitzenteam von Kommandosoldaten hinter die feindlichen Linien teleportieren.\n\nFindet den Beschwörungsstein der Talrendisspitze!", sourceObjective = "Tötet 5 Wissenshüter der Talrendisspitze und findet den Beschwörungsstein der Wissenshüter irgendwo in Talrendisspitze.", completion = "Bilder eines großen, weit entfernten Baums durchfluten Eure Gedanken. Euer Magen krampft sich zusammen während Ihr den Stein neu ausrichtet. Eure Gedanken füllen sich kurz mit Visionen eines feurigen Portals, eines hochaufragenden Bergs, einer kalten Einöde und einer furchtbaren Narbe, die sich über die Erde erstreckt.\n\nKurz darauf beruhigen sich die magischen Energien des Steins und Ihr fühlt Euch nur einen Schritt entfernt von Valormok. Andorels Einmarsch kann beginnen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24435] = { id = 24435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmal nass wischen", description = "Es gibt noch viel zu viele Naga an diesem Strand. Sieht aus, als hättet Ihr da ein wenig aufzuwischen, <Junge/Mädel>.", sourceObjective = "Tötet 12 Naga der Grollflossen am Strand der Trümmer.", completion = "Da habt Ihr aber schön aufgeräumt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24436] = { id = 24436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles Heil kommt von oben", description = "Am Strand liegen eine Menge \"Soldaten\", die versuchen, durch den Tod ihren Pflichten zu entfliehen. Findet diese Faulpelze und ruft mit der Leuchtpistole einen Priester herbei, der sich der Lage annimmt.\n\nUnsere Männer sollen ja nicht glauben, dass sie so leicht ausmustern können.", sourceObjective = "Ruft an den Leichen von 8 verwundeten Soldaten am Strand der Trümmer einen fliegenden Priester herbei.", completion = "Gute Arbeit, Junge. Wir kriegen diesen Strand im Handumdrehen wieder sauber.", sourceObjectiveStatus = "unverified-source-field" }
quests[24437] = { id = 24437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer zuerst kommt, mahlt zuerst", description = "Am Strand entlang gibt es einige wunderschöne Gebäude, die sich perfekt als Strandhäuschen eignen. Ich könnte sie für das Zehnfache der Reparaturkosten weiterverkaufen.\n\nDie besten Stücke sind die Nagapagode im Süden, der Turm direkt am Wasser und die Ruinen ganz am nördlichen Ende des Strands. Wenn Ihr sie für mich beansprucht, bevor die Kämpfe vorbei sind, werde ich Euch gut belohnen.", sourceObjective = "Stellt Ruckus' Gebietsanspruchsfahne neben den besten Strandgrundstücken am Strand der Trümmer auf.", completion = "Haha! Ausgezeichnet. Sehr gut gemacht, Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[24438] = { id = 24438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exodus", description = "Wir haben keine Wahl, {name}. Wir müssen weiter ins Landesinnere.\n\nEs gefällt mir zwar überhaupt nicht, aber hier sind wir verwundbar.\n\nKehrt zu den Ställen unterhalb des Anwesens zurück. Lasst uns alle Mann auf Karren verfrachten und ostwärts schicken. Ich hoffe nur, es ist noch nicht zu spät.", sourceObjective = "Geht an Bord eines Karrens unterhalb des Graumähnenanwesens.", completion = "Danke, dass Ihr angehalten habt, {name}. Unseren Karren hat es ziemlich übel erwischt.\n\nAber der vor uns ist noch schlimmer dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[24439] = { id = 24439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterwerfung Azsharas", description = "{name}! Habt Ihr den Windreiter gelenkt, der die Kommandozentrale bombardiert hat? Das war ein Volltreffer!\n\nMeine Späher berichten mir, dass Ihr Jarrodenus, den Flugmeister der Nachtelfen der Himmelsjäger und de facto Kommandanten der gegnerischen Truppen schwer verwundet habt.\n\nJetzt ist die Gelegenheit zuzuschlagen - ich habe nicht genug Zeit, um alle zum Angriff zusammenzurufen. Stürmt das Gebäude der Kommandozentrale und tötet Kommandant Jarrodenus bevor seine Verstärkung eintrifft. Bringt mir seinen Kopf - und Azshara gehört uns!", sourceObjective = "Besiegt Kommandant Jarrodenus an der Talrendisspitze und holt Euch seinen Kopf.", progress = "Brüllt Jarrodenus immer noch Befehle oder habt Ihr ihn von der Last seines Kopfes befreit?", completion = "...dann ist es vollbracht!\n\n<Chawg beobachtet das Schlachtfeld.>\n\nEs befinden sich immer noch vereinzelte Widerstandsnester um unser Lager herum, aber diese Rückzugsgefechte scheinen einen großangelegten Rückzug ins Eschental zu verschleiern. Azshara gehört uns!\n\nDer Kriegshäuptling wird von diesem Sieg und Eurem Anteil daran hören. Aber ein {class} wie Ihr wird uns sicherlich anderswo eine große Hilfe sein. Vergesst nicht, mit Kroum hier im Lager zu sprechen, bevor Ihr aufbrecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24440] = { id = 24440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhufsäuberung", description = "Ich habe das Totem angefertigt, um den Brunnen der Winterhufe zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet den Brunnen im Südosten, aber nehmt Euch in Acht. Wer auch immer für diese Schandtat verantwortlich war, wird dort eventuell auf der Lauer liegen.\n\nEs kann sein, dass diese Aufgabe sehr schwierig ist, {name}. Seid vorsichtig, und lasst diejenigen, die unseren Brunnen entweiht haben, nicht entkommen.", sourceObjective = "Benutzt das Läuterungstotem der Winterhufe beim Brunnen der Winterhufe.", progress = "Zögert diese Aufgabe nicht hinaus, {name}. Der Brunnen der Winterhufe muss gereinigt werden!", completion = "Die Grimmtotems...\n\n<Mull verzieht das Gesicht.>\n\nIch hatte gehofft, dass meine Tage gezählt sein würden, bis {race} andere {race} grundlos in den Ländern von Mulgore angreifen. Ihr solltet stolz sein, {name} – Ihr habt unserem Land und unserem Volk einen guten Dienst geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24441] = { id = 24441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem der Donnerhörner", description = "Es gibt noch mehr zu tun. Wir müssen ein neues Totem erschaffen, um den Brunnen der Donnerhörner zu säubern.\n\nIhr müsst die Klauen der Raubtiere der Mulgoreebene besorgen. Jagt Präriepirscher wegen ihrer Pirscherklauen und Flachlandpumas wegen ihrer Pumaklauen und kehrt dann zu mir zurück.\n\nIhr findet die Präriepirscher und Flachlandpumas im Osten und Westen.", sourceObjective = "Sammelt 6 Pirscherklauen und 6 Pumaklauen.", progress = "{name}, habt Ihr die Klauen, die Ihr für mich besorgen solltet? Der Brunnen der Donnerhörner wird von Stunde zu Stunde verseuchter!", completion = "Vielen Dank, {name}. Die Reinheit, mit der diese Bestien jagen, ist für die Erstellung des Läuterungstotems äußerst wichtig.\n\nDer Brunnen der Donnerhörner ist ein Symbol meines Stamms und das Wissen, dass er von anderen {race} verunreinigt wurde, ruft die größte Wut hervor, die ich in Jahren verspürt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24442] = { id = 24442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlachtpläne der Kvaldir", description = "Ein Blick auf die erbeuteten Angriffspläne lässt eine Karte von den Östlichen Königreichen und Kalimdor erkennen, auf der die größten Siedlungen markiert sind. Beim Lesen der Befehle erfahrt Ihr, dass die Hauptleute der Kvaldir Pläne für eine Reihe von zerstörerischen Schlachtzügen ausgearbeitet haben.\n\nLaut diesen Befehlen sollen die Angriffe anfangen, nachdem Nebelrufer Yngvar \"das Herz der Nebel befragt hat\". Möglicherweise könnt Ihr die Angriffe ein wenig hinauszögern, indem Ihr das Omen aus der Höhle der Nebelrufer westlich von Hrothgars Landestelle erbeutet und Justiziarin Mariel Treuherz benachrichtigt.", sourceObjective = "Bergt das Herz der Nebel und bringt es zusammen mit den Angriffsplänen der Kvaldir zu Jusitziarin Mariel Treuherz auf dem Argentumturnierplatz.", progress = "Was habt Ihr da gefunden, {name}?", completion = "<Mariel nimmt die Befehle und den erbeuteten Seher-Kristall entgegen und begutachtet beides.>\n\nGute Arbeit, {name}, und gut mitgedacht. Ich bin mir zwar sicher, dass der Diebstahl dieses Schmuckstücks sie nicht lange aufhalten wird, aber ich glaube, dass Ihr uns Zeit verschafft habt, die Anführer der Horde und der Allianz vor den bevorstehenden Angriffen zu warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24443] = { id = 24443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Jägerin", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Honu Hirschjäger, eine junge Jägerlehrerin, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Honu!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Honu Hirschjäger gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24444] = { id = 24444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Schamanin", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Miira Donnerhuf, eine junge Schamanenlehrerin, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Miira!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Miira Donnerhuf gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24445] = { id = 24445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Druidin", description = "Die Verteidigung des Lagers fällt nun den Jüngsten unter uns zu, {name}, und viele unserer mutigsten Lehrlinge bekämpfen in genau diesem Augenblick die Stacheleber. Ich fürchte um ihre Sicherheit...\n\nBitte, sucht die junge Druidin Keshu Baumhuf östlich von hier, tief im Territorium der Stacheleber. Wenn Ihr sie und andere Lehrlinge lebendig vorfindet, können sie Euch vielleicht helfen.", sourceObjective = "Findet Keshu Baumhuf.", sourceObjectiveStatus = "unverified-source-field" }
quests[24446] = { id = 24446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Sonnenläufer", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Bowe Dämmerhorn, einen jungen Sonnenläufer, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Bowe!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Bowe Dämmerhorn gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24447] = { id = 24447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Seherin", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie die junge Seherin Himmelhuf in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet die Seherin!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Seherin Himmelshuf gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24448] = { id = 24448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beförderung", description = "Kommandant Molotov hat persönlich angeordnet, dass Ihr direkt an unseren Außenposten versetzt werdet. Wir bereiten uns darauf vor, Truppen in die Ruinen zu schicken, um den Naga Einhalt zu gebieten und das Artefakt zurückzuholen. Molotov möchte, dass Ihr eine dieser Truppen anführt.\n\nBegebt Euch in den Nordwesten des Strands und folgt dem Weg nach oben zu unserem Außenposten.", sourceObjective = "Meldet Euch bei Hauptmann Tork am Außenposten in den Ruinen von Eldarath.", completion = "{name}! Ihr habt es heil hierher geschafft, gut!\n\nWir haben viele Aufgaben in den Ruinen für Euch, aber wir stellen Euch unsere Besten zur Seite. Ihr arbeitet jetzt mit der ZOGGA-Truppe, die Zasterorientierte Organisation für gewinnbringende Goblin-Akquisen. Molotov ist davon überzeugt, dass Ihr es schafft. Mehr muss ich nicht wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24449] = { id = 24449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landgang", description = "Für den Augenblick stehen die Dinge gut hier. Es war mir eine Freude, mit Euch zusammenzuarbeiten, Soldat.\n\nWenn Ihr bereit seid, das Artefakt zurückzubringen, könnt Ihr einen Gyrokopter zurück zum Bilgewasserhafen nehmen und es Onkel Tollhaus persönlich geben.", sourceObjective = "Bringt das Herz von Arkkoroc zu Onkel Tollhaus im Bilgewasserhafen.", progress = "Ah, der Mann der Stunde!", completion = "Und Ihr habt das Artefakt dabei! Dann war die Mission wohl ein Erfolg. Die Zasterorientierte Organisation für gewinnbringende Goblin-Akquisen kann sich sehen lassen. Dieses Ding bringt sicher ordentlich Knete ein.\n\nUnd Ihr… Ich habe gehört, dass Ihr da unten beeindruckende Arbeit geleistet habt. Wahrscheinlich habt Ihr die Kosten ganz allein um 10% gesenkt. Genau das ist der clevere Geschäftssinn, den ich mir in meiner Armee wünsche!\n\nHier ist Euer versprochener Sold. Und ich habe noch etwas draufgelegt. Ich hoffe, es gefällt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24451] = { id = 24451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz mit dem Arkanisten", description = "Ich habe den Wappenrock mit einem Zauber belegt, sodass Ihr für kurze Zeit die Verteidigung der Silbernen Enklave umgehen könnt. Das dürfte Euch genügend Zeit verschaffen, um in die obere Ebene der Silbernen Enklave zu gelangen und jemanden vom Silberbund namens Arkanist Tybalin zu treffen.\n\nNutzt Eure Tarnung, um das Exemplar von \"Uralte drachengeschmiedete Klingen\", das seine Leute von Wyrmruh geliehen haben, zu beschaffen und zu mir zu bringen.", sourceObjective = "Holt den Folianten \"Uralte drachengeschmiedete Klingen\" bei Arkanist Tybalin.", progress = "Habt Ihr das Buch vom Wyrmruhtempel besorgt?", completion = "Ausgezeichnete Arbeit! Jetzt, wo es sich in unserem Besitz befindet, müssen wir es so schnell wie möglich zu Myralion Sonnenfeuer bringen. Wir dürfen nicht riskieren, dass das Buch wieder in die Hände des Silberbunds gelangt.\n\nIch kümmere mich darum, dass Shandy Lackglanz seinen Wappenrock unbeschadet zurückbekommt und für seine Hilfe entschädigt wird. Sobald sich das Buch in Myralions Händen befindet, stellt der Silberbund keine Bedrohung mehr dar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24452] = { id = 24452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Profit", description = "Die Dinge scheinen sich langsam etwas zu beruhigen. Gallywix blättert sicher weiter Bares hin, damit wir hier draußen bleiben, aber ich glaube, wir können noch ein bisschen mehr aus unserem Deal herausschlagen.\n\nNaga und Meerriesen sind sich normalerweise nicht grün, also müssen die Naga sie irgendwie kontrollieren. Nehmt diesen Tarnfeldgenerator, schleicht Euch in die Ruinen und lasst mich wissen, wenn Ihr etwas von Wert findet.", sourceObjective = "Schleicht Euch mit dem Tarnfeldgenerator in die Ruinen von Eldarath und findet das Herz von Arkkoroc.", completion = "Haha! Sehr gut. Damit bringe ich die Sache ins Rollen. Jetzt brauche ich nur noch einen Käufer und die Genehmigung von Onkel Tollhaus.\n\nHier ist der Lohn für Eure Arbeit. Tolle Leistung, Soldat!", sourceObjectiveStatus = "unverified-source-field" }
quests[24453] = { id = 24453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespräch unter Gefreiten", description = "Hört mal… ein letzter Gefallen, bevor Ihr Euch vom Acker macht.\n\nGefreiter Worcester ist immer noch an diesem Turm und \"rekrutiert\". Lasst ihn wissen, dass wir bereit sind, zusammenzupacken.\n\nEs war mir eine Ehre, mit Euch zu arbeiten, Rekrut.", sourceObjective = "Sprecht mit Gefreiter Worcester am Umschlagplatz der Raketenbahn von Orgrimmar.", completion = "Was?! Ich habe gar nichts von der Mission mitbekommen? Im Ernst?\n\nNa gut, na gut… Ihr überbringt ja nur die Nachricht. Vielen Dank, Kumpel. Vielleicht sehen wir uns ja mal wieder in der Stadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24454] = { id = 24454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Caladis Prunkspeer zurück", description = "Wir müssen dieses Buch umgehend zu Caladis Prunkspeer bringen. Würdet Ihr das tun? Ich kann mich auf niemand anderen verlassen, das Buch zu transportieren, und Ihr habt Euch geschickt darin erwiesen, die Sonnenhäscher auf Abstand zu halten.\n\nBringt es nach Quel'Delars Ruh südlich des Argentumturnierplatzes in Eiskrone. Caladis und das Schwert werden auf Euch warten. Je eher wir die Klinge identifizieren, desto eher können wir Anspruch darauf erheben.", sourceObjective = "Bringt \"Uralte drachengeschmiedete Klingen\" zu Caladis Prunkspeer nach Quel'Delars Ruh.", progress = "Wir haben Eure Rückkehr erwartet. Was hat Euch zurückgehalten?", completion = "<Caladis nimmt das schwere Buch entgegen und fängt an es durchzublättern.>\n\nIch wusste, dass mir die Symbole auf der Klinge bekannt vorkamen. Die Waffe wurde ganz bestimmt von den Drachen geschmiedet und als Geschenk an eine der sterblichen Rassen übergeben. Aber welche Klinge soll das sein und wie kommt es, dass sie in Eiskrone ruht?", sourceObjectiveStatus = "unverified-source-field" }
quests[24455] = { id = 24455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelle Entsendung", description = "Ihr meldet Euch sofort zum Dienst. Hauptmann Desoto überwacht die Entsendung der Truppen an der Rampe der Raketenstartstation.\n\nMacht uns reich, Soldat! Weggetreten!", sourceObjective = "Meldet Euch bei Hauptmann Desoto im Bilgewasserhafen, um entsendet zu werden.", completion = "Schön Euch zu treffen, Soldat. Kommandant Molotov lobt Euch in höchsten Tönen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24456] = { id = 24456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerhornsäuberung", description = "Der Stamm der Grimmtotems glaubt, dass Kalimdor alleine den Tauren gehören sollte. Ihr Hass und Ärger füllen sie mit einem korrumpierenden Durst nach Macht. Magatha, ihre Anführerin, hat den Oberhäuptling Cairne Bluthuf selbst vergiftet, in einem Versuch, die Macht über Donnerfels zu erlangen. Sie wurde besiegt und die Grimmtotems ins Exil geschickt.\n\nJetzt scheinen sie Mulgore in die Verderbnis führen zu wollen, bevor sie diese Ländereien für immer verlassen müssen. Schnell, {name}, begebt Euch zum Brunnen der Donnerhörner nördlich von hier und führt das Ritual aus!", sourceObjective = "Benutzt das Läuterungstotem der Donnerhörner beim Brunnen der Donnerhörner.", completion = "Ihr habt sowohl mir als auch meinen Vorfahren heute einen großen Gefallen getan. Bitte, nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24457] = { id = 24457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Vision", description = "Ich kann Euch gar nicht genug für die Säuberung des Brunnens unseres Stamms danken, {name}, und dafür, dass Ihr die wilden Grimmtotems bekämpft habt. Es gibt aber noch mehr zu tun; für Euch ist die Zeit gekommen, Eure Reise außerhalb vom Dorf der Bluthufe fortzusetzen.\n\nSucht Zarlman Zwillingsmond bei den Feuern im Norden des Dorfes aus. Sprecht mit ihm, um mehr von dem nächsten Ritual zu erfahren, das auf Euch zukommt.", sourceObjective = "Sprecht mit Zarlman Zwillingsmond im Dorf der Bluthufe.", completion = "Ich habe bereits mit Eurem Besuch gerechnet, {class}. Ich weiß immer, wer versuchen möchte, die Riten der Erdenmutter zu bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24458] = { id = 24458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod am Nachmittag", description = "{name}, ich habe die gereinigte Probe Azsharit, die Ihr aus dem Labor gerettet habt, waffenfähig gemacht. Wenn meine Berechnungen richtig sind, wird es mit genug Kraft detonieren, um eine Stadt dem Erdboden gleichzumachen.\n\nWenn ich mich irre, könnten wir den Planeten in zwei Hälften reißen.\n\nDie einzige Möglichkeit, das herauszufinden, ist ein Probelauf! Bringt den Azsharitkern zu der Riesenkanone in Bilgewasser und meldet Euch bei Bleenik Zischlunte. Mein Mietpilot Friz Bodendreh hier kann Euch hinbringen.\n\nIch komme nach... mit Sicherheitsabstand.", sourceObjective = "Liefert den scharfgemachten Azsharitkern bei Bleenik Zischlunte im Bilgewasserhafen ab. Sprecht mit Friz Bodendreh für einen Freiflug.", progress = "Was habt Ihr denn da - hat Wurfhammer Euch geschickt?", completion = "Oh! Das ist er. Der große Knall.\n\n<Zischlunte ruft seine Arbeiter herbei.>\n\nJungs, es ist so weit!", sourceObjectiveStatus = "unverified-source-field" }
quests[24459] = { id = 24459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morin Wolkenpirscher", description = "Ihr habt vielleicht schon einmal etwas von der Venture Company gehört. Sie sind ein \"Kartell\" der Goblins - das ist so etwas Ähnliches wie ein Stamm.\n\nObwohl sich eines dieser Kartelle der Horde angeschlossen hat, ist die Venture Company eigentlich nur der Gier gegenüber loyal. Die gierigen Goblins und ihre Arbeiter haben schon lange versucht, die Rohstoffe und Ressourcen Mulgores auszubeuten - bisher mit wenig Erfolg.\n\nEiner unserer Kundschafter, Morin Wolkenpirscher, hat sich aufgemacht, um die Überreste einer der Karawanen der Goblins zu untersuchen. Wenn Ihr ihm helfen möchtet, müsst Ihr nur der Straße folgen, die aus dem Dorf und nach Osten führt.", sourceObjective = "Findet Morin Wolkenpirscher östlich des Dorfs der Bluthufe.", completion = "Schön, Euch zu treffen. Wenn Ahmo Euch die Einzelheiten zu dieser Art Goblin schon verraten hat, können wir gleich mit der Arbeit anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24460] = { id = 24460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außer Betrieb", sourceObjective = "Pauls Testquestgeber möchte, dass Ihr Zombies tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24461] = { id = 24461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert neu schmieden", description = "Wir dürfen nicht zulassen, dass Quel'Delar in zerbrochenem und entehrtem Zustand bleibt. Nehmt die Überreste des Schwertes sowie den von Euch gefundenen ramponierten Schwertgriff und begebt Euch in die Grube von Saron in der Eiskronenzitadelle.\n\nIn der Grube lässt der Lichkönig Sklaven Saroniterz fördern sowie be- und verarbeiten. Dieses energieerfüllte Saronit brauchen wir, um Quel'Delar wiederherzustellen.\n\nIhr müsst energieerfüllte Saronitbarren sammeln und den Hammer des Schmiedemeisters erbeuten, Euch mit beidem zum Amboss des Schmiedemeisters begeben und das Schwert neu schmieden.", sourceObjective = "Besorgt 5 energieerfüllte Saronitbarren sowie den Hammer des Schmiedemeisters und schmiedet damit Quel'Delar neu.", progress = "Konntet Ihr Quel'Delar wiederherstellen?", completion = "Ihr habt die Klinge Quel'Delars wiederhergestellt, obwohl Blutkönigin Lana'thel verkündet hat, es würde nicht gelingen. Zwar muss die Klinge noch getempert werden, doch Lana'thel und ihr Meister werden uns nicht daran hindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[24462] = { id = 24462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Hol den Gegenstand", description = "Jetzt da Ihr diese Wölfe getötet habt, probieren wir etwas anderes. Holt Euch ein paar Gegenstände von den Troggs da drüben.\n\nNur die dicksten der dicken haben Gegenstände.\n\nci 49707 5", sourceObjective = "Pauls Testquestgeber möchte, dass Ihr 5 Trogggegenstände besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24463] = { id = 24463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Eschental vordringen", description = "Obwohl der Abschaum aus Darnassus sich aus Azshara zurückgezogen hat, bekomme ich immer noch widersprüchliche Meldungen von meinen Reitern, die im Eschental im Westen stationiert sind. Es ist möglich, dass die Nachtelfen einen Angriff auf unser Gebiet im Brachland durchführen.\n\n{class}, Ihr müsst über die Grenze schleichen und mit einem meiner Späher sprechen. Sucht nach Kulg Blutspritzer direkt hinter der Brücke am südwestlichen Rand der Talrendisspitze. Findet heraus, was in jenen Wäldern vor sich geht!", sourceObjective = "Sprecht mit Kulg Blutspritzer im Eschental.", completion = "Ihr sagt, dass die Talrendisspitze gefallen ist? Das sind gute Nachrichten!\n\nDas erklärt auch den Exodus von Elfen, den ich auf dieser Straße gesehen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24464] = { id = 24464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtiere aufspüren", description = "Die Kunst des Aufspürens ist die Seele der Jagd, und Ihr habt gute Arbeit geleistet, mich hier zu finden. Ich bin kein Experte, aber ich wurde gut ausgebildet. Ich kann Euch weitere Wege zeigen, wie man Bestien verfolgen und seine Beute auffinden kann.\n\nDas ist das Mindeste, was ich Euch für die Rettung meines Lebens anbieten kann.", sourceObjective = "Sprecht mit Honu Hirschjäger und erlernt Wildtiere aufspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24465] = { id = 24465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal der Wildnis", description = "Ich bin selbst noch ein Lehrling, {name}, aber ich kann Euch trotzdem aus Dankbarkeit ein wenig beibringen.\n\nLasst mich Euch zeigen, wie Ihr die Erdenmutter anrufen könnt, um von den Mächten der Wildnis profitieren zu können.", sourceObjective = "Sprecht mit Keshu Baumhuf und erlernt Mal der Wildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[24466] = { id = 24466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtruf", description = "Ich bin selbst noch ein Lehrling, {name}, aber ich kann Euch trotzdem aus Dankbarkeit ein wenig beibringen.\n\nLasst mich Euch zeigen, wie Ihr Eure innere Wut in einen mächtigen Schlachtruf kanalisieren könnt.", sourceObjective = "Sprecht mit Kriegerheld Scharfhorn und erlernt Schlachtruf.", sourceObjectiveStatus = "unverified-source-field" }
quests[24467] = { id = 24467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übergang ins Schwarze", description = "Jetzt können wir diesen Wahnsinn beenden! Wir müssen den schwarzen Drachenschwarm vollkommen von Azshara fernhalten, bevor sie ihrem Meister irgendeine Nachricht überbringen können.\n\nIch weiß immer noch nicht, welches Ass sie für unsere Entführung im Ärmel haben, deshalb möchte ich Euch ein letztes Mal um etwas bitten: Geht zum Säbelrücken und tötet ihre Anführer, Zwielichtfürstin Katrana und Malicion.\n\nWenn es eng wird, komme ich und helfe. Ich möchte nur nicht riskieren, in die Falle zu gehen, die sie Azuregos gestellt haben.", sourceObjective = "Tötet Zwielichtfürstin Katrana und Malicion am Säbelrücken.", completion = "Ihr versetzt mich in Erstaunen, sterbliches Wesen. Nur selten trifft man jemanden, der so entschlossen und erfinderisch ist.\n\nAzuregos und ich werden Azshara wahrscheinlich für eine Weile verlassen und untertauchen. Ich hoffe allerdings, dass wir uns eines Tages wiedersehen. Vielleicht bereiten wir ja Todesschwinge selbst ein Ende.\n\nLebt wohl, {name}. Passt auf Euch auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[24468] = { id = 24468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandet im Moor", description = "Die Oger haben zwei unserer Postkutschen erwischt: diese hier und eine, die nicht weit von hier im Norden ins Moor gestürzt ist.\n\nGeht dorthin und rettet die Überlebenden, während wir uns überlegen, wie wir mit diesen Ogern fertigwerden.", sourceObjective = "Rettet 5 Unfallüberlebende aus dem Hagelwaldmoor.", completion = "Ihr habt es wieder geschafft, {name}. Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[24469] = { id = 24469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stellung halten!", description = "Hey, Ihr da! Ihr seid doch <ein kräftig aussehender/eine kräftig aussehende:c> {class}. Würdet Ihr uns helfen?\n\nEs scheint, als ob das heutige Erdbeben eine Gruppe dieser barbarischen Troggs aufgerüttelt hat und die sind über irgendetwas ziemlich erbost. Meine Leute tun, was sie können, um sie fernzuhalten, aber wir könnten Hilfe gebrauchen.\n\nTragt Euren Teil dazu bei - geht Richtung Süden und helft meinen Gebirgsjägern aus der Klemme. Wir müssen die Stellung halten!", sourceObjective = "Tötet 6 Eindringlinge der Felsenkiefertroggs.", progress = "Wie viele habt Ihr erwischt?", completion = "Beeindruckende Arbeit, mein Junge. Von jetzt an können wir die Stellung wieder alleine halten.\n\nHier, nehmt das für Eure Bemühungen. Es könnte sich als nützlich erweisen, zumal ich Euch um etwas noch Wichtigeres bitten muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[24470] = { id = 24470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haut sie!", description = "Also gut, hört zu. Ich weiß ein oder zwei Dinge über Troggs, und eins davon ist, dass die größten und stärksten Troggs den meisten Respekt genießen. Diese Rohlinge ziehen Stärke allem anderen vor.\n\nSeht Ihr diese großen, starken Troggs hinter ihren Frontlinien? Sie sind das, was einem Anführer am nächsten kommt. Geht und erledigt ein paar von denen, damit sie wissen, was es heißt, sich mit den Töchtern und Söhnen von Eisenschmiede anzulegen!", sourceObjective = "Tötet 3 Stümper der Felsenkiefertroggs.", progress = "Nun, worauf wartet Ihr, {class}?", completion = "Hmm... Sie machen uns dafür verantwortlich, ihre Höhle zerstört zu haben, sagt Ihr? Das waren nicht wir, das war dieses schreckliche Erdbeben heute früh. Sind die so beschränkt, dass sie nicht sehen, dass unser Lager auch beinah zerstört wurde?\n\nIch kann allerdings keinem Trogg vorwerfen, dass er für seine Heimat kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[24471] = { id = 24471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Verwundeten", description = "Hört zu, {name}! Ich brauche nicht wie Joren Eure Klinge, aber ich benötige jemanden mit einer ruhigen Hand und etwas Mut.\n\nUnsere Gebirgsjäger sind ausgebildet, um das Dorf vor einem Wolfsangriff zu schützen... nicht vor einer ausgewachsenen Trogginvasion! Viele unserer Besten liegen verletzt und erschöpft darnieder, und ich brauche Eure Hilfe, um sie zu versorgen.\n\nHier, nehmt mein Erste-Hilfe-Set und helft so vielen, wie Ihr könnt.", sourceObjective = "Verwendet Stens Erste-Hilfe-Set, um 4 verwundeten Gebirgsjägern der Eisklamm zu helfen.", completion = "Viele von jenen, die Ihr gerettet habt, sind schon ins Lager zurückgekehrt. Ihre Wunden scheinen gut versorgt! Ihr könntet eine Zukunft im Bereich der Ersten Hilfe haben, wenn Euch dergleichen zusagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24472] = { id = 24472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorstellen ist angebracht", description = "Die Verlassenen sind uns dicht auf den Fersen und nun versuchen auch diese Oger, uns in die Zange zu nehmen, {name}.\n\nSie sind Diener des Ettins Koroth, dem bösartigsten und zerstörerischsten Wesen in ganz Gilneas.\n\nWenn wir Koroth dazu bringen könnten, die Vorhut der Verlassenen anzugreifen, können wir uns vielleicht sicher zurückziehen und etwas Zeit gewinnen.\n\nAber das gelingt uns nur, wenn wir Koroth wütend machen. Seine Diener zu töten reicht nicht. Wir müssen uns seinen wertvollsten Besitz schnappen, sein Banner aus Tigerfell.", sourceObjective = "Tötet 4 Ogerdiener und besorgt Euch Koroths Banner in Koroths Bau.", progress = "Wie ist es gelaufen, {name}?", completion = "Ihr habt den Ettin wirklich sehr wütend gemacht, {name}. Ich habe ihn selbst gehört.\n\nHoffen wir, dass es funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[24473] = { id = 24473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambossar abriegeln", description = "Wir wissen Eure Hilfe hier draußen zu schätzen, doch es gibt einen Ort, an dem Ihr noch mehr gebraucht werdet.\n\nDank der Angriffe durch die Troggs - ganz zu schweigen von dem starken Erdbeben, das wir gerade erlebt haben - müssen wir alle Zivilisten in Ambossar im Nordwesten abriegeln.\n\nGeht und sprecht mit meiner Frau Jona in Ambossar. Ich bin sicher, sie kann <einen kräftigen Kerl/ein kräftiges Mädel> wie Euch gut brauchen.", sourceObjective = "Sprecht mit Jona Eisenquell in Ambossar.", completion = "Hmpf... und was wollt IHR nun wieder? Seht Ihr nicht, dass ich beschäftigt bin!? Geht jemand anders auf die Nerven, ich hab' keine Zeit.\n\nMoment, was sagt Ihr da? Joren hat Euch geschickt, um zu helfen? Warum habt Ihr das nicht gleich gesagt!", sourceObjectiveStatus = "unverified-source-field" }
quests[24474] = { id = 24474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wichtigste zuerst: Wir brauchen Bier", description = "Ich kann mir nicht vorstellen, wie wir hier IRGENDWAS auf die Beine stellen wollen, solange wir kein Bier haben! Unser Biervorrat hier in Ambossar ist bedenklich niedrig.\n\nZum Glück haben wir für solche Fälle ein paar Notfallfässer aufbewahrt. Westlich von Ambossar, entlang der nördlichen Grenze des Tals, werdet Ihr Fässer mit Sturmhammer-Starkbier und Theramore Hell finden. Gleich östlich von hier findet Ihr einen Vorrat mit Gnomenbräu. Das ist mein Lieblingsbier!", sourceObjective = "Bringt je ein Fässchen Sturmhammer-Starkbier, Theramore Hell und Gnomenbräu an Euch.", progress = "Das Bier, Kumpel, das Bier!", completion = "<Jona nimmt einen tiefen Zug von dem Gnomenbräu.>\n\nAhh... Das hat gut getan. Jetzt können wir hier endlich ordentlich arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24475] = { id = 24475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ganze andere Zeug", description = "Wenn wir hier eine ganze Weile die Schotten dichtmachen, werden wir etwas zu futtern brauchen und Decken, um die Kleinen warmzuhalten. Würde es Euch etwas ausmachen, hinauszugehen und ein paar Vorräte zu besorgen?\n\nIhr werdet feststellen, dass einige der kleinen Eber ein paar Keulen von stattlicher Größe haben... perfekt zum Essen. Dann brauchen wir noch Felle von jungen Wölfen.\n\nIhr findet fast überall in Eisklamm solches Wild.", sourceObjective = "Erlangt 3 Wildschweinschenkel und 4 struppige Wolfsbälge.", progress = "Die Leute werden schon unruhig. Habt Ihr die Vorräte schon?", completion = "Das muss fürs Erste reichen. Wir haben eine Menge Mäuler zu stopfen, aber wir müssen mit dem hinkommen, was wir haben. Mit ein bisschen Glück schickt uns König Bronzebart in Eisenschmiede ja bald Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24476] = { id = 24476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge tempern", description = "Endlich wurden die Bruchstücke von Quel'Delar wieder vereint und die Klinge ist ganz - doch sie muss zuerst getempert werden, bevor Ihr sie einsetzen könnt. Die gezackte Saronitschneide ist spröde und würde beim ersten Kontakt zerbrechen.\n\nIn den Tiefen der Seelenschmiede in der Eiskronenzitadelle gibt es einen Ort, an dem sie sicher getempert werden kann. Nehmt Quel'Delar mit Euch zum Domizil des Verschlingers der Seelen und sucht nach dem Schmelztiegel. Taucht die Klinge dort hinein und bringt sie zurück zu mir in die Gefrorenen Hallen.", sourceObjective = "Tempert das neugeschmiedete Quel'Delar im Schmelztiegel der Seelen.", progress = "Solange das Schwert nicht getempert wurde, ist es nutzlos.", completion = "Ich... ich verstehe nicht. Das Schwert zu tempern hätte die Klinge wieder in ihren ursprünglichen Zustand bringen sollen. Was ist hier geschehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24477] = { id = 24477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakte der Zwerge", description = "{name}, <mein Junge/meine hübsche Blume>! Interessiert Ihr Euch für Archäologie?\n\nWir haben hier genau vor unserer Nase eine aufregende Gelegenheit. Das Beben des heutigen seismischen Ereignisses hat einige Artefakte aus der Erde unter unserem Lager herausgeschüttelt. Wenn Ihr den nördlichen Rand des Tals inspiziert, solltet Ihr alle möglichen Schätze finden. Bringt einige zurück zu mir und vielleicht können wir sie zusammen untersuchen.\n\nAlles klar! Ab mit Euch!", sourceObjective = "Beschafft 5 vergessene Zwergenartefakte.", progress = "Ja?", completion = "Wunderbar! Schaut Euch dieses hier an... Das muss mehr als 200 Jahre alt sein!\n\nJetzt aber zu anderen Dingen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24478] = { id = 24478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Frosts", description = "Wisst Ihr, einige meiner Lehrlinge haben mich als kaltherzig bezeichnet. Ich sage allerdings immer, lasst die Temperatur meines Körpers Euch nicht daran hindern, zu lernen.\n\nWenn Ihr Euch zur Prüfung des Frosts begeben möchtet, berührt den Frostkristall, um ein Portal zu öffnen. Wenn Ihr dort seid, ist das Ziel ganz einfach: Sammelt die kleinen schwebenden Eiskügelchen ein.\n\nDamit es nicht zu einfach wird, könnte der Gefrierbrand Euren Fortschritt hemmen. Wenn Ihr besonders raffiniert sein wollt, könnt Ihr die Runenfallen benutzen, um über sie hinwegzuspringen, wenn sie vorbeidriften. Klasse, nicht wahr?", sourceObjective = "Schließt die Prüfung des Frosts ab, indem Ihr 20 Essenzen des Eises einsammelt, ohne von Gefrierbrand getroffen zu werden.", completion = "Großartig. Ihr lasst Euch ganz bestimmt nicht von kalten Füßen aufhalten. Oder sonstigen kalten Körperteilen!\n\nNein? ...noch zu früh?", sourceObjectiveStatus = "unverified-source-field" }
quests[24479] = { id = 24479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Schattens", description = "Lassen wir uns nicht von den Grenzen des Magierepertoires der Magier einschränken. Ich jedenfalls will keiner Klasse angehören. Nekromantie kann so viel Spaß machen!\n\nBerührt den Schattenkristall, um ein Portal zu meiner Prüfung des Schattens zu öffnen. Sobald Ihr dort eintrefft, begebt Euch zu dem Altar, wenn Ihr bereit seid.\n\nKlagende Seelen werden Euch verfolgen...Euer Ziel ist es, sie in die Fallen zu locken. Achtet darauf, dass sie Euch nicht berühren.", sourceObjective = "Schließt die Prüfung des Schattens ab, indem Ihr 20 Klagende Seelen zu den Schattenrunen lockt, ohne von ihnen berührt zu werden.", progress = "Ihr seid nicht besonders gut darin. Ihr sollt die Prüfung beenden, BEVOR Ihr zu mir zurückkommt und mit mir sprecht. Nachvollziehbar?", completion = "Es gefällt mir, wie Ihr Euch bewegt, Lehrling.\n\nMacht Euch keine Sorgen darüber, wo ich all die Seelen herhabe. Sie wurden auf absolut humane Art und Weise besorgt, das versichere ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24480] = { id = 24480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen der Reflexion", description = "Ihr habt das Schwert zwar neu geschmiedet und getempert, dennoch ruht es in seiner Scheide und zeigt nichts von der Macht, die es besitzen soll. Ihr sagt, dass es Euch zieht, als hätte es einen eigenen Willen?\n\nWagt Ihr es, das Schwert an den von ihm gewünschten Ort zu bringen? Es ist nicht richtig, dass es so ruhig und doch so hartnäckig ist, und ich fürchte, wir werden nie erfahren weshalb, solltet Ihr es nicht an seinen Zielort bringen. Bringt es in die Hallen der Reflexion in der Eiskronenzitadelle. Seid jedoch auf der Hut! Ich warte in den Gefrorenen Hallen auf Euch.", sourceObjective = "Bringt Quel'Delar nach Schwertruh ins Innere der Hallen der Reflexion.", progress = "Was ist im Inneren der Hallen der Reflexion geschehen?", completion = "Ich hätte es nicht für möglich gehalten, dass das Böse von solch einem Schwert Besitz ergreifen kann, doch ich nehme an, dass das naiv von mir war. Wenn die größte Schöpfung der Drachen verdorben und gegen sie gerichtet werden kann, weshalb sollte da ein Schwert die Ausnahme bilden?\n\nUthers Rat ist weise, {name}, und ich würde Euch nahelegen, ihn schleunigst zu befolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24481] = { id = 24481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffe des Felsbeißers", description = "Ich bin selbst noch ein Lehrling, {name}, aber ich kann Euch trotzdem aus Dankbarkeit ein wenig beibringen.\n\nLasst mich Euch zeigen, wie Ihr die Erdgeister zu Hilfe rufen könnt, um Eure Waffen mit elementarer Macht zu tränken.", sourceObjective = "Sprecht mit Miira Donnerhuf und erlernt Waffe des Felsbeißers.", sourceObjectiveStatus = "unverified-source-field" }
quests[24482] = { id = 24482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtwort: Seelenstärke", description = "Ich bin selbst noch ein Lehrling, {name}, aber ich kann Euch trotzdem aus Dankbarkeit ein wenig beibringen.\n\nLasst mich Euch zeigen, wie Ihr die Seelenstärke An'shes kanalisieren könnt, um Euch selbst mit enormer Ausdauer zu versorgen.", sourceObjective = "Sprecht mit Seherin Himmelshuf und erlernt Machtwort: Seelenstärke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24483] = { id = 24483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmsiel", description = "Unsere Kutschenfahrer wurden angewiesen, sich im Fischerdorf Sturmsiel zu sammeln. Die Späher berichten, dass wir dort Schutz und Vorräte finden können.\n\nTrefft Euch dort mit Gwen Armstead. Sie ist für die Leute verantwortlich.", sourceObjective = "Sprecht mit Gwen Armstead in Sturmsiel.", completion = "Ihr habt es also geschafft, {name}. Anscheinend haben es fast alle geschafft.\n\nFür eine Ausnahmesituation schlagen wir uns nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24484] = { id = 24484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfung", description = "Was sagt Ihr dazu, {name}? Die ganze Zeit über war Sturmsiel halbwegs intakt.\n\nSchade, dass die Verlassenen noch immer unterwegs ins Landesinnere sind, aber immerhin ist es ein guter Platz, um für ein oder zwei Nächte die Füße hochzulegen.\n\nDie andere Hälfte der Stadt ist voll von Spinnen, deswegen habe ich den Leuten gesagt, sie sollen sich von dort fernhalten.\n\nVielleicht könntet Ihr ja helfen, die Spinnen zu beseitigen? Unsere Verwundeten können bestimmt besser schlafen, wenn sie wissen, dass jemand diese achtbeinigen Ungeheuer in Schach hält.", sourceObjective = "Tötet 6 Giftbruthuscher.", completion = "Das habt Ihr gut gemacht, {name}. Aber diese Spinnen sind überall und ich fürchte, ihre Zahl hat kaum abgenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24485] = { id = 24485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Rechtschaffenheit", description = "Ich bin selbst noch ein Lehrling, {name}, aber ich kann Euch trotzdem aus Dankbarkeit ein wenig beibringen.\n\nLasst mich Euch zeigen, wie Ihr Euch mit dem Licht An'shes füllen und Eure Feinde niederschlagen könnt.", sourceObjective = "Sprecht mit Bowe Dämmerhorn und erlernt Siegel der Rechtschaffenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24486] = { id = 24486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedet das Eisen, solange es noch heiß ist", description = "Das Dorf der Troggs im Südwesten wurde fast ebenso sehr beschädigt, wie unseres. Nun sollte man logischerweise annehmen, dass da auch einige Troggartefakte aus dem Boden ragen!\n\nLeider scheinen Troggplünderer die meisten Artefakte bereits aufgesammelt zu haben. Bitte schaut, ob Ihr eine Möglichkeit findet, sie zurückzuholen. Ob Ihr es glaubt oder nicht, aber Wissen über die Troggs könnte schließlich dazu führen, dass man noch mehr Wissen über die mächtigen Zwerge erlangt!", sourceObjective = "Besorgt 5 unbezahlbare Felsenkieferartefakte von den Strauchdieben der Felsenkiefertroggs.", progress = "Habt Ihr den Troggs einige Artefakte entreißen können?", completion = "Oh, nun schaut Euch das an! Eine Axtklinge, einige Pfeilspitzen und eine Art einfacher Löffel. Das ist in der Tat faszinierend.\n\nNoch einmal vielen Dank für Eure Hilfe, {name}. Ich werde viel mit meinen Studien zu tun haben, wenn Joren uns hier abriegelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24487] = { id = 24487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weißbart braucht Euch", description = "Ihr habt uns hier einen großen Dienst erwiesen, doch befürchte ich, dass wir Euch weiterschicken müssen.\n\nEin guter Freund von mir, Grelin Weißbart, hat mich wissen lassen, dass er ein wenig Verstärkung gebrauchen könnte. Ihr findet ihn in der Nähe der Trolllager in Richtung Südwesten. Folgt der Straße Richtung Westen, dann solltet Ihr ihm früher oder später begegnen.\n\nAlles Gute, {name}. Troggs mögen vielleicht eine Plage sein, aber Trolle sind nicht zu unterschätzen.", sourceObjective = "Meldet Euch bei Grelin Weißbart im Eisklammtal.", completion = "Seid gegrüßt, {class}. Bereit, Euch an die Arbeit zu machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24488] = { id = 24488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ersatz", description = "Meine Jungs sitzen alle verletzt auf der Bank! Unsere Schredder sind nur noch Schrott! Der Schiri pfeift das Spiel gleich ab!\n\nDie letzte Minute läuft und ich brauche Euch, {name}!!!\n\nWir müssen einen dieser Schredder auf Vordermann bringen. Im Bilgepier liegen genügend Ersatzteile herum. Jeder grünblütige Kezanier überlässt sie Euch sicher gerne, wenn die Bukaniere dann eine Chance auf den Sieg haben.\n\nWir werden diesen nichtsnutzigen Dampfdruckhaien schon zeigen, wie man Fußbombe spielt.", sourceObjective = "Sammelt 6 Ersatzteile.", progress = "Wir verlassen uns auf Euch, {name}!", completion = "Das ist mein Junge! Jetzt muss ich diesen wertlosen Metallschrott nur noch in einen funktionierenden Zustand bringen und Euch raus aufs Spielfeld schicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[24489] = { id = 24489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollt Euch und lauscht", description = "Ich bin unglaublich schlecht darin, den Gesichtsausdruck von Trollen zu deuten. Daher kommen diese Trolle mir gar nicht wütend vor. Sie scheinen verwirrt... vielleicht ein wenig verängstigt.\n\nHier ist etwas passiert, was wir übersehen, {name}. Wir sollten der Sache ein wenig auf den Grund gehen, bevor wir einfach alle Trolle umbringen.\n\nHier in der Gegend gibt es drei Trolllager: eins im Südosten, eins im Südwesten und eins ganz im Westen. In jedem Lager gibt es eine Sterndeuterin... Schaut, ob ihr nahe genug an sie herankommt, dass Ihr belauschen könnt, was sie sagen.", sourceObjective = "Stellt Euch in jedem der Frostmähnenlager in die Nähe einer Sterndeuterin der Frostmähnen und lauscht dem, was sie zu sagen hat.", completion = "Hmm... interessant. Nach dem, was Ihr berichtet, scheint ein Feuerelementar sich aus der Sengenden Schlucht eingeschlichen zu haben. Oder das Erdbeben hat einen Riss in der Elementarebene geöffnet...\n\n<Soren lacht gequält.>\n\nSo oder so, das sind schlechte Neuigkeiten. Ihr solltet das lieber Grelin berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24490] = { id = 24490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Trip nach Eisenschmiede", description = "Die Präsenz eines Feuerelementars hier im Eisklammtal ist keine Kleinigkeit. Dieses Erdbeben hat doch mehr angerichtet, als nur ein paar Troggs zu verärgern... Es hat die Welt genug verändert, um einen Riss in der Elementarebene zu verursachen. Wir sollten einen Bericht nach Eisenschmiede schicken.\n\nIhr wärt nicht eventuell bereit, eine kleine Reise zu unternehmen, oder? Keine Sorge, Ihr seid genau <der Richtige/die Richtige>. Redet mit Hands Federspross beim Tunnel am östlichen Ende des Tals. Er weist Euch den richtigen Weg.", sourceObjective = "Sprecht mit Hands Federspross im Eisklammtal.", completion = "Nach Eisenschmiede? Nun, zuerst müsst Ihr durch Kharanos, aber davor müsst Ihr noch durch diesen Tunnel.", sourceObjectiveStatus = "unverified-source-field" }
quests[24491] = { id = 24491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt diesem Gyrokopter", description = "H-h-habt Ihr das gesehen? Wie die ganze Höhle einfach so zusammengestürzt ist? Ich glaube, Ihr seid genau rechtzeitig gekommen, keine Minute zu früh.\n\nObwohl diese Entwicklung meinen Job, die Höhle zu untersuchen, entschieden vereinfacht, wird es für Euch nun schwerer, nach Kharanos zu gelangen.\n\nHe, wartet, ich habe eine Idee! Die Luftfahrer aus Gnomeregan haben einen Flugpunkt nicht weit von hier. Ich werde ein Signal absetzen und sie sollten Hilfe schicken. Ich vermute, dass sie drüben in Ambossar landen werden.", sourceObjective = "Meldet Euch bei Milo Zwickrädchen nahe Ambossar.", completion = "Milo Zwickrädchen meldet sich zum Dienst. Ihr habt ein Notsignal abgesetzt?", sourceObjectiveStatus = "unverified-source-field" }
quests[24492] = { id = 24492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Packt Eure Taschen", description = "Aufgrund der Gewichtsbeschränkung meines Gyros kann nur <ein/eine:r> {race} mitfliegen. Sieht aus, als hättet Ihr Glück, {name}!\n\nDie Zwergin Jona hat mir erzählt, dass all Eure Sachen nach Ambossar gebracht wurden. Sammelt zusammen, was Ihr braucht, beendet Eure Angelegenheiten und kommt zu mir zurück, wenn Ihr bereit seid, aufzubrechen.", sourceObjective = "Erlangt einen Bierkrug der Eisklamm, einen struppigen Wolfsbalgumhang und ein paar Eberfleischreste.", progress = "Seid Ihr absolut sicher, dass Ihr Euch um alles gekümmert habt? Ihr werdet keine Zeit haben, nochmal herzukommen.", completion = "Hat ja auch lang genug gedauert. Haltet Euch gut fest und schaut Euch nochmal gut um! Höchstwahrscheinlich werdet Ihr eine ganze Weile nicht mehr herkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24493] = { id = 24493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst uns nicht", description = "Ihr verlasst uns? Denkt daran, Eure Vorräte aufzufüllen, bevor Ihr aufbrecht.\n\nWichtiger noch, sprecht mit Tharek Schwarzstein sobald Ihr in Kharanos eintrefft. Sagt ihm, was hier im Eisklammtal geschehen ist und dass wir ein wenig Hilfe gebrauchen könnten. Er wird hoffentlich etwas für uns organisieren können.", sourceObjective = "Meldet Euch bei Tharek Schwarzstein in Kharanos.", completion = "Das Eisklammtal? Ich habe hier meine eigenen Probleme. Was, die werden nicht mit ein paar Troggs fertig? Und Trollen? Und Übergriffen aus den Elementarebenen?\n\nAllerdings, wenn ich so darüber nachdenke... Das ist eine Menge. Ich bin überrascht, wie gut sie sich unter den Umständen halten. Ich werde sehen, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[24494] = { id = 24494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machterfüllte Rune", description = "{name}, diese Rune wurde mir gegeben, damit ich sie an Euch weiterreiche. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaub', sie stammt vom Schamanenlehrer Teo. Werft einen Blick auf die Rune und sucht ihn dann in Ambossar auf.", sourceObjective = "Lest die machterfüllte Rune und sprecht mit Teo Hammersturm in Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24495] = { id = 24495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fetzen der Vergangenheit", description = "Ich habe das Tagebuch eines Mannes namens Bradshaw gefunden. Leider fehlen viele Seiten, besonders gegen Ende.\n\nWenn Ihr genügend Seiten zusammentragt, kann ich vielleicht herausfinden, was nach dem Ausbruch des Fluchs hier geschehen ist.\n\nWer weiß… Vielleicht haben die Leute in diesem Dorf einen Fluchtweg gefunden. Vielleicht gibt es da draußen noch Überlebende.\n\nVielleicht ist mein Vater noch am Leben.", sourceObjective = "Sammelt 6 alte Tagebuchseiten.", progress = "Hattet Ihr schon Erfolg bei der Suche nach diesen Seiten?", completion = "Danke, {name}. Es wird ein wenig dauern, aber ich versuche, in dem was wir haben einen Sinn zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24496] = { id = 24496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rune", description = "{name}, diese Rune hier sollte ich an Euch weitergeben. Nehmt Euch Zeit und lest sie gut durch, sobald Ihr könnt. Ich glaube, sie kommt von der Magierlehrerin Teegli. Werft einen Blick darauf und dann sucht sie in Ambossar auf.", sourceObjective = "Lest die arkane Rune und sprecht dann mit Teegli Merrowith im Eisklammtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[24497] = { id = 24497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder in der Luft", description = "Wir haben gerade aus Valormok erfahren, dass wir keine weiteren Windreiter entsenden sollen, sonst werden sie von Heckenschützen der Talrendisspitze abgeschossen. Wir können Valormok nicht aufgeben, wenn wir eine sichere Route ins Eschental haben wollen, also gehen wir auf einem anderen Weg hinein.\n\nDie Fliegenden Priester haben großzügigerweise angeboten, einige unserer Leute von oberhalb der Reichweite der Heckenschützen abzusetzen. Geht zum Militärviertel und sichert Euch einen Flug auf einem ihrer Flugzeuge. Sie werden Euch dort in einem Stück abliefern und wenn Ihr erst einmal dort seid, könnt Ihr unsere Windreiterlinien wieder sichern.", sourceObjective = "Sichert Euch einen Flug nach Valormok mit den Fliegenden Priestern an der Ostseite des Bilgewasserhafens.", completion = "Es ist schon längst überfällig, Azshara von diesem Nachtelfenabschaum zu säubern. Ich bin froh, dass ich jemanden mit Euren Fähigkeiten habe, der mir helfen kann, das deutlich zu machen.\n\nSeid Ihr bereit, an die Arbeit zu gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24498] = { id = 24498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad zur Zitadelle", description = "Sie haben unsere gefangenen Soldaten zur Arbeit im Steinbruch eingesetzt!\n\nTötet ihre Entführer und befreit sie, <mein Held/meine Heldin>. Wir werden ihre Hilfe brauchen, wenn wir Geißelfürst Tyrannus entgegentreten.", sourceObjective = "Befreit 15 Allianzsklaven und tötet Schmiedemeister Garfrost.", completion = "Ihr habt heute gute Arbeit geleistet.\n\nJetzt, wo viele der Sklaven befreit sind und wir Zugang zu den Schmieden haben, wird es nicht mehr lange dauern, bis ich eine starke Mannschaft zusammen habe, die uns helfen wird, uns aus den Fängen des Geißelfürsten Tyrannus und seiner widerwärtigen Grube zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[24499] = { id = 24499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos gequälter Seelen", description = "Wir sind eindeutig zu wenige, um uns in die Zitadelle zu wagen, doch so eine Gelegenheit dürfen wir uns nicht entgehen lassen.\n\nRäumt die Feinde bis ganz nach hinten aus dem Weg und sichert den Pfad zur Grube von Saron, damit unsere Leute weiter in die Zitadelle vordringen können.", sourceObjective = "Tötet Bronjahm und den Verschlinger der Seelen, um den Zugang zur Grube von Saron zu sichern.", completion = "Die Grube von Saron liegt direkt vor uns, und wenn unsere Späher richtig liegen, befinden sich dahinter die Hallen der Reflexion.\n\nDiesen Ort lässt Arthas nicht so stark bewachen. Wir hoffen, dass wir dort einen Hinweis auf seine Schwachstelle finden... und vielleicht sogar den Schlüssel zu seiner Erlösung.", sourceObjectiveStatus = "unverified-source-field" }
quests[24500] = { id = 24500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Lichkönigs", description = "Es besteht wohl kaum Hoffnung, Arthas auf den Stufen seines eigenen Thrones zu besiegen. Und wer übernimmt in diesem Fall die Krone des Lichkönigs?\n\nViele Fragen sind noch offen, doch zuerst müsst Ihr Jaina finden und vor dem Lichkönig fliehen, solange noch Zeit dazu ist.", sourceObjective = "Findet Lady Jaina Prachtmeer und flieht aus den Hallen der Reflexion.", completion = "<Jaina ringt noch immer nach Luft.>\n\nIch kann kaum glauben, dass wir noch am Leben sind. Es war dumm von mir, ihm zu folgen. Zu oft habe ich diesen Fehler begangen. Und Ihr... es war ziemlich unbesonnen, mir zu folgen, anstatt mit den Informationen zu fliehen!\n\nAber... nun ja... danke. Das war wirklich heldenhaft.\n\nMit Uthers Hilfe haben wir vielleicht eine Chance, Arthas zu besiegen. Dann hätten alle, die heute gestorben sind, ihr Leben nicht umsonst gelassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24501] = { id = 24501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinne am Morgen bringt Kummer und Sorgen", description = "Die Flut der Spinnen nimmt kein Ende, {name}. Ihr müsst in ihr Nest gehen und die Brutmutter töten.\n\nWir haben die riesige Spinne namens Rygna zuletzt am Rand des Schwarzforstes gesehen, in einer Gegend, die ganz mit dicken Netzen bedeckt war. Es wird gefährlich, aber wir verlassen uns auf Euch.", sourceObjective = "Tötet Rygna in Rygnas Hort.", completion = "Gute Arbeit, {name}. Wir haben gehört, dass es weiter oben in den Bergen noch Überlebende geben soll. Jetzt können wir endlich Späher dorthin schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24502] = { id = 24502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notwendige Gewaltanwendung", description = "Wir haben nur noch einen Schredder. Als gerade niemand hingesehen hat, habe ich ihn mit, nun ja, sagen wir, modifizierten Fußbomben geladen.\n\nIhr müsst diesen Schredder nehmen und ihnen das Leben zur Hölle machen!", sourceObjective = "Benutzt den Bilgewasserbukanier und werft die Fußbombe auf 8 Dampfdruckhaie.", sourceObjectiveStatus = "unverified-source-field" }
quests[24503] = { id = 24503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drölfmeterschießen", description = "Jetzt liegt es an Euch, <Junge/Mädel>! Ihr habt die Dampfdruckhaie vernichtet. Jetzt müsst Ihr nur noch das Siegtor schießen.\n\nJetzt mal unter uns. Ich finde, wir sollten dieses Mal alles richtig machen. Ich möchte nicht, dass Ihr einfach nur ein Tor schießt... Ich möchte, dass Ihr so weit schießt, dass die Bombe bis zwischen die beiden Schornsteine hinter dem Tor fliegt!\n\nIch habe die Fußbombe so präpariert, dass sie dafür die richtige Zusatzleistung hat.\n\nUnd jetzt raus da und macht mich stolz!", sourceObjective = "Schießt das Siegertor, indem Ihr die Fußbombe zwischen die beiden Schornsteine hinter dem gegnerischen Tor schießt.", completion = "Äh… Ihr habt es geschafft, Junge. Ihr habt es ECHT geschafft! Wir haben das Spiel gewonnen und… \n\nHABT IHR DIESEN DRACHEN GESEHEN?!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24504] = { id = 24504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säubert den Höhenpfad", description = "Hier entlang, {class}! Wie ich sehe, habt Ihr den Höhenpfad entdeckt.\n\nDie Allianz hofft, dass sie unsere Verbindungen zum Steinkrallengebirge abschneiden kann, aber sie haben vergessen, dass wir Tauren seit Generationen in diesen Landen jagen. Wir kennen jede Spitzkehre an den Hängen und jeden Wildpfad von hier nach Tausend Nadeln.\n\nAber damit diese Pfade offen bleiben, müssen wir die Menschen daran hindern, sie zu vermessen.\n\nLauft auf dem östlichen Pfad Patrouille und tötet alle Späher des Höhenpfads, die Ihr unterwegs findet. Dann sprecht mit Tunawa Stillwind, den Ihr ein Stück weiter den Pfad entlang findet.", sourceObjective = "Tötet 3 Späher des Höhenpfads.", completion = "Auf dem Höhenpfad zu patrouillieren ist eine lebensgefährliche Aufgabe, aber sie muss erledigt werden. Diese engen Bergpfade sind im Moment unsere einzige Lebenslinien ins Steinkrallengebirge. Sie müssen erhalten werden.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24505] = { id = 24505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Jägerhügel ausharren", description = "Ehrenwacht mag verloren sein, aber sein Geist ist niemals zerstört worden. Sogar jetzt harren Überlebende noch an einem Ort aus, der \"Jägerhügel\" genannt wird.\n\nFolgt dem Höhenpfad weiter und Ihr werdet ihr Lager genau vor uns finden. Wenn Ihr dort eintrefft, sprecht mit Onatay und lasst sie wissen, dass der Pfad - für den Moment jedenfalls - immer noch sicher ist.", sourceObjective = "Sprecht mit Onatay am Jägerhügel im Südlichen Brachland.", completion = "Also die Allianz erkundet die Drehungen und Wendungen des Höhenpfads?\n\nSelbst wenn es ihnen gelingt, ihn zu kartographieren, könnten sie diese Hügel nicht mit vielen Leuten angreifen. Dies ist unser Land, {name}. Und sie werden es teuer bezahlen, wenn sie etwas anderes glauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24506] = { id = 24506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der eisigen Zitadelle", description = "{class}! Kommt schnell her - ich muss mit Euch reden!\n\nMeine Königin, Fürstin Sylvanas Windläufer, hat eine Lücke in der Verteidigung der Eiskronenzitadelle entdeckt, die zu einem Ort namens \"Die Seelenschmiede\" führt. Bevor sie sich auf den Weg machte, hat sie mich mit der Suche nach grimmigen Kämpfern beauftragt, die sich dorthin wagen. Ihr scheint mir dafür geeignet.\n\nTrefft sie am Eingang der Schmiede, {class}!", sourceObjective = "Betretet die Seelenschmiede von der Seite der Eiskronenzitadelle und findet Fürstin Sylvanas Windläufer.", completion = "Gut. {name}, ich weiß einiges über Euch. Ihr seid wie gemacht für diese Aufgaben.\n\nUns bietet sich die seltene Gelegenheit, die Eiskronenzitadelle zu erkunden. Doch wir müssen uns beeilen, wenn wir nicht wollen, dass Arthas etwas merkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24507] = { id = 24507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad zur Zitadelle", description = "Sie lassen unsere entführten Soldaten im Steinbruch schuften. Tötet die Entführer und befreit die Gefangenen, {class}! Wir brauchen ihre Hilfe, wenn wir Geißelfürst Tyrannus gegenübertreten.", sourceObjective = "Befreit 15 Hordensklaven und tötet Schmiedemeister Garfrost.", completion = "Ihr habt heute gute Arbeit geleistet.\n\nJetzt, wo viele der Sklaven befreit sind und wir Zugang zu den Schmieden haben, wird es nicht mehr lange dauern, bis ich eine starke Mannschaft zusammen habe, die uns helfen wird, uns aus den Fängen des Geißelfürsten Tyrannus und seiner widerwärtigen Grube zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[24508] = { id = 24508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temp Quest Record" }
quests[24509] = { id = 24509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temp Quest Record" }
quests[24510] = { id = 24510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der eisigen Zitadelle", description = "{class}! Kommt schnell her - ich muss mit Euch reden!\n\nMeine Herrin, Lady Jaina Prachtmeer, hat eine Lücke in der Verteidigung der Eiskronenzitadelle entdeckt, die zu einem Ort namens \"Die Seelenschmiede\" führt. Bevor sie sich auf den Weg machte, erhielt ich die Aufgabe, alle Hilfe zu suchen, die ich finden kann... und, nun ja, ich hatte da an Euch gedacht.\n\nBitte, sucht sie so schnell wie möglich dort auf!", sourceObjective = "Betretet die Seelenschmiede von der Seite der Eiskronenzitadelle und findet Lady Jaina Prachtmeer.", completion = "{name}! Ich bin so froh, dass Ihr gekommen seid!\n\nUns bietet sich die seltene Gelegenheit, die Eiskronenzitadelle zu erkunden. Doch wir müssen uns beeilen, wenn wir nicht wollen, dass Arthas etwas merkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24511] = { id = 24511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos gequälter Seelen", description = "Es ist ziemlich gefährlich, mit so wenig Leuten die Zitadelle zu betreten, doch so eine Gelegenheit bekommt man nicht alle Tage.\n\nBereitet einen Weg zum anderen Ende und sichert den Pfad zur Grube von Saron, damit unsere Leute weiter in die Zitadelle vordringen können.", sourceObjective = "Tötet Bronjahm und den Verschlinger der Seelen, um den Zugang zur Grube von Saron zu sichern.", completion = "Die Grube von Saron liegt direkt vor uns, und wenn unsere Späher richtig liegen, befinden sich dahinter die Hallen der Reflexion. Diesen Ort lässt Arthas nicht so stark bewachen, und an diesem Ort hoffen wir, ein Anzeichen von Schwäche bei ihm entdecken zu können... und eine Möglichkeit zur Rache, die schon so lange überfällig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24512] = { id = 24512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung eines Kriegers", description = "Diejenigen, die sich beim Fall von Ehrenwacht ergeben haben, sind der Horde nicht länger würdig, {class}. Doch ich werde sie noch nicht aufgeben. Der Gefängnisturm unter uns ist nur leicht bewacht. Geben wir den Gefangenen eine letzte Chance, ehrenhaft zu sterben.\n\nIch habe Seile in Position gebracht, die es Euch erlauben werden, schnell den Berg hinauf- und hinunterzuklettern. Schleicht Euch hinunter, bringt die beschlagnahmten Waffen an Euch und bewaffnet die Gefangenen, die sich im Turm befinden.\n\nUnd {name} - bleibt beim Turm! Wir sind in der Basis noch nicht ausreichend ausgerüstet, um einen Angriff zu überstehen.", sourceObjective = "Bringt 5 Kisten mit konfiszierten Waffen aus Ehrenwacht an Euch und rüstet 5 Gefangene aus dem Steinkrallengebirge damit aus. Benutzt die Seile in der Nähe, um Euch schnell in das Lager der Allianz hinein- und hinauszubewegen.", completion = "Von hier oben habe ich einen genauen Überblick über das Chaos, das Ihr gerade angerichtet habt, {name}. Unsere verlorenen Brüder haben ein wenig ihrer Würde wiedergewonnen und die Hunde der Allianz wurden in die Flucht gejagt. Präzise Arbeit, mein Freund!\n\nWenn die Allianz heute Nacht gut schläft, machen wir etwas falsch.\n\nWir werden niemals nachgeben.\n\nWir werden niemals aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24513] = { id = 24513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Auge", description = "Wer ist da? Eure Schritte klingen nicht wie das faule Schlurfen der Wachen.\n\n<Ein/Eine:c> {class}, sagt Ihr? Immer noch tapfer und frei? Für mich gibt es keine Hoffnung, <mein Freund/meine Liebe>. Ich habe mein Augenlicht verloren und bin nicht länger kampftauglich.\n\nIch habe es gewagt, meine Stimme zu erheben, als Hauptmann Peake einen der Gefangenen schwer misshandelte. Als Antwort hat er mich gegen den Kopf getreten. Immer wieder. Er hat auf mir herumgetrampelt, bis ich blind war, {race}.\n\nIhr findet Hauptmann Peake oben auf seinem Turm. Wenn Ihr Gerechtigkeit wollt, bringt mir seine Augen.\n\nWenn er sie nicht freiwillig hergibt... so sei es.", sourceObjective = "Tötet Hauptmann Peake und bringt seine Augen zu Oltarg.", progress = "Peake ist ein Monster. Wenn seine Vorgesetzten davon wüssten, wären sie der Horde dankbar, dass diese ihm ein Ende bereitet hat.", completion = "Habt Ihr sie? Ich verlasse mich blind auf Euch. Zu hören, das Peake wie eins seiner Opfer brüllt, ist genug Belohnung für mich.\n\nNun lasst mich allein, {name}. Ich möchte meinem Klan keine Bürde sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24514] = { id = 24514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenreste", description = "Wir werden hier belagert, {class}. Durch den Abgrund einerseits und die ständige Belästigung durch die Allianz andererseits sind die Vorräte knapp geworden. Aber wir schlagen uns mit dem, was da ist, durch - so, wie wir Tauren das immer getan haben.\n\nWir haben keine Schmiede, aber wer geschickt in der Lederverarbeitung ist, kann unsere beschädigte Rüstung mit qualitativ hochwertigen Bälgen verstärken oder zusammenflicken.\n\nDort unten sind die Jagdgründe der Schreckenszahnraptoren. Sie sind nicht leicht zu töten - was zum Teil an der Robustheit ihrer dicken Bälge liegt. Jagt sie, {name} und bringt mir ihre Bälge!", sourceObjective = "Besorgt 8 Schreckenszahnbälge von Schreckenszahnläufern und Schreckenszahnsensenklauen.", progress = "Schreckenszahnraptoren jagen im Rudel und kreisen ihre Beute ein. Wir jagen sie, ja, aber wir respektieren sie auch.", completion = "<Onatay lässt ihren Blick über die frischen Bälge schweifen und nickt langsam.>\n\nJa {name}, damit kann ich arbeiten. Ihr arbeitet schnell!\n\nDiese Bälge werden uns dabei helfen, noch länger auszuharren, bis Verstärkung kommt. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24515] = { id = 24515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signale am Himmel", description = "Wendet Euren Blick nach Südosten. Seht Ihr den Rauch der Lagerfeuer von Camp Una'fe?\n\nVor noch nicht einmal zehn Minuten sah ich aus dem Zentrum des Lagers große weiße Rauchwolken gen Himmel aufsteigen. Das war ein altes Signal, das mein Dorf dazu verwendete, die Jagd über große Entfernungen hinweg zu koordinieren. Doch diesmal war es ein Notrufsignal.\n\n{name}, mein Bruder Makaba ist in diesen unnatürlichen Dschungel gegangen. Bitte geht dorthin und stellt sicher, dass er nicht in Schwierigkeiten steckt.\n\nEs gibt verschiedene Wege... Schaut Euch in der Wildnis nach Zelten um.", sourceObjective = "Begebt Euch nach Camp Una'fe in der Überwucherung des Südlichen Brachlands und sprecht mit Makaba Flachhuf.", completion = "Also hat meine Schwester die alten Signale erkannt? Ihre Jägeraugen sind scharf wie immer.\n\n{name}, als wir dieses Lager aufschlugen, waren wir am Rand des Dschungels. Jetzt schaut Euch um!\n\nIrgendetwas fehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24517] = { id = 24517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt ihnen Angst ein", description = "Seht Ihr die Spur dort unter uns, {name}? Das ist MEINE Spur. Und wenn diese Hunde der Allianz sich an meine Spur heften, dann sollten sie aufpassen, was hinter ihnen vor sich geht.\n\nEs wird Zeit, dass ich meinen Wegzoll einfordere. Tötet die Fußsoldaten der Ehrenwacht und schaut, ob wir sie nicht wie die Hasen wieder hinter ihre Mauern jagen können.\n\nAchtet darauf, dass Ihr mindestens einen ihrer Offiziere tötet, die die Straße entlang patrouillieren. Ihnen muss klar werden, dass niemand sicher ist.", sourceObjective = "Tötet 8 Fußsoldaten der Ehrenwacht und 1 Offizier der Ehrenwacht.", completion = "Ausgezeichnet, {name}. Es wird eine Weile dauern, bevor wir die Festung selbst angreifen können, aber bis dahin müssen wir ihnen Angst vor dem Brachland einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24518] = { id = 24518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tiefenpfad", description = "Dieser Stapel Papiere wurde in einer Ledertasche unter den Kleidern des Offiziers versteckt gefunden.\n\nSchlachtpläne der Region, die Ehrenwacht darstellen, das mit einer langen, unfertigen Straße verbunden zu sein scheint, die sich von Theramore aus quer durch das Brachland erstreckt. Es sieht so aus, als ob die Allianz plant, eine Straße von der Küste bis hinein ins Herz von Kalimdor zu bauen.\n\nKilrok Grindhammer wird das sicher sehen wollen.", sourceObjective = "Liefert die Straßenbaupläne bei Kilrok Grindhammer am Jägerhügel im Südlichen Brachland ab.\n\nBereitgestellter Gegenstand:", progress = "Ah, Ihr sagt, Ihr hättet etwas bei einer der Leichen gefunden?", completion = "<Kilrok überfliegt die Pläne, die Ihr entdeckt habt.>\n\nDas erklärt einiges, {name}. Kein Wunder, dass unsere Feinde so versessen darauf sind, das Südliche Brachland einzunehmen. Es ist das Zentrum ihrer Pläne für den Kontinent!\n\nAber sie haben die Rechnung ohne uns gemacht, nicht wahr, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24519] = { id = 24519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vermessung unterbinden", description = "Diese Karten wurden alle von derselben ruhigen Hand gezeichnet. Ich hab einen Vermesser der Menschen gesehen, der die Straße zwischen der Burg und dem Dschungel im Osten entlanggelaufen ist.\n\nWir können ihnen einen Strich durch die Rechnung machen, indem wir an diesem Vermesser ein Exempel statuieren, {name}.\n\n<Kilrok zeigt auf die Unterschrift unten auf den Karten.>\n\nWas meint Ihr, was dort steht? \"Zykes\"? Sogar menschliche Namen klingen dünn und schwach. Tötet ihn!", sourceObjective = "Findet und tötet den Feldmesser Henry Zykes.", completion = "Gut, gut! Wir müssen Ehrenwacht isoliert halten.\n\nAlleine...verängstigt... {name}, wenn wir sie unter Druck setzen, werden sie vielleicht eines Tages sogar den Pfad einfach aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24520] = { id = 24520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten für Sassy", description = "Ich würde ja mit Euch feiern, aber ich fürchte, dass der Drache dem guten alten Kajaro ganz schön zugesetzt hat. Ich… äh… Ich glaube, ich packe meine Sachen und nehme das erste Schiff, das die Insel verlässt.\n\nIhr solltet jedenfalls zum Hauptgeschäftssitz zurückkehren und Sassy erzählen, dass Ihr den Fußbombentitel für uns gewonnen habt. Ich bin mir sicher, dass sie auch über den Drachen und den Kajaro Bescheid wissen möchte.\n\nViel Glück!", sourceObjective = "Sprecht mit Sassy Hartzang im Hauptgeschäftssitz der HGK auf Kezan.", completion = "Ihr macht Witze, oder?! TODESSCHWINGE?!!!\n\n<Sassy sieht einen Moment lang panisch aus.>\n\nOkay, das wird schon. Wir veranstalten Eure Party, und bis wir damit fertig sind, ist der Drache sicher schon lange weg und der Boden hat zu zittern aufgehört.\n\nFalls nicht, können wir immer noch ein Schiff chartern und von hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24521] = { id = 24521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch für ein Testspiel", description = "{name}, Trainer Blutgrätsch, der Kopf unserer furchtlosen Bilgewasserbukaniere, sucht Euch.\n\nEr sagt, dass der Ligatitel gegen die Dampfdruckhaie in Gefahr ist und dass nur Ihr den Pokal nach Hause holen könnt!\n\nGeht nach Westen in die Stadt. Ihr könnt das Kajarofeld nicht verfehlen!", sourceObjective = "Sprecht mit Trainer Blutgrätsch auf dem Kajarofeld auf Kezan.", sourceObjectiveStatus = "unverified-source-field" }
quests[24522] = { id = 24522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Sonnenbrunnen", description = "Bringt Quel'Delar so schnell wie möglich zum Sonnenbrunnen, {name}! Glaubt Uthers Worten, dass Ihr die Kontrolle über die Klinge nicht immer behalten könnt, wenn sie dem bösen Einfluss des Lichkönigs ausgesetzt ist. Ihr müsst zur Insel von Quel'Danas reisen und versuchen, zum Sonnenbrunnen zu gelangen, um das Schwert zu läutern.\n\nDie Wächter des Sonnenbrunnens werden Euch nicht so einfach Zutritt gewähren. Daher müsst Ihr Euch an Halduron Wolkenglanz wenden, der ein Auge auf die Wachen dort hat.", sourceObjective = "Sprecht mit Halduron Wolkenglanz am Eingang des Sonnenbrunnenplateaus auf der Insel von Quel'Danas.", progress = "Was führt Euch hierher?", completion = "Ihr wollt Zugang zum Sonnenbrunnen? Das ist unmöglich! Der Sonnenbrunnen ist unserem Volk der heiligste und wichtigste Ort. Erst kürzlich konnten wir ihn durch die Hilfe der Offensive der Zerschmetterten Sonne zurückgewinnen. Er ist kein Ort für Touristen und Reisende.", sourceObjectiveStatus = "unverified-source-field" }
quests[24523] = { id = 24523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem der Wildmähnen", description = "Es gibt nur noch einen Brunnen, der gesäubert werden muss; er trägt den Namen des Wildmähnenklans. Damit dieser Brunnen wieder rein wird, muss das Land die Zähne eines wilden Raubtiers opfern, die eines Präriewolfalphatiers. Findet die Alphatiere im Norden und kehrt dann zu mir zurück, wenn Ihr Eure Jagd beendet habt.\n\nAlphatiere streifen oft am Fuße unserer mächtigen Stadt Donnerfels umher.", sourceObjective = "Sammelt 4 Präriealphazähne von Präriewolfalphas.", progress = "{name}. Habt Ihr die Zähne, um die ich gebeten habe?", completion = "Sehr gut, {name}. Ich kann das Opfer fühlen, das das Land gebracht hat, und mein Geist ist erfüllt von Traurigkeit und Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[24524] = { id = 24524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmähnensäuberung", description = "Die Geister sprechen von Eurer Säuberung der Brunnen der Winterhufe und Donnerhörner, {name}. Das Totem der Wildmähnen ist fertig und die letzte Aufgabe erwartet Euch.\n\nDer Brunnen der Wildmähnen liegt nördlich von Donnerfels. Führt das Ritual durch! Heilt das Land vom Gift der Grimmtotems! Lasst das Wasser wieder klar und rein fließen!", sourceObjective = "Benutzt das Läuterungstotem der Wildmähnen beim Brunnen der Wildmähnen.", progress = "Einer der Brunnen stinkt immer noch und verbreitet sein Gift, {name}. Ihr müsst Euch beeilen.", completion = "Ihr habt es geschafft. Ihr habt die Brunnen gesäubert und unser Land geheilt. Das Dorf der Bluthufe dankt Euch, {name}.\n\nMöge der Wind Kunde von Euren Taten in alle Welt tragen und mögen die Wasser von Mulgore bis in alle Ewigkeit rein sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24525] = { id = 24525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hunde in Schach halten", description = "Nicht jeder, der aus Taurajo geflohen ist, hat es nach Una'fe geschafft, {name}. Einige starben unterwegs an ihren Verletzungen. Andere wurden von opportunistischen Stachelebern angegriffen.\n\nIch habe die grausige Aufgabe, die Leichen zu finden und einzusammeln. Aber Ihr könnt etwas für mich tun.\n\nFleischreißerstrauchdiebe durchstreifen die Lande südlich von hier und zerreißen die Leichen, zerren an ihren Eingeweiden herum und schleppen die Extremitäten der Toten davon. Bitte dezimiert sie, damit ich die gebotenen Beerdigungsrituale durchführen kann.", sourceObjective = "Tötet 6 Fleischreißerstrauchdiebe.", completion = "Es ist also vollbracht.\n\nEigentlich sind diese Strauchdiebe ein Teil des Lebenszyklus' der Erdenmutter. Aber im Zuge der Zerstörung, die sowohl die Allianz als auch der Kataklysmus über uns gebracht haben, wächst ihre Zahl ins Unermessliche. Es ist gut, sie wieder zu dezimieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24526] = { id = 24526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstocken des Zauberbuchs", description = "Exzellent! Lasst uns beginnen.\n\nWenn Ihr an Macht gewinnt, wird sich Eure Verbindung zum Arkanen vertiefen und Ihr werdet Zugang zu neuen Zaubern und Fähigkeiten erhalten.\n\nGeht, sammelt Erfahrungen, und Ihr werdet sehen, was ich meine. Kommt zurück, wenn Ihr etwas Neues erlernt habt und demonstriert es an den Trainingsattrappen hier.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Wirkt den Zauber erfolgreich zweimal auf den Trainingsattrappen vor dem Eingang nach Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24527] = { id = 24527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn Eures Wegs", description = "Ausgezeichnet! Lasst uns anfangen.\n\nWenn Ihr auf Eurem Weg erfahrener werdet, werdet Ihr die uralten Geheimnisse der Schamanen entschlüsseln.\n\n'Urtümlicher Schlag' ist eine solche Fähigkeit. Die urtümlichen Geister, wenn sie herbeigerufen sind, werden Euren Arm stärken, um einen mächtigen Schlag auszuführen.\n\nHilfreich, nicht wahr?", sourceObjective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Übt anschließend 'Urtümlicher Schlag' zweimal an einer Übungsattrappe nahe des Eingangs zu Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24528] = { id = 24528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Lichts", description = "Seid Ihr bereit? Wunderbar! Wir sind froh, dass Ihr hier seid.\n\nJe stärker Ihr werdet, desto näher kommt Ihr dem Licht und könnt neue Techniken lernen. Also zieht los und sammelt etwas Erfahrung. Zeigt mir dann, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3, um das Siegel des Befehls zu erlernen. Wirkt das Siegel des Befehls auf Euch selbst und schlagt dann eine Trainingsattrappe am Eingang zu Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24529] = { id = 24529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Regen in die Traufe", description = "Als die Flüchtlinge von Taurajo aus nach Norden flohen, wurden einige von ihnen in der aufziehenden Dunkelheit von den anderen getrennt. Viele wurden von den Stachelebern der Borstennacken gefangen genommen, die ihre Lager im Westen und Südwesten von hier aufgeschlagen haben.\n\nIch weiß nicht, was die Stacheleber sich von uns erhofften, als sie unsere Flüchtlinge gefangennahmen - das Einzige, was sie sich dadurch zugezogen haben, ist mein Zorn. Und alles, was sie im Gegenzug erhalten werden, ist Rache.\n\nBefreit meine gefangenen Brüder und Schwestern und sendet den Stachelebern eine Botschaft, indem Ihr diejenigen tötet, die sie gefangen nahmen.", sourceObjective = "Rettet 5 eingesperrte Flüchtlinge aus Taurajo und tötet insgesamt 8 Dornenwirker oder Klingenwächter der Borstennacken.", completion = "Es ist schlimm genug, wenn das eigene Dorf ausgeraubt wird... aber die nächste Nacht in einem Stacheleberkäfig zu verbringen? Ich bin froh, dass Ihr da wart, um zu helfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24530] = { id = 24530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ah, das Leben eines Jägers", description = "Das Leben eines Jägers ist tief in Traditionen verwurzelt, wisst Ihr? Aufspüren mächtiger Bestien in wildem Terrain. Trinken. Die Lande bereisen, das Gewehr stets griffbereit. Trinken. Überleben dank Finesse, Mut und Instinkt, gefolgt von einem ordentlichen Schluck zu trinken.\n\nAber bevor wir zu den guten Sachen kommen, müsst Ihr die Grundlagen erlernen.\n\nGeht, macht Eure eigenen Erfahrungen und Ihr werdet lernen, mehr Dinge hinzukriegen. Und darauf trinken wir dann einen.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen und verwendet ihn dann fünfmal bei den Trainingsattrappen vor dem Eingang nach Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24531] = { id = 24531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereitmachen für die Schlacht", description = "Lektion eins. Abgesehen von Eurem Schwert und Schild, was ist das wichtigste Utensil in Eurem Arsenal?\n\n<Thran wartet auf eine Antwort.>\n\nAch, macht nichts, ich werde für Euch antworten. Es ist Erfahrung.\n\nWenn Ihr erfahrener werdet, entdeckt Ihr neue Techniken. Was bedeutet, dass Ihr effektiver werdet - effektiver, als Ihr es Euch je hättet träumen lassen.\n\nGeht, sammelt Erfahrungen und erlernt etwas Neues. Kommt dann zurück und demonstriert es.", sourceObjective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen und verwendet es dann bei einer der Trainingsattrappen vor dem Eingang nach Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24532] = { id = 24532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Gegner ausweiden", description = "Wenn Ihr erst einmal mehr Erfahrung gesammelt habt, werdet Ihr feststellen, dass Ihr neue Techniken nutzen könnt. \n\nEines der Dinge, die Ihr lernen werdet, ist die Fähigkeit, eine Kombination von Kampfmanövern zu verwenden, um einen Gegner zu schwächen, um ihn dann mit einer vernichtenden Technik fertigzumachen.\n\nUnd jetzt macht Euch auf und sammelt Erfahrung. Wenn Ihr neue Techniken gelernt habt, probiert sie einfach an einer der Trainingsattrappen hier aus.", sourceObjective = "Erreicht Stufe 3 und erlernt das Ausweiden. Wendet es dann 3-mal auf die Trainingsattrappen vor dem Eingang nach Ambossar an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24533] = { id = 24533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Macht", description = "Also, wenn Ihr wirklich etwas Besonderes werden wollt, solltet Ihr mit mir sprechen. Ein Priester ist ein Niemand ohne seine Zaubersprüche. Und wie könnt Ihr wohl neue Zauber lernen?\n\nIndem Ihr Erfahrung sammelt! Also zieht los, werdet stärker und kommt dann wieder zurück, um mir zu zeigen, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3, um das Schattenwort: Schmerz zu erlernen. Wirkt es dann 5-mal auf die Trainingsattrappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24534] = { id = 24534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Sprache sprechen", description = "Die Stacheleber greifen uns an, weil sie Schwäche spüren. Stärke ist die einzige Sprache, die sie verstehen. Also werden wir ihnen Stärke zeigen.\n\n<Makaba zieht ein großes Horn aus seinem Beutel.>\n\nZugegeben, das hier ist primitive Arbeit, aber es wird reichen. Die Anführer der Borstennacken benutzen Hörner wie dieses, um sich gegenseitig zu Revierkämpfen herauszufordern.\n\n{name}, ich möchte, dass Ihr Säbelschnauze, den Champion der Borstennacken, zu einem Einzelkampf herausfordert. Besiegt ihn vor den Augen seiner Anhänger. Lasst das Horn am Herausforderungsring der Borstennacken südlich von hier erschallen.", sourceObjective = "Lasst das Horn der Herausforderung am Herausforderungsring der Borstennacken erschallen und besiegt Säbelschnauze in einem Einzelkampf.", progress = "Habt Ihr den Borstennacken einen Dämpfer versetzt?", completion = "Wie bitte? Er hat Euch mit einem Dutzend Eber angegriffen? Anscheinend haben die Stacheleber ihre eigenen Vorstellungen, was \"Einzelkampf\" bedeutet.\n\nDennoch, die Borstennacken werden nach dem Schlag, den Ihr ihnen versetzt habt, aus der Bahn geworfen sein. Es wird nicht lange dauern, bis ein neuer Champion sich in ihren Reihen erhebt, um weiteren Ärger zu verursachen...doch bis dahin haben wir ein wenig Zeit gewonnen, um die Flüchtlinge in Sicherheit zu bringen.\n\nDanke, {name}, die Überlebenden haben Euch viel zu verdanken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24535] = { id = 24535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Morgensucher", description = "Solltet Ihr Quel'Delar wirklich bei Euch tragen, {name}, kann ich Euch vielleicht Zutritt zum Sonnenbrunnen verschaffen. Wenn Ihr die Geschichte der Klinge kennt, erinnert Ihr Euch vielleicht, dass Thalorien Morgensucher sie bei der Verteidigung des Sonnenbrunnens gegen die Geißel führte. Er fiel dort, wo sich heute die Todesschneise befindet, und verschaffte so seinen Leuten Zeit, eigene Vorbereitungen zu treffen. Seine sterblichen Überreste befinden sich am südlichen Ende der Todesschneise auf dieser Insel. Begebt Euch dorthin, damit sein Geist Euch den Segen erteilt, zum Sonnenbrunnen zu gehen.", sourceObjective = "Besucht die sterblichen Überreste Thalorien Morgensuchers und erhaltet seinen Segen zum Führen Quel'Delars.", progress = "Seid Ihr an dem Ort gewesen, an dem Thalorien fiel, als er den Sonnenbrunnen verteidigte?", completion = "Ich gebe zu, dass ich nicht erwartet hätte, dass Thalorien Euch als Erben Quel'Delars anerkennt, aber ich respektiere sein Urteil. Ihr dürft zum Sonnenbrunnen gehen, doch ich erinnere Euch daran, dass Ihr an unserem allerheiligsten Ort zu Gast seid und Euch dementsprechend zu verhalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24536] = { id = 24536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas stinkt hier", description = "Man sieh sich diese Kerle an. Das Dampfdruckkartell betreibt das Valentinstagsgeschäft schon seit Jahren, und plötzlich tauchen diese Typen auf. Die gehören nicht zum Kartell. Das Kartell hat mich beauftragt, der Sache auf den Grund zu gehen. Irgendwas stinkt hier, und damit meine ich nicht das Parfüm.\n\nNehmt das Gerät, das ich mitgebracht habe, um damit die Parfümwolken zu untersuchen, die die Wachen umgeben. Ich möchte wissen, was sie in das Zeug reintun. Irgendwas ist da faul.", sourceObjective = "Verwendet Schnappbolzens Luftanalysegerät, um die Luft zu untersuchen, die 6 stark parfümierte Wachen umgibt, und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Hey, vielen Dank! Gebt her und lasst mal sehen!\n\n<Er nimmt das Gerät an sich und hantiert damit herum.>\n\nOh, das ist gar nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[24539] = { id = 24539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Pflanzen angreifen", description = "Dieses Camp wurde am Rande dieses Dschungels erbaut und ist bereits vollkommen von Pflanzen überwuchert. Irgendetwas Unnatürliches geht hier vor.\n\nVor Kurzem habe ich den Fehler gemacht, einige der gesunden Flüchtlinge hinauszuschicken, um Nüsse und Beeren zu sammeln. Diejenigen, die zurückkehrten, berichteten, dass die Pflanzen nach ihren Beinen gegriffen oder sie sogar hochgehoben hätten. Ich mache mir Sorgen um diejenigen, die noch nicht zurückgekehrt sind.\n\n{class}, bitte rettet die Flüchtlinge, die in dem klammernden Überwuchs um das Camp herum festgehalten werden.", sourceObjective = "Rettet 5 Flüchtling aus Taurajo, indem Ihr den klammernden Überwuchs tötet, der sie festhält.", completion = "Danke, {name}. Aber wenden wir uns nun der eigentlichen Frage zu:\n\nWo kommt dieser Überwuchs her? Und warum ist er so außer Kontrolle?", sourceObjectiveStatus = "unverified-source-field" }
quests[24540] = { id = 24540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegstanz", description = "Unser Volk wird von vielen als Volk der sanftmütigen Riesen oder der edlen Wilden angesehen. Sie haben nie gesehen, wie wir uns gegenseitig bekämpfen... wie wir Verräter aus eigenen Reihen bekämpfen.\n\nDen Grimmtotems wurde durch das Exil Gnade erteilt, doch sie haben ihre Heimat verletzt, um Rache an uns zu üben. Wir werden sie in Mulgore nicht länger akzeptieren.\n\nIch habe bereits Krieger geschickt, um sie durch den Steinkrallenpass nördlich von hier zu schicken. Unsere Krieger sind sehr mutig im Kampf, {name}. Ich möchte, dass Ihr Euch diesem Kampf anschließt. Geht und helft unseren Kriegern, die Grimmtotems endlich zu vertreiben.", sourceObjective = "Besiegt Orno Grimmtotem in Steinkrallenpass.", progress = "Ich habe nicht vor, nichtstuend in Donnerfels zu sitzen und zu warten, während unsere Krieger im Kampf für ihre Heimat ihr Leben riskieren, {name}. Wir werden uns auf dem Schlachtfeld treffen. Macht Euch schon auf den Weg; ich werde auch bald aufbrechen.", completion = "Willkommen zurück, {name}.\n\n\n\nWas getan wurde, war weder aus Rache, noch aus Stolz. Es war einzig und allein zum Schutz Donnerfels', zum Schutz unseres Volkes vor Qualen und Angst. Heute ist Mulgore wieder ein sicherer Ort.\n\nDie Erdenmutter dankt Euch für all Eure mutigen Taten, {name}, und auch ich danke Euch. Ihr habt für Euer heldenhaftes Verhalten eine Belohnung verdient. Ihr sollt für immer in Donnerfels willkommen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24541] = { id = 24541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parfümdiebstahl", description = "Ich wusste, dass die was im Schilde führen! Das Zeug enthält irgendeine bewusstseinsverändernde Chemikalie, doch anhand so einer kleinen Probe kann ich nicht ermitteln, was genau es ist. Ich brauch das echte Zeug.\n\nGeht aber nicht einfach rüber und kauft es. Ich will nicht, dass Ihr den Halunken auch nur ein Kupfer gebt. Nein, wir müssen es von der Quelle besorgen, diskret.\n\nIch werde Euch als Lieferbursche verkleiden. Ich hab einen Vorratshaufen gesehen, der von ihren Schlägern bewacht wurde. Geht und lauft dort vorbei, und bleibt NICHT stehen, sonst halten sie Euch auf! Sie werden Euch eine Kiste zuwerfen, bringt diese hierher.", sourceObjective = "Begebt Euch, während Ihr als Lieferbursche verkleidet seid, zum Vorratslager der Chemiemanufaktur Krone vor den Toren Orgrimmars, kehrt dann mit dem Paket, das sie Euch zuwerfen, zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Habt Ihr sie? Gut gemacht! Ganz ausgezeichnet! Mal sehen, was wir hier haben.\n\n<Er öffnet die Kiste und untersucht den Inhalt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24542] = { id = 24542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Blüte", description = "Der große Erzdruide Naralex ist vor Kurzem hier im Brachland erschienen. Entweder steckt er hinter diesem Chaos, oder er versucht, es wieder in Ordnung zu bringen. Wie auch immer - Ihr solltet mit ihm sprechen, bevor dieser Dschungel die ganze Welt einhüllt. Naralex befindet sich in einem kleinen Taurenlager im Südosten.\n\nEs wäre hilfreich, wenn Ihr unterwegs Pflanzenproben sammeln könntet, damit er sie studieren kann. Die neuesten Blumensamen werden ihm viel über die jüngsten Veränderungen im Dschungel sagen.", sourceObjective = "Sammelt zehn ungewöhnliche Blütenknospen von knospenden Blüten in der Überwucherung auf.", progress = "Ich bin sehr beschäftigt, {class}.", completion = "Ah, Proben von verschiedenen Bereichen der Überwucherung? Ja, die werden ausgesprochen hilfreich sein. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24543] = { id = 24543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gespaltene Familie", description = "Die Kinder, die Ihr hier seht, wurden alle aus Taurajo gerettet, als die Kämpfe ausbrachen. Ich versuche, ihre Eltern zu finden.\n\nEiner der Flüchtlinge, die Ihr von den Stachelebern gerettet habt, hat das stärkste Kind erkannt. Es gehört zu Kirge und Mawre Sternhorn. Außerdem sagte er, dass Kirge bei den Feldern des Blutes etwas nördlich des Ortes, an dem das Massaker von Taurajo stattfand, lagert.\n\n{name}, bitte geht dorthin und sagt Kirge Sternhorn, dass sein Kind lebt und es ihm gut geht!", sourceObjective = "Findet Kirge Sternhorn an der Vendettakuppe im Südlichen Brachland.", completion = "<Kirge hört angestrengt zu und fällt dann auf ein Knie.>\n\nAm Leben! Mein Junge lebt noch! Lobet die Erdenmutter - ich habe immer noch einen Sohn.\n\n<Kirge gewinnt seine Fassung zurück.>\n\n{class}, die Mutter meines Jungen hat es nicht lebend aus Taurajo herausgeschafft. Ich werde ihren Tod rächen, selbst wenn das bedeutet, dass mein Sohn dann vielleicht ohne seine Eltern aufwachsen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[24544] = { id = 24544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pauls Testquest" }
quests[24545] = { id = 24545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heiligen und die Verderbten", description = "Ich verwahre mich dagegen, Euch diesen Auftrag zu erteilen, {race}, da er Euch wahrscheinlich ins Verderben führt.\n\nWenn Ihr nichts auf meine Einschätzung gebt und Euch der Aufgabe stellt, werde ich Euch mit dem Wissen und den Ressourcen vertraut machen, die dazu notwendig sind.\n\nIhr müsst in die Frostgramhöhlen zurückkehren und Lichträcher, Arthas' abgelegten Hammer, finden. Neu geschmiedet aus Saronit und geschärft mit dem ätzenden Blut der Monstrositäten des Lichkönigs, wird er die Grundlage unserer Arbeit bilden.", sourceObjective = "Platziert Lichträcher, 25 Einheiten urtümliches Saronit sowie Modermienes und Fauldarms ätzendes Blut in Hochlord Mograines Runenschmiede in der Eiskronenzitadelle.\n\nModermienes ätzendes Blut und Fauldarms ätzendes Blut sind nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle erhältlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[24546] = { id = 24546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Linie im Schmutz", description = "Die Allianz brennt eine Spur der Morde quer durch das Brachland. Wir müssen sie hier aufhalten oder es wird nichts für uns übrig bleiben.\n\nAuf den Feldern des Blutes gibt es eine Anzahl strategisch wichtiger Hügel, auf denen Holztürme und neutrale graue Banner stehen. Wir müssen diese Hügel einnehmen und halten, wenn wir den Vorstoß der Allianz aufhalten wollen!\n\nHaltet Ausschau nach den Türmen im Norden, Osten und Süden von dem, was von Taurajo übrig geblieben ist. Schnappt Euch eine neutrale Flagge und verteidigt den Hügel gegen die Gegenangriffe!", sourceObjective = "Erobert einen neutralen Hügel in den Feldern des Blutes und verteidigt ihn gegen den Gegenangriff der Allianz.", completion = "Ihr habt Euch also behauptet! Mit Eurer Beharrlichkeit könnten wir es noch schaffen, die Allianz aus unseren Landen zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24547] = { id = 24547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Seelenschmaus", description = "Schattenschneide ist eine der besten Waffen, in deren Besitz <ein/eine:c> {class} kommen kann.\n\nIst Eure Machtgier nun befriedigt, {race}?\n\n<Ihr fühlt Mograines eindringlichen Blick.>\n\nDas dachte ich mir. Dann noch eine letzte Warnung...\n\nNun beginnt der tückischste Teil Eurer Aufgabe. Zügelt Euer Bestreben, denn wenn Eure Ziele nicht rein sind, werdet Ihr Euer Leben, ja, Eure Seele verlieren.\n\nDie Waffe in Euren Händen ist nichts weiter als eine leere Hülle, ein bloßer Schatten dessen, zu was sie werden kann.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr mit Schattenschneide 50 Diener des Lichkönigs in der Eiskronenzitadelle tötet. Die Seelen sind in den Schwierigkeitsgraden für 10 oder 25 Mann erhältlich.", completion = "<Hochlord Mograine blickt Euch eine Weile stumm an.>\n\nIhr scheint diesen Teil Eurer Prüfung mit Bravour bestanden zu haben, {race}.\n\nBetet, dass Euch das Glück in Euren Bestrebungen weiterhin hold bleibt...", sourceObjectiveStatus = "unverified-source-field" }
quests[24548] = { id = 24548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zersplitterte Thron", description = "Der Thron des Lichkönigs war einst sein Gefängnis. Kil'jaeden höchstselbst hat das Behältnis aus Eiskristallen aus dem Wirbelnden Nether gefertigt. Sein alleiniger Zweck war es, Ner'zhuls rachsüchtigen Geist festzuhalten.\n\nIndem er den Kristall mit Frostgram berührte, befreite Arthas Ner'zhuls Seele und ließ sie mit seiner eigenen verschmelzen. Die Splitter dieses Zusammenstoßes sind jetzt überall in der Zitadelle verteilt.\n\nIch brauche die Scherben, die wir nur von den mächtigsten Dienern des Lichkönigs bekommen können, um die in Eurer Klinge enthaltene Kraft zu versiegeln.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr 50 Schattenfrostsplitter sammelt.\n\nSchattenfrostsplitter sind nur im Schwierigkeitsgrad für 25 Mann erhältlich.", progress = "Habt Ihr die Splitter des Frostthrons besorgt, {class}?", completion = "Das sollte genügen, {class}.\n\nKommt zu mir, wenn Schattenschneide mit ihren Kräften ausgestattet wurde, und ich werde versuchen, sie zu vervollständigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24549] = { id = 24549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattengram...", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr ihm Schattenschneide bringt.", completion = "Ich gratuliere, {class}.\n\nEntgegen aller unüberwindbaren Hindernisse habt Ihr den Sturm überstanden.\n\nIch vertraue darauf, dass Ihr Eure Belohnung als angemessen empfinden werdet...", sourceObjectiveStatus = "unverified-source-field" }
quests[24550] = { id = 24550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Donnerfels", description = "Die Brunnen wurden gereinigt und die Wasser in Mulgore fließen wieder sauber und süß. Ihr habt uns gerettet... aber auch die auf die Grimmtotems zurückzuführenden Geschehnisse zu Tage gebracht. Die Taten der Grimmtotems müssen bekannt gemacht werden.\n\nDie Zeit ist für Euch gekommen, nach Donnerfels zu reisen, unserer großen Stadt auf der Anhöhe. Geht zu unserem Anführer, Baine Bluthuf, Sohn des Cairne. Er muss davon erfahren.", sourceObjective = "Sprecht mit Baine Bluthuf in Donnerfels.", completion = "Willkommen in Donnerfels, {name}. Ihr habt für unser Volk viel Gutes getan.\n\nErzählt mir von Eurer Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[24551] = { id = 24551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der neue Boss", description = "Unter Gar'duls Kommando ist die Verteidigung des Brachlandes nicht sehr erfolgreich verlaufen, {name}. Garrosh hat Kriegsfürst Blutheft hierher entsandt, um die Sache in die Hand zu nehmen. Er ist hier im Camp und wenn Ihr einen guten Eindruck hinterlassen wollt, solltet Ihr etwas Initiative zeigen.\n\nGeht nach Osten in die Felder des Blutes und findet Aufklärer der Nordwacht. Wenn Ihr dem neuen Kriegshäuptling einen Stapel ihrer Verdienstabzeichen bringt, werdet Ihr Euch sicherlich einen Namen machen!", sourceObjective = "Tötet Aufklärer der Nordwacht und nehmt ihnen 10 Verdienstabzeichen von Theramore ab.", progress = "Ihr seht wie ein {race} aus, der sich durchsetzen kann. Welche Neuigkeiten bringt Ihr aus den Feldern?", completion = "<Blutheft schaut sich die Abzeichen an und lässt sie dann aus seinen Händen auf den Sandboden fallen. Seine Lippen verziehen sich zu einem breiten Grinsen.>\n\nDAS sehe ich doch gerne, {class}! Wie heißt Ihr noch gleich?\n\nIhr werdet es hier weit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24552] = { id = 24552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz des Löwen", description = "Wenn Ihr Rache an den Eindringlingen der Allianz nehmen wollt, seid Ihr gut beraten, die gefährlichsten Raubtiere im Brachland zu beobachten.\n\nDie Löwen, die sich durch das hohe Gras schleichen, sind gerissen, gut getarnt und mächtig. Nehmt Euch an ihnen ein Beispiel und Ihr werdet verstehen, welche Art Krieg wir führen müssen.\n\nJagt die Ebenenstreuner und -stolzmähnen. Dann kehrt zu mir zurück und wir unterhalten uns darüber, was Ihr gelernt habt. Ihr werdet sie oft im Schatten großer Bäume antreffen.", sourceObjective = "Tötet insgesamt 5 Ebenenstreuner oder Ebenenstolzmähnen.", completion = "Ah ja... Ich sehe eine Gerissenheit in Euren Augen, die dort vorher nicht zu finden war. Gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24553] = { id = 24553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt, und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Die Klinge wird sich an Euch binden. Wenn das passiert, tragt sie zu Caladis Prunkspeer in Qel'Delars Ruh.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", progress = "Was ist Euch beim Sonnenbrunnen widerfahren?", completion = "Das ist unglaublich, {name}! Ihr habt es tatsächlich geschafft! Alle Quel'dorei kennen die Geschichte von Thalorien Morgensucher und Quel'Delar, aber keiner hätte je geglaubt, dass das Schwert wiederhergestellt werden würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[24554] = { id = 24554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ramponierte Schwertgriff", description = "Dieser ramponierte alte Schwertgriff hat schon bessere Tage gesehen. Bevor er von der Klinge gebrochen wurde, muss es sich dabei um ein wunderschönes Beispiel der Schmiedekunst gehandelt haben.\n\nDie eleganten Symbole und exotischen Edelsteine, die den Griff schmücken, lassen darauf schließen, dass die Waffe womöglich einer mächtigen Person gehörte. Die Sonnenhäscher wären sicherlich am Fund eines solchen Artefakts interessiert. Sucht ihren Repräsentanten in Quel'Delars Ruh südlich des Argentumturnierplatzes auf.", sourceObjective = "Bringt den ramponierten Schwertgriff zu Myralion Sonnenfeuer in Quel'Delars Ruh südlich des Argentumturnierplatzes.", progress = "Was habt Ihr entdeckt?", completion = "<Myralion nimmt den Schwertgriff an sich und inspiziert das Artefakt.>\n\nDas habt Ihr aus der Zitadelle? Was hat es dort gemacht? Diese Klinge ist gewiss kein Erzeugnis der Geißel.\n\nWaffen dieser Qualität können nur von einigen wenigen Geschöpfen Azeroths hergestellt werden. Wir müssen mit ihnen in Verbindung treten und sehen, ob sie uns bei der Identifizierung der Waffe behilflich sein können.", sourceObjectiveStatus = "unverified-source-field" }
quests[24555] = { id = 24555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Drachen", description = "Dieser Schwertgriff stammt ganz eindeutig von einer sehr alten, sehr mächtigen Waffe. Nur von welcher? Diese Muster sind mir unbekannt, doch wir haben unsere Möglichkeiten noch nicht ausgeschöpft.\n\nKorialstrasz, besser bekannt als Krasus, ist schon lange Zeit mit den Quel'dorei und den Kirin Tor befreundet. Mit seinem umfangreichen Wissen und seinen Beziehungen kann er uns sicher weiterhelfen. Reist zur höchsten Ebene des Wyrmruhtempels und bittet ihn um Rat, meldet Euch dann bei Magister Hathorel in Sonnenhäschers Zuflucht in Dalaran.", sourceObjective = "Sprecht mit Krasus in der Spitze des Wyrmruhtempels.", completion = "Wir müssen uns das Buch vom Silberbund wiederbeschaffen. Ohne das Buch von Krasus haben wir kaum eine Chance, das Rätsel um das Schwert in Eiskrone zu lösen oder seine Macht freizusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24556] = { id = 24556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Verkleidung", description = "Euch ins Innere der Silbernen Enklave zu bringen, wird schwieriger sein, als es erscheint. Nur diejenigen, die über einen Wappenrock des Silberbunds verfügen, wird Zugang zur Zuflucht gewährt. Sollten wir an einen herankommen können, wird eine einfache Verzauberung den Rest erledigen.\n\nAuf dem Balkon über den Fäden des Schicksals werdet Ihr Shandy Lackglanz finden. Ich habe ihm in der Vergangenheit ein paar Mal geholfen - er schuldet mir also noch einen Gefallen. Er kümmert sich um die Wäsche etlicher Leute jeden Schlags aus der Stadt. Vielleicht kann er einen Weg finden, Euch einen Wappenrock eine Weile lang \"auszuleihen\".", sourceObjective = "Besorgt Euch von Shandy Lackglanz einen geliehenen Wappenrock.", progress = "Konnte Shandy Euch helfen, an einen Wappenrock des Silberbunds heranzukommen?", completion = "Ich wusste, dass Shandy einen Weg finden würde. Lasst mich ihn verzaubern, damit Ihr ihn verwenden könnt. Mit etwas Glück wird der Besitzer des Wappenrocks nicht einmal bemerken, dass er verschwunden ist, und Shandy wird unsere Spuren beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24557] = { id = 24557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan des Silberbunds", description = "Einer meiner Kontakte unten in den Kanälen der Schattenseite hat in der Taverne \"Zur Zauberkrähe\" einen Agenten des Silberbunds erblickt. Die Mitglieder des Silberbunds sind normalerweise nicht dafür bekannt, ein Interesse am dortigen Treiben zu hegen, was also sehr stark darauf hindeutet, dass sie etwas vorhaben.\n\nBegebt Euch zur Schattenseite, spürt diesen Agenten auf und schaltet ihn aus. Durchsucht ihn nach allen Informationen, die uns einen Hinweis über den Verbleib dieses Folianten vom Wyrmruhtempel liefern könnten. Wir können nicht zulassen, dass ihn diese albernen Schwächlinge vom Silberbund zuerst zurück nach Eiskrone bringen.", sourceObjective = "Besorgt die Befehle des Silberbunds.", progress = "Konntet Ihr irgendetwas Brauchbares bei diesem Agenten finden?", completion = "<Magister Hathorel liest die erbeuteten Befehle.>\n\nDer Agent, den Ihr abgefangen habt, sollte in der Silbernen Enklave jemanden namens Arkanist Tybalin treffen und dann den Folianten vom Wyrmruhtempel nach Eiskrone bringen. Wir müssen das Buch zurückbekommen, {name}, und es gibt nur eine Möglichkeit, solange es sich noch in der Stadt befindet. Jetzt ist schnelles Handeln gefragt!", sourceObjectiveStatus = "unverified-source-field" }
quests[24558] = { id = 24558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Myralion Sonnenfeuer", description = "Wir müssen dieses Buch zu Myralion Sonnenfeuer bringen. Würdet Ihr das übernehmen? Ich kann diese Aufgabe sonst niemandem anvertrauen, und Ihr habt Geschick darin bewiesen, die Leute vom Silberbund zu meiden.\n\nBringt es nach Quel'Delars Ruh südlich des Argentumturnierplatzes in Eiskrone. Myralion wird Euch dort erwarten. Wenn er die Klinge identifizieren kann, können wir sie im Namen Aethas Sonnenhäschers beanspruchen und Dalaran und der Allianz zeigen, dass wir den Angriff auf den Lichkönig anführen werden.", sourceObjective = "Bringt den Folianten \"Uralte drachengeschmiedete Klingen\" zu Myralion Sonnenfeuer in Quel'Delars Ruh.", progress = "Wir hatten Eure Rückkehr schon erwartet. Was hat Euch aufgehalten?", completion = "<Myralion nimmt das schwere Buch zur Hand und beginnt, darin zu blättern.>\n\nDie Symbole auf der Klinge kamen mir bekannt vor und jetzt weiß ich auch, warum. Das ist zweifellos eine Drachenklinge, die einem der sterblichen Völker zum Geschenk gemacht wurde. Nur um welche Klinge handelt es sich und wie ist sie nach Eiskrone gelangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[24559] = { id = 24559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert neu schmieden", description = "Wir dürfen nicht zulassen, dass Quel'Delar in zerbrochenem und entehrtem Zustand bleibt. Nehmt die Überreste des Schwertes sowie den von Euch gefundenen ramponierten Schwertgriff und begebt Euch in die Grube von Saron in der Eiskronenzitadelle.\n\nIn der Grube lässt der Lichkönig Sklaven Saroniterz fördern sowie be- und verarbeiten. Dieses energieerfüllte Saronit brauchen wir, um Quel'Delar wiederherzustellen.\n\nIhr müsst energieerfüllte Saronitbarren sammeln und den Hammer des Schmiedemeisters erbeuten, Euch mit beidem zum Amboss des Schmiedemeisters begeben und das Schwert neu schmieden.", sourceObjective = "Besorgt 5 energieerfüllte Saronitbarren sowie den Hammer des Schmiedemeisters und verbindet sie mit den Überresten Quel'Delars, um das Schwert wiederherzustellen.", progress = "Konntet Ihr Quel'Delar wiederherstellen?", completion = "Ihr habt die Klinge Quel'Delars wiederhergestellt, der Behauptung Blutkönigin Lana'thels zum Trotz! Jetzt muss die Klinge nur noch getempert werden, bevor wir ihr beweisen können, wie töricht ihre Worte doch waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24560] = { id = 24560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge tempern", description = "Endlich wurden die Bruchstücke von Quel'Delar wieder vereint und die Klinge ist ganz - doch sie muss zuerst getempert werden, bevor Ihr sie einsetzen könnt. Die gezackte Saronitschneide ist spröde und würde beim ersten Kontakt zerbrechen.\n\nIn den Tiefen der Seelenschmiede in der Eiskronenzitadelle gibt es einen Ort, an dem sie sicher getempert werden kann. Nehmt Quel'Delar mit Euch zum Domizil des Verschlingers der Seelen und sucht nach dem Schmelztiegel. Taucht die Klinge dort hinein und bringt sie zurück zu mir in die Gefrorenen Hallen.", sourceObjective = "Tempert das neugeschmiedete Quel'Delar im Schmelztiegel der Seelen.", progress = "Solange das Schwert nicht getempert ist, ist es nutzlos.", completion = "Das Tempern des Schwertes sollte die Klinge wiederhergestellt haben. Warum hat es nicht funktioniert?", sourceObjectiveStatus = "unverified-source-field" }
quests[24561] = { id = 24561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen der Reflexion", description = "Ihr habt das Schwert zwar neu geschmiedet und getempert, dennoch ruht es in seiner Scheide und zeigt nichts von der Macht, die es besitzen soll. Ihr sagt, dass es Euch zieht, als hätte es einen eigenen Willen?\n\nWagt Ihr es, das Schwert an den von ihm gewünschten Ort zu bringen? Es ist nicht richtig, dass es so ruhig und doch so hartnäckig ist, und ich fürchte, wir werden nie erfahren weshalb, solltet Ihr es nicht an seinen Zielort bringen. Bringt es in die Hallen der Reflexion in der Eiskronenzitadelle. Seid jedoch auf der Hut! Ich warte in den Gefrorenen Hallen auf Euch.", sourceObjective = "Bringt Quel'Delar nach Schwertruh in den Hallen der Reflexion.", progress = "Was ist in den Hallen der Reflexion geschehen?", completion = "Wie kann sich das Böse in solch einem Schwert einnisten? Ich hätte das nicht für möglich gehalten, wenn sich der Beweis nicht direkt vor meinen Augen befände. Wenn die größte Schöpfung der Drachen verdorben und gegen sie gerichtet werden kann, weshalb sollte da ein Schwert die Ausnahme bilden?\n\nIch glaube, Uther hat Recht. Ihr müsst seinem Rat schnell folgen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24562] = { id = 24562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Sonnenbrunnen", description = "Bringt Quel'Delar so schnell wie möglich zum Sonnenbrunnen, {name}! Glaubt Uthers Worten, dass Ihr die Kontrolle über die Klinge nicht immer behalten könnt, wenn sie dem bösen Einfluss des Lichkönigs ausgesetzt ist. Ihr müsst zur Insel von Quel'Danas reisen und versuchen, zum Sonnenbrunnen zu gelangen, um das Schwert zu läutern.\n\nDie Wächter des Sonnenbrunnens werden Euch nicht so einfach Zutritt gewähren. Daher müsst Ihr Euch an Halduron Wolkenglanz wenden, der ein Auge auf die Wachen dort hat.", sourceObjective = "Sprecht mit Halduron Wolkenglanz am Eingang des Sonnenbrunnenplateaus auf der Insel von Quel'Danas.", progress = "Was führt Euch hierher?", completion = "Ich hoffe, Ihr habt Verständnis dafür, dass ich Euch nicht einfach so Zutritt zum Sonnenbrunnen gewähren kann, {name}. Dies ist der heiligste den Sin'dorei bekannte Ort, und wir haben erst kürzlich Kontrolle über ihn zurückerlangt.\n\nIhr wollt unserem Volk mit Märchen über Quel'Delar Hoffnungen machen? Ohne Beweis für die Wahrhaftigkeit Eurer Behauptungen sehe ich keine Veranlassung, Euch Glauben zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24563] = { id = 24563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Morgensucher", description = "Ihr arbeitet mit Myralion Sonnenfeuer zusammen, nicht wahr? Ich weiß, wie wir das Schwert testen können.\n\nWenn Ihr die Geschichte der Klinge kennt, erinnert Ihr Euch vielleicht, dass Thalorien Morgensucher sie bei der Verteidigung des Sonnenbrunnens gegen die Geißel führte. Er fiel dort, wo sich heute die Todesschneise befindet, und verschaffte so seinen Leuten Zeit, eigene Vorbereitungen zu treffen. Seine sterblichen Überreste befinden sich am südlichen Ende der Todesschneise auf dieser Insel. Begebt Euch dorthin, damit sein Geist Euch den Segen erteilt, zum Sonnenbrunnen zu gehen.", sourceObjective = "Besucht die sterblichen Überreste Thalorien Morgensuchers und erhaltet seinen Segen für den Gebrauch Quel'Delars.", completion = "Ihr tragt wirklich Quel'Delar bei Euch. Heute ist ein großer Tag für ganz Quel'Thalas und die Sin'dorei! Ihr habt meine Erlaubnis, zum Sonnenbrunnen zu gehen und die Wiederherstellung des Schwertes abzuschließen. Lasst den Kopf nicht hängen, {name}. Die Söhne und Töchter Silbermonds haben viele Jahre auf diesen Tag gewartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24564] = { id = 24564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", progress = "Was ist beim Sonnenbrunnen geschehen?", completion = "Sind meine Augen tatsächlich auf die Waffe Thalorien Morgensuchers gerichtet? Heute ist ein großer Tag für alle Sonnenhäscher und alle Sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24565] = { id = 24565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biologischer Eingriff", description = "Die Energien, die hier freigesetzt wurden, sind durch die Wildtiere geflossen. Dadurch wurden sie mächtig und instabil. Wenn wir zulassen, dass sie sich über diesen Hain hinaus ausbreiten, werden diese Mutationen eine katastrophale Auswirkung auf das Ökosystem haben, die Beutetiere verschlingen und die schwächeren, natürlichen Kreaturen vertreiben.\n\nIhr müsst gehen und bei dem Bestand der Überwucherung eine Auslese treffen. Kehrt zurück, wenn diese Aufgabe erfüllt ist.", sourceObjective = "Tötet 5 Deviatschreckenszähne und 5 Deviatebenenschreiter.", completion = "Danke, {name}. Ich bin froh, dass Ihr unverletzt zurückgekehrt seid; die Bösartigkeit dieser Kreaturen ist wirklich erschreckend.", sourceObjectiveStatus = "unverified-source-field" }
quests[24566] = { id = 24566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aussaat einer Lösung", description = "Aufgrund dessen, was Ihr mir überbracht habt, denke ich, dass wir vielleicht eine Lösung haben. Ich hab die Peitschenrankensamen mit heilenden Energien erfüllt.\n\nEinfacher Kontakt mit ihnen sollte den Kreaturen hier genug Energie verleihen, um den verderbnisreichen Einfluss abzuschütteln.\n\nGeht und versucht, die mutierten Raptoren und Ebenenschreiter zu heilen, indem Ihr die Samen über sie streut. Dann berichtet mir von dem Ergebnis.", sourceObjective = "Benutzt die beruhigenden Samen bei 6 Deviatschreckenszähnen oder Deviatebenenschreitern und beobachtet die Ergebnisse.", completion = "Oh weh! Anscheinend sind die Kräfte, die hier am Werk sind, schwer unter Kontrolle zu bringen...\n\nBitte behelligt Naralex nicht damit. Es wird ihn nur aufregen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24567] = { id = 24567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch für ein Testspiel", description = "{name}, Trainer Blutgrätsch, der Kopf unserer furchtlosen Bilgewasserbukaniere, sucht Euch.\n\nEr sagt, dass der Ligatitel gegen die Dampfdruckhaie in Gefahr ist und dass nur Ihr den Pokal nach Hause holen könnt!\n\nGeht nach Westen in die Stadt. Ihr könnt das Kajarofeld nicht verfehlen.\n\nEin Fußbombenstar. Das wird sich hervorragend auf Euer Image auswirken!", sourceObjective = "Sprecht mit Trainer Blutgrätsch auf dem Kajarofeld auf Kezan.", completion = "Da seid Ihr ja, mein Junge! Schnell, wir haben keine Zeit zu verlieren! Wir müssen diese Schredder wieder funktionstüchtig machen.\n\nIch hole Euch von der Ersatzbank… Ihr werdet das Spiel und den Titel für uns gewinnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24568] = { id = 24568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Mauern!", description = "{name}, sie versammeln sich an den Toren! Die Allianz versucht, nach Mulgore hineinzudrängen. Ihre Fußsoldaten versuchen, die Wachen zu überwältigen.\n\nWir haben so wenig, womit wir die Mauern verteidigen können. Wir haben kochendes Wasser in Töpfen, um die Angreifer in Schach zu halten, bis Hilfe eintrifft... Das muss reichen.\n\nAber wir brauchen jemand, der unsere Verteidigung organisiert. Ihr müsst nur ein Wort sagen und ich werde Euch zu einer Übersicht aus der Vogelperspektive über das Schlachtfeld verhelfen.\n\nWir brauchen Euch, {name}!", sourceObjective = "Sprecht mit Winnoa Kiefernwald an den Feldern des Blutes, um die Tore von Mulgore gegen den Angriff zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24569] = { id = 24569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsbrecher", description = "{name}, Ihr habt Euch auf den Feldern des Blutes als würdig erwiesen. Aber die Allianz bedroht immer noch unsere Taurenfreunde.\n\nDie Belagerungsmaschinen außerhalb der Tore von Mulgore sind wie Speere, die direkt auf unsere Herzen zielen. Ich möchte, dass Ihr zu den Toren südlich von uns geht und diese Belagerungsfahrzeuge aus dem Spiel nehmt.\n\nHier, benutzt die Haftbomben. Wir haben sie freundlicherweise von unseren neuen Goblinverbündeten bekommen. Sieht so aus, als ob sie Schwarzpulver in... es sieht aus wie... ölverschmierte Socken gestopft haben. Aber die werden schon reichen.", sourceObjective = "Zerstört 4 Belagerungsmaschinen der Nordwacht vor den Toren von Mulgore.", progress = "Warum hat Gar'dul zugelassen, dass die Allianz so viele schwere Belagerungsmaschinen aufstellt? Warum wurde kein Gegenschlag angeordnet, bevor ich hier eintraf? Gar'dul wird sich dafür noch rechtfertigen müssen...", completion = "Sehr gut! Jetzt werden sie wohl mit Infanterie auf die Tore losstürmen müssen.\n\nGlaubt Ihr, sie haben den Mumm dazu?", sourceObjectiveStatus = "unverified-source-field" }
quests[24570] = { id = 24570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenabzug", description = "Die Verderbnis, die hier entfesselt wurde, muss eingehend erforscht werden, wenn wir einen wirksamen Weg finden wollen, sie zu bekämpfen.\n\nZum Glück haben sich hier nicht alle Kreaturen gleichermaßen verändert. Die kleineren Schlangen trinken wenig Wasser und fressen keine Pflanzen, also sind sie den Energien nur in geringem Maße ausgesetzt worden. Dennoch haben sie genug aufgenommen, um ihre Farbe zu verändern.\n\nGeht, sammelt einige dieser Schlangen aus der Überwucherung und bringt sie zu mir, damit wir sehen können, was genau mit den Kreaturen hier geschieht.", sourceObjective = "Besorge 5 entkräftete Ottern.", progress = "Habt Ihr genügend eingesammelt? Wir benötigen einige, um aussagekräftige Vergleiche anstellen zu können.", completion = "Die sind genau richtig. Bunte Farben wie diese entstehen im Brachland nicht auf natürliche Weise, aber bisher haben sich bei ihnen noch keine weiteren Mutationen herausgebildet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24571] = { id = 24571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peitschenrankensamen", description = "Es muss einen Weg geben, diese armen Kreaturen zu heilen, ohne ihnen das Leben zu nehmen. Ich habe eine Idee, aber ich brauche Eure Hilfe, {class}.\n\nDie Pflanzen der Peitschenranke, die hier umherstreifen, enthalten Samen prallvoll mit der urtümlichen Energie dieses Ortes. Sammelt sie für mich ein und bringt sie hierher, dann sehen wir, was man tun kann.", sourceObjective = "Besorgt 4 zuckende Samen von Peitschenranken.", progress = "Habt Ihr die Samen?", completion = "Es beunruhigt mich, wie... aktiv sie sind. Dennoch bedeutet das nichts anderes, als dass wir schnell handeln müssen, bevor die Verderbnis hier noch schlimmer wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[24572] = { id = 24572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taurajo zurückerobern", description = "Ausgezeichnete Arbeit dort an den Toren, {name}! Der größte Teil der Streitkräfte der Allianz befindet sich auf dem Rückzug. Aber das genügt mir nicht.\n\nSie haben Taurajo geplündert, das nur ein einfaches Lager der Jäger war. Die \"Allianz\" wurde demaskiert und man weiß jetzt, was sie wirklich ist: Eine Bande abtrünniger Schlächter.\n\nSogar jetzt lungert eine Gruppe Menschen dort herum und wühlt in den Knochen des noch schwelenden Taurajo herum.\n\n<Blutheft schleudert eine Axt in den Staub.>\n\nSie sollen leiden.", sourceObjective = "Tötet 8 Plünderer von Taurajo in den Überresten von Camp Taurajo.", completion = "Ausgezeichnet. Ich werde ihre Leichen entlang der Goldstraße als Botschaft für die Allianz aufhängen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24573] = { id = 24573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Toten ehren", description = "Jetzt, da die unmittelbare Bedrohung vorüber ist, könntet Ihr bei einer traurigen Aufgabe helfen?\n\nWir Tauren beerdigen unsere Toten nicht, wir bereiten ihre Körper auf die Rückkehr zu den Elementen vor und bringen sie zu unseren heiligen Grabstätten. Diejenigen, die während des Taurajomassakers getötet wurden, wurden nicht bestattet und ich fürchte, dass fehlgeleitete Soldaten der Allianz die Körper der Toten verbrennen, bevor die richtigen Rituale durchgeführt wurden.\n\n{name}, bitte bringt dieses Totem nach Taurajo und führt die Bestattungszeremonie für Krulmoo, Dranh, Yonada und Omusa durch. Sie... haben es dort nicht herausgeschafft.", sourceObjective = "Benutzt das Bestattungstotem an den Leichnamen von Krulmoo, Dranh, Yonada und Omusa in den Überresten von Camp Taurajo.", progress = "Haben ihre Geister ihren Frieden mit der Erdenmutter gemacht?", completion = "<Winnoa neigt ihren Kopf.>\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24574] = { id = 24574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...wird Chaos ernten", description = "Wenn ich wirklich Chaos gesät habe, wird es Zeit für mich, die Ernte einzubringen.\n\nDie schwerfälligen Auswüchse der Pflanzenwelt schlurfen durch den magieerfüllten Strom hier, {name}. Sie sind eine Manifestation der instabilen Kräfte, die diese Gegend verändern. Tötet so viele Ihr könnt und vielleicht können wir die weitere Verbreitung der Überwucherung verlangsamen.\n\nUnd wenn Ihr schon dabei seid... ich suche nach Teilen von ihnen, die besonders befallen erscheinen. Bringt solche Teile zu mir.", sourceObjective = "Tötet 5 Auswüchse und findet ein sich windendes Herz.", progress = "Die Auswüchse zu beschneiden, wird uns höchstens etwas Zeit verschaffen. Habt Ihr irgendwelche verdächtigen Teile gefunden?", completion = "<Naralex nimmt langsam das sich windende Herz aus Euren Händen und ist sichtlich verstört.>\n\nIch war ein Narr. Die eine Wahrheit, die ich nicht akzeptieren wollte, hat mir die ganze Zeit ins Gesicht gestarrt...dieses widerwärtige Ding ist der Beweis dafür.\n\nWir beide haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[24575] = { id = 24575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung", description = "Wir haben kürzlich herausgefunden, dass die Dorfbewohner in Glutstein die schlimmsten Verheerungen des Fluchs überlebt haben.\n\nLeider hatte ihr Dorf beim Einmarsch der Verlassenen nicht so viel Glück.\n\nDie Verlassenen haben die Dorfbewohner gefangen genommen und zwingen sie, in der nahegelegenen Mine als Sklaven zu arbeiten.", sourceObjective = "Befreit 5 versklavte Dorfbewohner in der Glutsteinmine.", completion = "Ihr habt es wieder geschafft, {name}. Die befreiten Dorfbewohner wollen uns mit allen Kräften im Kampf gegen die Verlassenen unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24576] = { id = 24576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine nette Unterhaltung...", description = "<Roka hört widerwillig zu, als Ihr ihr erzählt, warum Ihr versucht, Flenni aufzuspüren.>\n\nIhr meint also, ich hätte die ganze Zeit unter dem Einfluss eines Alchemisten gestanden? Ich kann nicht glauben, dass ich auf diesen Schwindel hereingefallen bin! Wenn ich diesen hinterhältigen Goblin jemals in die Finger kriege, reiß ich ihn in Stücke!\n\nFalls er mit seinen Erledigungen fertig ist, befindet er sich auf dem Weg zum Zeppelinturm inmitten Orgrimmars! Was auch immer Ihr tut, {name}, Ihr dürft ihn nicht an Bord des Zeppelins und davonkommen lassen!\n\nBeeilt Euch, geht zum Zeppelinturm, bevor Ihr ihn verpasst!", sourceObjective = "Begebt Euch zum Zeppelinturm auf dem zentralen Hügel in Orgrimmar und befragt Flenni Rostrakete zu den Vorräten. Kehrt mit den erhaltenen Informationen zurück.", progress = "Habt Ihr den Kerl gefunden oder hat er sich irgendwo verkrochen?", completion = "Habt Ihr sein Geschäftsbuch bekommen? Wirklich? Das ist wunderbar, {name}! Darin befinden sich bestimmt eine Menge nützlicher Informationen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24577] = { id = 24577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überprüfung der Ödnisfeste", description = "Euch haben wir es zu verdanken, dass die unmittelbare Bedrohung vorüber ist. Aber meine Arbeit hier im Brachland ist nur der Anfang.\n\nEhrenwacht wurde erobert und Taurajo geplündert, während Kriegsherr Gar'dul noch das Sagen in der Region hatte. Der Kriegshäuptling hat mich geschickt, um das Chaos hier zu beseitigen.\n\nIch möchte, dass Ihr als meine Vorhut zur Ödnisfeste im Süden reitet und Gar'dul wissen lasst, dass es Zeit für eine Abrechnung ist.\n\nSprecht mich an, wenn Ihr bereit seid, aufzubrechen und ich werde meinen Vortrupp zusammentrommeln, damit er Euch begleitet.", sourceObjective = "Sprecht mit Kriegsfürst Blutheft, dann reitet zur Ödnisfeste und informiert Gar'dul, dass Kriegsfürst Blutheft unterwegs zu ihm ist.", completion = "<Gar'dul bricht der Schweiß aus.>\n\nHört mal, äh, lasst uns das nicht hier vor all den Leuten besprechen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24578] = { id = 24578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarzforst", description = "Es hat ein wenig gedauert, aber ich glaube, ich habe endlich herausgefunden, was hier passiert ist. Zumindest teilweise.\n\nIn dieser Stadt gab es einige Überlebende der Seuche. Sie haben sich alle den anderen in den Bergen angeschlossen, an der Witterfront.\n\nAlle sind geflohen, bis auf den Mann, der dieses Tagebuch geführt hat, der alte Bradshaw. Er bemerkte, dass die Angriffe der Worgen plötzlich aufgehört hatten, und entschloss sich, in den Schwarzforst zu reisen.\n\nDirekt nordöstlich der Stadt gibt es eine verlassene Mühle. Dort lebte Bradshaw früher. Schaut Euch da nach Hinweisen um.", sourceObjective = "Untersucht die Bradshawmühle direkt außerhalb von Sturmsiel.", completion = "Ich habe Euch erwartet, {name}. Habt keine Angst.\n\nMein Name ist Belysra. Ich bin eine Priesterin des Mondes... eine Nachtelfe.\n\nIhr kennt Meinesgleichen vielleicht nicht, aber seit der Fluch Euch befiel, sind die Schicksale unserer Völker miteinander verbunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24579] = { id = 24579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sartharion muss sterben!", description = "Sartharion, der Onyxwächter, hütet die Eier des Zwielichtdrachenschwarms. Er hält sich im Obsidiansanktum in der Kammer der Aspekte unterhalb des Wyrmruhtempels auf.\n\nDer Rat der Sechs hat verfügt, dass Sartharion sterben muss!", sourceObjective = "Tötet Sartharion.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Jetzt, wo Sartharion tot ist, werden Todesschwinges und Sinestras Pläne bestimmt ins Stocken geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24580] = { id = 24580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anub'Rekhan muss sterben!", description = "Anub'Rekhan, einst mächtiger Spinnenfürst im Nerubischen Reich, ist in die Fänge des Lichkönigs geraten, der ihn zu einem Untoten machte.\n\nJetzt fristet er sein Dasein als Gruftlord in seinem Domizil im Arachnidenviertel von Naxxramas und ersinnt Strategien für Kel'Thuzad.\n\nDer Rat der Sechs hat verfügt, dass Anub'Rekhan sterben muss!", sourceObjective = "Tötet Anub'Rhekan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24581] = { id = 24581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth der Seuchenfürst muss sterben!", description = "Noth der Seuchenfürst, Verräter und Feigling! In der Anzahl gegeißelter Seelen folgt er gleich hinter dem Lichkönig selbst.\n\nBegebt Euch schleunigst nach Naxxramas. Dort hält er sich im Seuchenviertel hinter seiner untoten Dienerschaft versteckt.\n\nVernichtet ihn! Der Rat der Sechs hat verfügt, dass Noth sterben muss!", sourceObjective = "Tötet Noth den Seuchenfürst.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Eine Sorge weniger... Jetzt, wo Noth tot ist, wird auch die Forschung der Geißel nach verbesserten Methoden zur Erschaffung Untoter ein Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24582] = { id = 24582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrukteur Razuvious muss sterben!", description = "Instrukteur Razuvious stolziert selbstgefällig durch das Militärviertel von Naxxramas. Man sagt, nur ein von ihm persönlich ausgebildeter Todesritter könne der Macht seiner Klinge standhalten.\n\nIhr und Eure Gruppe sollt das Gegenteil beweisen.\n\nDer Rat der Sechs hat verfügt, dass Razuvious sterben muss!", sourceObjective = "Tötet Instrukteur Razuvious.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Gut gemacht, {class}! Razuvious' Untergang hatte eine Verwirrung des Militärbefehls der Geißel aus Naxxramas zur Folge.", sourceObjectiveStatus = "unverified-source-field" }
quests[24583] = { id = 24583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickwerk muss sterben!", description = "Der sogenannte \"Abgesandte des Krieges\", Flickwerk, ist die ultimative Monstrosität. Außerdem setzt er unseren Truppen in der Drachenöde schwer zu.\n\nIch möchte, dass Ihr Eure Gefährten versammelt und Euch in das Konstruktviertel von Naxxramas begebt, wo Ihr dieses Konstrukt auseinandernehmen sollt.\n\nDer Rat der Sechs hat verfügt, dass Flickwerk sterben muss!", sourceObjective = "Tötet Flickwerk.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Kinder überall auf der Welt werden besser schlafen können, jetzt, da Flickwerk nicht mehr lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24584] = { id = 24584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malygos muss sterben!", description = "Unsere Ressourcen sind erschöpft. Malygos, der Spruchwirker, entzieht der Welt ihre Magie, um sie im Auge der Ewigkeit zu sammeln. Ohne Magie sind wir verloren!\n\n{class}, der Nexuskrieg muss beendet werden. Der Rat der Sechs hat verfügt, dass Malygos sterben muss!", sourceObjective = "Tötet Malygos.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Nach dem Sieg über Malygos sollte der Nexuskrieg bald beendet sein. Die Dankbarkeit der Kirin Tor ist Euch gewiss, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24585] = { id = 24585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flammenleviathan muss sterben!", description = "Auf dem Gestaltungsgelände bildet der Flammenleviathan die erste Verteidigungslinie von Ulduar.\n\nDie Kirin Tor haben die Information erhalten, dass diese vom Bewahrer hergestellte Maschine schon bald an einen unbekannten Ort gebracht und auf die Sterblichen von Azeroth losgelassen werden soll, um Verwüstung über sie zu bringen.\n\nDas dürfen wir nicht zulassen. Der Rat der Sechs hat verfügt, dass der Flammenleviathan sterben muss!", sourceObjective = "Tötet den Flammenleviathan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Ich bin doch immer wieder erstaunt, welche Schrecken man mit dem Gebrauch von Technik erschaffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[24586] = { id = 24586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenschuppe muss sterben!", description = "Klingenschuppe bleibt für gewöhnlich in ihrem Horst unweit der Kolossalen Schmiede in Ulduar. Doch in letzter Zeit wurde sie gesehen, wie sie Feuer auf das Land außerhalb des Titankomplexes niederregnen ließ.\n\nZwar hat die Brutmutter eine traurige Vergangenheit, doch stellt sie eine unmittelbare Gefahr für ganz Nordend dar. Der Rat der Sechs hat verfügt, dass Klingenschuppe sterben muss!", sourceObjective = "Tötet Klingenschuppe.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24587] = { id = 24587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignis, Meister des Eisenwerks, muss sterben!", description = "Der große Feuerriese Ignis, Meister des Eisenwerks, schuftet unermüdlich in der Kolossalen Schmiede von Ulduar. Auf Geheiß von Loken stellt Ignis Waffen von schrecklicher Macht her.\n\nDer Rat der Sechs hat verfügt, dass Ignis sterben muss!", sourceObjective = "Tötet Ignis, Meister des Eisenwerks.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Ich gehe davon aus, dass Ihr nicht mit allzu vielen seiner Eisenkonstrukte konfrontiert wart?", sourceObjectiveStatus = "unverified-source-field" }
quests[24588] = { id = 24588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "XT-002 Dekonstruktor muss sterben!", description = "Der XT-002 Dekonstruktor, ein weiteres, seltsames Konstrukt von Mimiron, denkt doch tatsächlich, er wäre der Sohn des Bewahrers! Lasst Euch von seiner geheuchelten Unschuld nicht in die Irre führen, er ist eine todbringende Maschine!\n\nIhr findet den Dekonstruktor auf dem Schrottplatz von Ulduar. Der Rat der Sechs hat verfügt, dass der XT-002 Dekonstruktor sterben muss!", sourceObjective = "Tötet den XT-002 Dekonstruktor.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Die größte Schwäche Ulduars ist das blinde Vertrauen ihrer Meister auf die Erfindungen, die sie zum Schutze dort ließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24589] = { id = 24589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Jaraxxus muss sterben!", description = "Erzmagier Timear hat eine schreckliche Begebenheit vorhergesagt, die sich in Kürze ereignen wird. Ein törichter Gnomenhexenmeister wird während der Prüfung des Kreuzfahrers versehentlich einen Eredarlord der Brennenden Legion heraufbeschwören.\n\nIhr müsst dort sein, wenn es passiert, {class}. Wenn Lord Jaraxxus entkommt, wird er ein Portal öffnen, durch das die Brennende Legion wieder Einzug in unsere Welt erhält.\n\nDer Rat der Sechs hat verfügt, dass Lord Jaraxxus sterben muss!", sourceObjective = "Tötet Lord Jaraxxus.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Ganz Azeroth hatte Glück, dass Timear die Ankunft des Eredarlords vorhergesehen hat und Ihr rechtzeitig dort wart, um ihn zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24590] = { id = 24590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Mark'gar muss sterben!", description = "Lord Mark'gar bewacht den Frostthron in der Bastionskammer. Seit der Lichkönig ihn aus den Knochen Tausender bezwungener Abenteurer zusammengesetzt hat, besitzt Mark'gar selbst die Macht des Thrones.\n\nWenn dieses Knochengespenst nicht vernichtet wird, besteht keine Hoffnung, die Eiskronenzitadelle einzunehmen.\n\nDer Rat der Sechs hat verfügt, dass Lord Mark'gar sterben muss!", sourceObjective = "Tötet Lord Mark'gar.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Dank Euch hat der Frostthron keinen Hauptwächter mehr. Unsere Angriffe auf die Truppen des Lichkönigs werden von nun an von noch größerem Erfolg gekrönt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24591] = { id = 24591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachablösung", description = "Wenn Blutheft eintrifft, würde ich gern, äh, unter Ausschluss der Öffentlichkeit mit ihm sprechen. Könnt Ihr mich begleiten um sicherzustellen, dass alles im Lot bleibt? Dieser Blutheft ist, äh, er ist... er ist unberechenbar.\n\n<Gar'dul versucht, seine Fassung zurückzugewinnen.>\n\nTrefft mich oben auf dem nördlichen Turm und wir sprechen gemeinsam mit Blutheft.", sourceObjective = "Geht auf die Spitze des nördlichen Turms in Ödnisfeste und helft Kriegsfürst Blutheft dabei, Gar'dul seines Kommandos zu \"entheben\".", sourceObjectiveStatus = "unverified-source-field" }
quests[24592] = { id = 24592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat an der Witterfront", description = "Lord Godfrey hat König Graumähne an der Witterfront gefangen genommen!\n\nEr konnte die beiden Fürsten aus dem Osten überzeugen, sich seinem Plan anzuschließen. Der Narr scheint zu denken, dass er eine Vereinbarung mit den Verlassenen treffen kann, wenn er ihnen Graumähne überlässt.\n\nHört genau zu, {name}. Wir müssen diese Angelegenheit mit so wenig Blutvergießen wie möglich klären.\n\nMit diesem Trank könnt Ihr Euch unerkannt hineinschleichen. Ermordet die verräterischen Fürsten, bevor die Dinge vollkommen außer Kontrolle geraten!", sourceObjective = "Trinkt Krennans Tarnungstrank an der Witterfront und tötet Baron Ashbury und Lord Walden.", progress = "Seid vorsichtig, {name}.", completion = "Ich wünschte, wir hätten es anders lösen können, {name}. Lasst uns sichergehen, dass wir die Sache ohne weiteres Blutvergießen beilegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24593] = { id = 24593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weder Mensch noch Tier", description = "Es ist Zeit, {name}. Diese… Alchemie, die die Bestie in Euch zügelt, hält nicht mehr lange an.\n\nDie ersten verfluchten Worgen waren Nachtelfdruiden, genau wie unsere neuen Verbündeten. Sie haben dem Gleichgewicht, das der Rest ihres Volkes ehrt, den Rücken gekehrt und zugelassen, dass die Bestie in ihrem Inneren die Kontrolle über ihren Verstand übernimmt.\n\nDaher ist es nur Recht, dass ihre Brüder und Schwestern uns von diesem Fluch befreien werden. Geht, {class}. Trinkt von den Wassern des Tal'doren und schließt Frieden mit Euch selbst.", sourceObjective = "Trinkt vom Brunnen der Ruhe, dem Brunnen des Gleichgewichts und dem Brunnen des Zorns.", completion = "Also ist es vollbracht, {name}. Ihr gehört jetzt zu uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[24594] = { id = 24594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wachen des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24595] = { id = 24595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Sobald die Klinge wiederhergestellt ist, zeigt sie Caladis Prunkspeer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24596] = { id = 24596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24597] = { id = 24597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Abgesandten von Sturmwind", description = "Möchtet Ihr für den Abgesandten von Sturmwind einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt dem Abgesandten Audwin Alston in Sturmwind einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24598] = { id = 24598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24601] = { id = 24601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Alptraumnarbe", description = "Das bestätigt es. Die Überwucherung hier wird nicht nur von der Fülle der Energie verursacht.\n\nVersteht Ihr? Das geht über das, was in den Höhlen des Wehklagens geschehen ist, hinaus. In den Landen, in denen wir uns befinden, muss sich ein Riss in den Alptraum aufgetan haben. Wenn ich daran denke, dass das mein Fehler ist...\n\nIch werde nicht länger an den Wundrändern herumkratzen. Geht nach Westen ins Zentrum der Überwucherung und trefft mich dort. Wir werden dieser Verderbnis auf den Grund gehen und ihr ein Ende setzen!", sourceObjective = "Helft Naralex, die Alptraumnarbe zu schließen.", progress = "Wir dürfen dem Alptraum nicht erlauben, sich noch weiter in der Welt auszubreiten!", completion = "Wir haben es geschafft! Die Verbindung des Alptraums zu dieser Welt wurde gekappt. Der Rest des Landes ist vor dem Eindringen sicher und im Laufe der Zeit werden die Anomalien hier auch wieder dem Naturgleichgewicht unterworfen.\n\nIch kann Euch nicht genug danken, {name}. Ihr habt geholfen, die Ordnung hier wiederherzustellen, und mir dadurch die Gelegenheit gegeben, meine törichten Taten wieder gutzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24602] = { id = 24602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Ruhe gebettet", description = "Bei unserer überstürzten Flucht haben wir die Ruhestätten unserer Vorfahren gestört, {name}. Eine Todsünde sozusagen.\n\nEs ist Tradition, ein kleines Andenken in der flachen Erde auf dem Grab eines Einwohners von Gilneas zu hinterlassen. Als die Leute panisch aus diesen Tunneln geflohen sind, wurden diese Andenken freigelegt. Das hat die Geister der Verstorbenen erzürnt.\n\nFindet diese Andenken und bringt sie mir. Wir werden dafür sorgen, dass die Toten zu ihrem ewigen Schlaf zurückkehren.", sourceObjective = "Besorgt 5 freigelegte Andenken.", progress = "Ihr seid zurück, {name}.", completion = "Danke, {name}. Hoffen wir, dass es funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[24603] = { id = 24603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist nie genug", description = "Für eine Weile dachte ich, mein Hass hätte sich gelegt. Meine Frau wurde zur letzten Ruhe gebettet, ein letztes Blutopfer ihrer Mörder, um ihre gequälte Seele zu beruhigen. Ich dachte, Frieden würde mir gefallen.\n\nIch habe mich geirrt.\n\nIch werde nicht ruhen, bis auch der letzte dreckige, quiekende, mordende Stacheleber tot und zerschmettert daliegt! Ich kann sie aber mit meinen eigenen Händen nicht schnell genug töten. Geht und tötet noch mehr für mich, {race}.", sourceObjective = "Tötet 13 Stacheleber der Klingenmähnen.", completion = "Gut. Nehmt Eure Belohnung; das ist erst der Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[24604] = { id = 24604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorge um Mankrik", description = "Ich möchte Euch um einen Gefallen bitten, {class}.\n\nEin Krieger namens Mankrik ist vor nicht allzu langer Zeit auf seiner einsamen Reise durch unser Lager gezogen. Seine Frau wurde von den Stachelebern vor langer Zeit getötet und ihn dürstet immer noch nach Rache. Ich kann seine Augen nicht vergessen... in ihnen brannte ständig unverhohlener Hass.\n\nWir haben nicht lange miteinander gesprochen, aber ich ertrage den Gedanken nicht, dass er da draußen ganz alleine ist. Bitte bringt dies zu Mankrik und sagt ihm, dass es von mir stammt...", sourceObjective = "Bringt Mahkas Geschenk zu Mankrik südlich der Flammensteinspitze.", progress = "<Mankrik knurrt.>\n\nWas ist? Ich bin beschäftigt.", completion = "Mahka hat Euch geschickt?\n\n<Manriks Wut ebbt einen Moment lang ab.>\n\nDas ist eine kleine Aufmunterung. Aber nichts kann mich trösten, solange ich hier noch nicht fertig bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[24606] = { id = 24606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des Brachlands", description = "Dieser hellrote Stein, den Ihr den Klauen eines Stachelebers entrissen habt, wurde sorgfältig in die Form eines großen Ebers geschnitzt, aus dessen Rücken Dornenranken sprießen. Seine Oberfläche ist glatt und abgenutzt.\n\nHaben die Stacheleber ihn hergestellt? Wenn Ihr weitere Steine findet, kann Euch vielleicht einer der Schamanen an der Flammensteinspitze mehr über sie erzählen.", sourceObjective = "Findet 6 Blutsplitterschmuckstücke bei Stachelebern der Klingenmähnen.", progress = "Ja?", completion = "Das sind Blutsplitter! Früher fand man sie überall im Brachland.\n\nMan sagt, dass sie aus dem Blut von Agamaggan geformt wurden, dem großen Halbgott, von dem die Stacheleber abstammen. Ich wusste, dass die Stacheleber viel Wert auf sie legen, aber niemand hätte gedacht, sie würden sich die Zeit nehmen und sich die Mühe machen, so etwas daraus zu schnitzen...\n\nVielleicht gibt es hier noch mehr zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24607] = { id = 24607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Nortet im Osten.", sourceObjective = "Trefft Nortet auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nObwohl, Ihr seht aus, als wärt Ihr gut in Form. Ruhige Hände. Scharfe Augen. Vielleicht wird aus Euch noch ein echter {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24608] = { id = 24608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quetschzahn", description = "Ich schere mich nicht länger um Ehre und Ruhm, {class}. Mich interessiert nur, dass die Stacheleber sterben - egal wie und durch wen.\n\nQuetschzahn, der Häuptling dieser dreckigen Klingenmähnen, sitzt im Nordwesten auf einem Hügel in seinem Bau. Beendet sein Leben.\n\nIch gedenke, hierzubleiben und diese Leichen aufeinanderzustapeln, bis dieses Ungeziefer mir nicht mehr quiekend aus dem Kral entgegenspringt...", sourceObjective = "Tötet Quetschzahn.", completion = "Gut. Gut! Sie werden alle sterben! Ihre Häuptlinge, ihre Frauen, ihre Kinder und ihre widerlichen Haustiere!", sourceObjectiveStatus = "unverified-source-field" }
quests[24609] = { id = 24609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für einen Lord von Eisenschmiede", description = "Möchtet Ihr für Muradin Bronzebart einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Muradin Bronzebart in Eisenschmiede einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24610] = { id = 24610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für die Hohepriesterin von Elune", description = "Möchtet Ihr für die Hohepriesterin von Elune einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, sie wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Tyrande Wisperwind in Darnassus einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24611] = { id = 24611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Propheten", description = "Möchtet Ihr für den Propheten der Exodar einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Prophet Velen in der Exodar einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24612] = { id = 24612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Abgesandten von Orgrimmar", description = "Möchtet Ihr für den Abgesandten von Orgrimmar einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt dem Abgesandten Drunzek Schädelband in Orgrimmar einen hübschen Glücksbringerarmreif.", progress = "Was gibt es, {class}?", completion = "Die Horde hat über die Jahre hinweg Stand gehalten. Unsere Feinde glauben, uns brechen zu können, aber unsere Horde ist stärker als sie denken.\n\nWisst Ihr, warum?\n\nWeil wir eine Familie sind. Dieses Geschenk beweist das. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24613] = { id = 24613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für die Bansheekönigin", description = "Möchtet Ihr für die Bansheekönigin einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, sie wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Fürstin Sylvanas Windläufer in Unterstadt einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24614] = { id = 24614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Oberhäuptling", description = "Möchtet Ihr für den Oberhäuptling einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Baine Bluthuf in Donnerfels einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24615] = { id = 24615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Lordregenten von Quel'Thalas", description = "Möchtet Ihr für den Lordregenten von Quel'Thalas einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Lor'themar Theron in Silbermond einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24616] = { id = 24616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolger abschütteln", description = "Ihr müsst so viele Fragen haben, {name}. Und Ihr werdet auch bald Antworten darauf erhalten.\n\nIch weiß, warum Ihr hier seid und wonach Ihr sucht.\n\nIch kann Euch nicht dahin führen, solange der Feind Euch folgt.\n\nEine von Sylvanas Späherinnen ist Euch auf den Fersen. Ihr dürft den Verlassenen auf keinen Fall den Ort zeigen, den Ihr sucht. Nehmt diesen Talisman und geht einfach die Straße direkt nördlich von hier entlang.\n\nLasst zu, dass die Späherin Euch in ihre Falle lockt, und nutzt dann die Macht des Talismans, um Euch zu befreien und einen Gegenangriff zu starten.", sourceObjective = "Verwendet Belysras Talisman, um die dunkle Späherin zu besiegen.", progress = "Ist es vollbracht, {name}?", completion = "Gut gemacht, {name}. Die Späherin hatte nicht die geringste Chance gegen Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24617] = { id = 24617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal'doren, die Heimstatt in der Wildnis", description = "Es gibt andere wie Euch, {name}. Und auch sie waren verwirrt und wussten nicht, wohin.\n\nEs gibt einen Ort, an den Ihr gehört. Tal'doren, die Heimstatt in der Wildnis, war einst das Zuhause eines Druidenordens, der die Form von Wölfen annehmen konnte.\n\nDort findet Ihr die Antworten, die Ihr sucht. Und dort wird Euch jemand helfen können. Ein alter Freund.", sourceObjective = "Sprecht mit Darius Crowley beim Tal'doren im Herzen des Schwarzforsts.", completion = "Es geht Euch gut, {name}! Ich habe schon so lange auf diesen Tag gewartet. Es ist eine wahre Freude, Euch zu sehen, Freund.\n\nIch habe gehört, was Ihr getan habt, und ich bin Euch so dankbar… besonders für Lorna. Sie ist alles, was mir geblieben ist. Ich lasse sie sofort herholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24618] = { id = 24618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anspruch auf die Kriegsnarbe erheben", description = "Wir haben die Allianz hier durch unseren Kampf zum Stillstand gebracht, obwohl das Land unter unseren Füßen auseinanderbricht. Im Osten findet Ihr die Kriegsnarbe, eine weite Schneise stark geschwächten Landes. Sie ist kaum mehr als eine Linie im Sand, aber sie muss UNSERE Linie werden.\n\nIm Zentrum der Narbe befindet sich eine Flagge, die anzeigt, wer gerade über sie herrscht. Findet die Flagge.\n\nWenn sie nicht bereits uns gehört, nehmt sie für die Horde ein - das wird den Kampf zu unseren Gunsten beeinflussen. Untersucht die Narbe und tötet jeden, den Ihr darin findet!", sourceObjective = "Geht zu der Kriegsnarbe. Findet die Flagge und tötet 10 Soldaten der Vorhut der Triumphfeste.\n\nDie Flagge einzunehmen wird allen Hordespielern in der Narbe einen Vorteil im Kampf gewähren.", completion = "Ausgezeichnet! Ihr seid die Art {class}, die ich mag, {name}.\n\nMit Eurer Hilfe werden wir diese Eindringlinge zurück ins Meer treiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24619] = { id = 24619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graus Anatomie", description = "Ich wollte schon immer mal versuchen, eine Monstrosität herzustellen. Es sieht recht einfach aus, aber Ihr wisst ja, wie es ist, wenn man etwas aus einem Buch gelernt hat. Es gibt nichts Besseres, als etwas selbst zu tun!\n\nZunächst brauche ich dafür Teile. Viele Teile. Und Ihr werdet sie mir besorgen.\n\nIhr müsst nicht wählerisch sein: menschlich, orcisch... Das ist egal. Teile sind Teile.\n\nIhr müsst nur darauf achten, dass die Leichen, die ihr aberntet, aus der Kriegsnarbe stammen, damit ich weiß, dass sie frisch sind.\n\n<Calder drückt Euch eine verrostete, blutbeschmierte Knochensäge in die Hand und lächelt entwaffnend.>", sourceObjective = "Benutzt Calders Knochensäge an Leichen in der Kriegsnarbe und sammelt 15 abgetrennte Gliedmaßen ein.", progress = "Habt Ihr meine Teile bekommen? Lasst mal sehen!", completion = "<Calder späht in den Sack mit den Gliedmaßen und leckt sich mit seiner trockenen, schwarzen Zunge über die Lippen.>\n\nAu weia. Ist das aufregend.\n\n Seid Ihr nicht aufgeregt, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24620] = { id = 24620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen sind Herzen", description = "Diese Teile – herrlich! Muskeln und Sehnen und Finger und Zehen... Jetzt habe ich SO einen Hunger.\n\nAber erst kommt die Arbeit. Sobald ich diesen Haufen Teile zusammengenäht habe, benötige ich ein Herz, das stark genug ist, Schlick durch dieses Durcheinander von Venen zu pumpen. Ich würde ja mein eigenes Herz benutzen, aber das ist eine verschrumpelte Hülle, die wie eine Rübe aussieht.\n\nNein, ich brauche wahre Stärke. Besorgt mir ein Kodoherz von einem dieser riesigen Landbeberbullen südlich der Kriegsnarbe.", sourceObjective = "Tötet einen Landbeberbullen südlich der Kriegsnarbe und besorgt ein gigantisches Kodoherz.", progress = "Habt doch ein Herz, {name}. Alles, was Ihr wirklich braucht, ist ein Herz.", completion = "<Calder packt das riesige Herz mit beiden Händen, drückt es und lauscht, wie die Kammern schlürfen und schmatzen.>\n\n<Die wächserne Maske seines Gesichts teilt sich zu einem breiten, kindlichen Grinsen.>\n\nEs ist so wichtig, dass man seine Arbeit liebt, findet Ihr nicht auch, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24621] = { id = 24621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clever ist clever", description = "Meine Monstrosität nimmt langsam Gestalt an! Nun muss ich nur noch ihren Schädel mit etwas Sinnvollem ausstopfen.\n\nIch spreche von einem Gehirn, {name}. Und da werde ich dann wählerisch. Die Vermonstrositierung verursacht erheblichen Hirnschaden, also sollte man mit jemandem anfangen, der intelligent ist.\n\nEiner der Allianzoffiziere sollte reichen. Findet einen der Hauptleute auf der anderen Seite der Kriegsnarbe und versucht, die Ware nicht zu beschädigen, während Ihr ihn tötet.", sourceObjective = "Tötet einen Hauptmann der Triumphfeste auf der gegenüberliegenden Seite der Kriegsnarbe und besorgt ein frisches Hirn.", progress = "Hiiiiiiiirrrrrrrrrrn...", completion = "<Calder hält das Hirn in seiner ausgestreckten Hand und zieht gleichzeitig ein blutverschmiertes Werkzeug aus seinem Gürtel.>\n\nWunderbare Arbeit! Das Geheimnis hier ist, das reptilische Nervensystem nicht zu verletzen, während man die höhere Erkenntnisfähigkeit entfernt. Schließlich können wir nicht zulassen, dass unser neuer Freund ein Gewissen bekommt oder sich daran erinnert, dass er zur Allianz gehört... \n\n<Calder bohrt und schnippelt an dem Hirn herum und entfernt große Stücke.>\n\nUnd... schon sind wir fertig! Wunderbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24622] = { id = 24622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Trolls bester Freund", description = "Wenn Ihr etwas zu tun sucht, wir hätten da noch ein paar Raptoren, die zu den Ställen gebracht werden müssen. Begebt Euch zu der Insel südlich von hier und trefft Euch mit den Pflegern, die werden Euch dann weiterhelfen.\n\nSie würden sich bestimmt auch über ein wenig Hilfe freuen. Ihr müsst die Liebe verbreiten, wisst Ihr?", sourceObjective = "Redet mit Kijara an der Blutkrallenküste.", completion = "Schön, hier draußen mal neue Gesichter zu sehen, Mann. Wir sind doch recht isoliert, seit wir Orgrimmar verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24623] = { id = 24623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kleinen", description = "Ich habe etwas ziemlich Wichtiges, bei dem ich Eure Hilfe brauche, wenn Ihr bereit seid, Mann.\n\nUnsere Jungtiere werden von jemandem auf der Nachbarinsel geraubt. Zuerst dachte ich ja, sie wären uns davongelaufen oder die Natur hätte sie sich genommen, aber mittlerweile fehlen mehr als ein Dutzend der kleinen Racker.\n\nBitte begebt Euch nach Zalazanes Sturz im Nordwesten und weist den Jungtieren den Weg zurück. Die armen Kleinen.", sourceObjective = "Verwendet die Blutkrallenpfeife, um 12 verlorene Brutkrallenjungtiere zu retten.", completion = "Ich danke Euch sehr! Sie können wild werden, wenn man sie provoziert, aber meist wissen sie es halt nicht besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[24624] = { id = 24624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnade für die Verirrten", description = "Der Übeltäter, der unsere Raptoren geklaut hat, muss sie mit irgendeiner Art von Magie verderbt haben. Jetz' da sie mit dieser Verderbnis herangewachsen sind, befürchte ich, dass wir kaum was anderes für sie tun können, außer ihnen einen friedlichen Tod zu gewähren. Geht zu Zalazanes Sturz nordwestlich von hier und übernehmt diese Pflicht.\n\nIch hoffe nur, Ihr habt den nötigen Mumm. Ich glaub' nich', dass ich mich dazu überwinden könnte, auch wenn ich weiß, dass es nötig ist.", sourceObjective = "Tötet 8 verderbte Blutkrallenraptoren.", completion = "Danke, {class}.\n\nEs benötigt tapfere und entschlossene Leute wie Euch, um die Dunkelspeere wieder groß zu machen. Ich hoffe, dass noch mehr Leute kommen, die nur halb so entschlossen sind.", sourceObjectiveStatus = "unverified-source-field" }
